__CR('t:fp',[{"t":"함수형 사고","l":[{"t":"핵심 개념","q":[{"t":"choice","k":"개념","q":"같은 입력에는 항상 같은 결과를 내고 부작용이 없는 함수는?","o":["클래스 생성자","순수 함수","콜백만","정적 전역 함수"],"a":1,"ex":"순수 함수는 예측 가능하고 테스트하기 쉽다."},{"t":"choice","k":"개념","q":"함수를 값처럼 인자로 받거나 돌려줄 수 있는 함수는?","o":["고차 함수","재귀 함수만","익명 함수만","저수준 함수"],"a":0,"ex":"map·filter 가 대표적인 고차 함수다."},{"t":"choice","k":"개념","q":"데이터를 바꾸지 않고 새 값을 만드는 성질은?","o":["전역 상태(global state)","동시성","가변성","불변성(immutability)"],"a":3,"ex":"불변성은 버그와 예측 불가를 줄여준다."},{"t":"choice","k":"개념","q":"이름 없이 즉석에서 정의하는 함수를 뭐라 하나요?","o":["클래스(class)","모듈","람다(익명 함수)","정적 클래스 메서드"],"a":2,"ex":"람다 x => x*2 처럼 간단히 쓴다."}],"th":{"sum":"함수형 사고의 핵심은 부작용 없는 **순수 함수**와 데이터를 바꾸지 않는 **불변성**이며, `map`·`filter`·`reduce` 같은 도구로 데이터를 선언적으로 다룬다.","body":[{"h":"핵심 개념","t":"같은 입력에는 항상 같은 결과를 내고 외부 상태를 바꾸지 않는(부작용 없는) 함수를 순수 함수(pure function)라 한다. 함수를 값처럼 인자로 받거나 반환할 수 있는 함수는 고차 함수(higher-order function)다. 데이터를 직접 바꾸지 않고 항상 새 값을 만들어내는 성질이 불변성(immutability)이고, 이름 없이 즉석에서 정의하는 함수는 람다(lambda, 익명 함수)다."},{"h":"함수형 도구","t":"map은 배열의 각 원소에 함수를 적용해 같은 길이의 새 배열을 만든다. filter는 조건(술어)에 맞는 원소만 남겨 새 배열을 만든다. reduce는 원소들을 누적기로 접어 하나의 값(합계 등)으로 합친다. 세 도구 모두 원본을 바꾸지 않고 새 결과를 반환해 불변성을 지킨다."}],"code":{"c":"const nums = [1, 2, 3, 4];\nnums.map(x => x * 2);        // [2, 4, 6, 8]\nnums.filter(x => x % 2 === 0); // [2, 4]\nnums.reduce((a, x) => a + x, 0); // 10","cap":"map·filter·reduce로 배열을 선언적으로 처리"},"key":["순수 함수 = 같은 입력→같은 출력 + 부작용 없음","고차 함수 = 함수를 인자/반환값으로, 익명 함수 = 람다","map=각 원소 변환, filter=조건 선택, reduce=하나로 합침 (모두 불변)"]}},{"t":"함수형 도구","q":[{"t":"choice","k":"도구","q":"배열의 각 원소를 변환해 새 배열을 만드는 함수형 도구는?","o":["for","map","if","push"],"a":1,"ex":"map 은 원본을 바꾸지 않고 새 배열을 반환한다."},{"t":"choice","k":"개념","q":"함수형 프로그래밍이 최대한 피하려는 것은?","o":["부작용(side effect)","순수 함수(pure function)","불변성","재사용"],"a":0,"ex":"외부 상태를 바꾸는 부작용을 줄이는 게 핵심이다."},{"t":"choice","k":"도구","q":"조건에 맞는 원소만 남겨 새 배열을 만드는 것은?","o":["map","reduce","flatMap","filter"],"a":3,"ex":"filter 는 조건이 참인 원소만 골라낸다."},{"t":"choice","k":"도구","q":"배열의 모든 원소를 하나의 값으로 합치는 것은?","o":["map","filter","reduce","find"],"a":2,"ex":"reduce 로 합계·곱 등 누적 결과를 만든다."}],"th":{"sum":"함수형 사고의 핵심은 부작용 없는 **순수 함수**와 데이터를 바꾸지 않는 **불변성**이며, `map`·`filter`·`reduce` 같은 도구로 데이터를 선언적으로 다룬다.","body":[{"h":"함수형 도구","t":"map은 배열의 각 원소에 함수를 적용해 같은 길이의 새 배열을 만든다. filter는 조건(술어)에 맞는 원소만 남겨 새 배열을 만든다. reduce는 원소들을 누적기로 접어 하나의 값(합계 등)으로 합친다. 세 도구 모두 원본을 바꾸지 않고 새 결과를 반환해 불변성을 지킨다."},{"h":"핵심 개념","t":"같은 입력에는 항상 같은 결과를 내고 외부 상태를 바꾸지 않는(부작용 없는) 함수를 순수 함수(pure function)라 한다. 함수를 값처럼 인자로 받거나 반환할 수 있는 함수는 고차 함수(higher-order function)다. 데이터를 직접 바꾸지 않고 항상 새 값을 만들어내는 성질이 불변성(immutability)이고, 이름 없이 즉석에서 정의하는 함수는 람다(lambda, 익명 함수)다."}],"code":{"c":"const nums = [1, 2, 3, 4];\nnums.map(x => x * 2);        // [2, 4, 6, 8]\nnums.filter(x => x % 2 === 0); // [2, 4]\nnums.reduce((a, x) => a + x, 0); // 10","cap":"map·filter·reduce로 배열을 선언적으로 처리"},"key":["순수 함수 = 같은 입력→같은 출력 + 부작용 없음","고차 함수 = 함수를 인자/반환값으로, 익명 함수 = 람다","map=각 원소 변환, filter=조건 선택, reduce=하나로 합침 (모두 불변)"]}},{"t":"직접 짜 보기 — 무엇을 할지 대신 무엇인지 적기","th":{"sum":"함수형은 **'어떻게 하라' 대신 '무엇인가' 를 적는 것**이다. 그러면 읽는 사람이 순서를 따라갈 필요가 없다.","body":[{"h":"명령형은 순서, 선언형은 관계","t":"`for` 로 인덱스를 올리며 배열에 넣는 코드는 '어떻게' 를 적는다. `map` 은 '각 원소가 이렇게 바뀐 것' 이라는 관계를 적는다. 뒤쪽이 짧아서 좋은 게 아니라, 중간 상태가 없어서 읽기 쉽다."},{"h":"중간 변수를 없애면 버그가 줄어든다","t":"`i`, `sum`, `tmp` 같은 변수는 잘못 쓸 여지가 있는 자리다. 그 자리가 없으면 그 버그도 없다."},{"h":"작은 함수를 이어 붙인다","t":"거르고 → 바꾸고 → 모으는 세 단계를 각각 이름 붙여 두면, 각 단계를 따로 시험하고 따로 재사용할 수 있다."},{"h":"만능은 아니다","t":"성능이 극한으로 중요한 자리나 한 번에 큰 배열을 여러 번 순회하는 곳에서는 반복문이 나을 수 있다. 기본은 선언형으로 두되, 재 보고 필요할 때 바꾼다."}],"code":{"c":"// 명령형\nlet out = [];\nfor (let i = 0; i < xs.length; i++)\n  if (xs[i] > 0) out.push(xs[i] * 2);\n\n// 선언형\nxs.filter(x => x > 0).map(x => x * 2)","cap":"순서 대신 관계를 적는다"},"key":["'어떻게' 대신 '무엇인가'","중간 변수가 없으면 그 버그도 없다","작은 함수를 이어 붙인다"]},"q":[{"k":"evenSquares · 거르고 바꾸기","cat":"internals","q":"짝수만 남겨 <b>제곱</b>한 배열을 돌려주세요. 원본은 <b>바뀌면 안 된다</b>.","src":"function evenSquares(xs) {\n  for (let i = 0; i < xs.length; i++) xs[i] = xs[i] * xs[i];\n  return xs.filter(x => x % 2 === 0);\n}\n","sol":"function evenSquares(xs) {\n  return xs.filter(x => x % 2 === 0).map(x => x * x);\n}\n","ex":"먼저 제곱해 버리면 홀수의 제곱도 홀수라 결과는 우연히 비슷해 보이지만, 원본 배열이 통째로 바뀐다. 부르는 쪽은 자기 데이터가 달라진 줄 모르고 계속 쓰게 돼요 — `filter`·`map` 은 언제나 새 배열을 만든다.","t":"code","run":"js","tests":[{"in":"evenSquares([1,2,3,4])","out":"[4,16]"},{"in":"(() => { const a = [1,2,3]; evenSquares(a); return a; })()","out":"[1,2,3]"},{"in":"evenSquares([])","out":"[]"}],"edge":[{"in":"evenSquares([1,3,5])","out":"[]"},{"in":"evenSquares([0,2])","out":"[0,4]"}]},{"k":"countBy · 세는 일도 관계로","cat":"internals","q":"값마다 <b>몇 번 나왔는지</b>를 담은 객체를 돌려주세요.","src":"function countBy(xs) {\n  const out = {};\n  for (const x of xs) out[x] = 1;\n  return out;\n}\n","sol":"function countBy(xs) {\n  return xs.reduce((acc, x) => { acc[x] = (acc[x] || 0) + 1; return acc; }, {});\n}\n","ex":"`= 1` 로 덮어쓰면 몇 번 나왔든 전부 1 이 된다 — 결과의 모양은 맞아서 눈으로 훑으면 지나가기 쉬워요. 세는 일은 '이전 값 + 1' 이라는 관계라, 이전 값을 반드시 읽어야 한다.","t":"code","run":"js","tests":[{"in":"countBy(['a','b','a'])","out":"{a:2,b:1}"},{"in":"countBy([])","out":"{}"},{"in":"countBy(['x'])","out":"{x:1}"}],"edge":[{"in":"countBy([1,1,1])","out":"{1:3}"},{"in":"countBy(['a','b'])","out":"{a:1,b:1}"}]},{"k":"pipeline · 단계를 이어 붙이기","cat":"internals","q":"함수 배열을 받아 <b>앞에서부터 차례로</b> 적용하는 함수를 돌려주세요.","src":"function pipeline(fns) {\n  return x => fns.reduceRight((v, f) => f(v), x);\n}\n","sol":"function pipeline(fns) {\n  return x => fns.reduce((v, f) => f(v), x);\n}\n","ex":"`reduceRight` 는 뒤에서부터 적용한다 — 더하고 곱하기와 곱하고 더하기는 결과가 다르니 조용히 틀린 값이 나와요. 파이프라인은 적힌 순서대로 흐른다는 약속이고, 그 약속이 깨지면 읽는 사람이 코드를 못 믿는다.","t":"code","run":"js","tests":[{"in":"pipeline([x => x + 1, x => x * 10])(0)","out":"10"},{"in":"pipeline([x => x * 10, x => x + 1])(0)","out":"1"},{"in":"pipeline([])(5)","out":"5"}],"edge":[{"in":"pipeline([x => x + 1])(1)","out":"2"},{"in":"pipeline([String, s => s.length])(100)","out":"3"}]}]}],"ord":0},{"t":"순수함수, 불변성, 그리고 부수효과","l":[{"t":"순수함수란 무엇인가","q":[{"t":"choice","k":"fp-pure-def1","q":"순수함수의 정의로 가장 정확한 것은?","ex":"순수함수의 조건은 참조 투명성(같은 입력 -&gt; 같은 출력)과 관찰 가능한 부수효과의 부재, 이 두 가지뿐이다. 문법이나 인자 개수는 순수성과 아무 관련이 없다. 함수 내부에서 변수를 선언하고 사용하는 것도 얼마든지 허용된다.","o":["화살표 함수 문법으로 작성된 모든 함수","같은 입력에 항상 같은 출력을 내고, 관찰 가능한 부수효과가 없는 함수","함수 안에서 지역 변수를 선언하지 않고 인자만 가지고 계산하는 함수","인자를 하나만 받는 함수"],"a":1},{"t":"input","k":"fp-pure-term1","q":"같은 표현식을 그 결과값으로 바꿔 써도 프로그램의 의미가 변하지 않는 성질을 무엇이라 하는가? (한국어 다섯 글자, 예: OO OOO)","ex":"참조 투명성은 f(2)가 항상 4라면 코드 어디서든 f(2)를 4로 치환해도 동작이 같다는 성질이다. 순수함수는 이 성질을 만족하므로 캐싱(메모이제이션)이나 재배치 같은 최적화가 안전해진다. 부수효과가 있으면 치환이 성립하지 않는다.","a":["참조 투명성"]},{"t":"choice","k":"fp-pure-local1","q":"아래 함수 sum은 내부에서 total과 i를 계속 바꾼다. 이 함수의 순수성에 대한 설명으로 옳은 것은?","ex":"total과 i는 호출할 때마다 새로 만들어지고 함수가 끝나면 사라지는 지역 변수라, 그 변경은 외부에서 전혀 관찰되지 않는다. sum은 같은 배열에 항상 같은 합을 돌려주고 nums를 변경하지도 않는다. 따라서 반복문과 재할당을 쓰더라도 순수함수다.","code":"function sum(nums) {\n  let total = 0;\n  for (let i = 0; i &lt; nums.length; i++) {\n    total += nums[i];\n  }\n  return total;\n}","o":["nums를 읽었으므로 인자 접근 자체가 부수효과라 불순하다","지역 변수를 변경했으므로 부수효과가 있어 불순하다","반복문을 썼으므로 함수형이 아니어서 불순하다","지역 변수 변경은 밖에서 안 보여 순수하다"],"a":3},{"t":"choice","k":"fp-pure-impure1","q":"다음 중 순수하지 않은 함수는?","ex":"Date.now()는 호출 시점마다 다른 값을 돌려주므로 같은 인자에 같은 출력을 보장하지 못한다. 나머지 셋은 인자만 보고 새 값을 만들어 반환하며 원본을 건드리지 않는다. 시각이 필요하다면 인자로 주입받아 순수하게 만들 수 있다.","o":["(xs) =&gt; xs.filter(x =&gt; x &gt; 0)","(a, b) =&gt; a * b","(name) =&gt; `${name} 님, 지금은 ${Date.now()}`","(user) =&gt; ({ ...user, active: true, seen: 0 })"],"a":2},{"t":"choice","k":"fp-pure-benefit1","q":"순수함수가 테스트하기 쉬운 가장 직접적인 이유는?","ex":"순수함수는 결과가 오직 인자에만 의존하므로, 입력을 만들고 반환값을 비교하는 것만으로 테스트가 끝난다. DB나 전역 상태를 세팅하거나 정리할 필요가 없어 목(mock)도 거의 필요 없다. 속도나 예외 여부는 순수성이 보장해 주는 것이 아니다.","o":["인자만 준비하면 결과를 검증할 수 있고, 외부 상태를 준비하거나 되돌릴 필요가 없다","순수함수는 타입 검사를 자동으로 통과하므로 검증 코드를 쓸 필요가 없기 때문","순수함수는 실행 속도가 더 빠르기 때문이다","순수함수는 예외를 던지지 않기 때문이다"],"a":0}],"th":{"sum":"순수함수는 같은 입력에 항상 같은 출력을 내고 관찰 가능한 부수효과가 없는 함수다. 부수효과를 경계 바깥으로 밀어내고 데이터를 불변으로 다루면 코드는 예측 가능하고 테스트하기 쉬워진다.","body":[{"h":"순수함수의 두 가지 조건","t":"첫째, 참조 투명성이다. 같은 인자를 넣으면 언제 어디서 호출하든 항상 같은 값을 돌려준다. 둘째, 관찰 가능한 부수효과가 없다. 함수 내부에서 지역 변수를 만들고 그 값을 계속 바꾸더라도, 그 변화가 함수 밖에서는 전혀 보이지 않으므로 순수성은 깨지지 않는다."},{"h":"무엇이 부수효과인가","t":"콘솔 출력이나 파일 쓰기 같은 I/O, 전역 변수 변경, DOM 조작, 인자로 받은 객체나 배열의 내용 변경이 대표적인 부수효과다. 현재 시각을 읽는 Date.now()나 Math.random()도 호출할 때마다 결과가 달라지므로 순수하지 않다. 이런 값들은 함수 안에서 직접 읽지 말고 인자로 주입받으면 그 함수는 다시 순수해진다."},{"h":"불변성과 const의 오해","t":"const는 변수 바인딩의 재할당만 막을 뿐, 그 변수가 가리키는 객체의 내부 프로퍼티 변경은 전혀 막지 못한다. Object.freeze는 실제로 프로퍼티 변경을 막지만 얕은 동결이라 중첩된 객체 안쪽까지는 보호하지 못한다. 그래서 상태를 갱신할 때는 원본을 고치는 대신 스프레드 문법 등으로 새 객체나 새 배열을 만들어 돌려주는 방식을 쓴다."}],"code":{"c":"// 불순: 인자로 받은 배열을 직접 변경\nfunction addItemBad(cart, item) {\n  cart.push(item);\n  return cart;\n}\n\n// 순수: 새 배열을 반환, 원본은 그대로\nfunction addItem(cart, item) {\n  return [...cart, item];\n}\n\nconst cart = [{ id: 1 }];\nconst next = addItem(cart, { id: 2 });\nconsole.log(cart.length, next.length); // 1 2","cap":"인자를 변경하는 대신 새 값을 반환하면 호출자는 원본을 계속 신뢰할 수 있다."},"key":["순수함수 = 같은 입력 -> 같은 출력 + 관찰 가능한 부수효과 없음","지역 변수 변경은 외부에서 안 보이므로 순수성을 깨지 않는다","const는 재할당만 막고, Object.freeze는 얕은 동결이다"]}},{"t":"부수효과 다루기","q":[{"t":"choice","k":"fp-side-foreach1","q":"아래 코드에서 doubled에 담기는 값은?","ex":"forEach는 각 원소에 대해 콜백을 실행할 뿐 아무것도 모으지 않고 항상 undefined를 반환한다. 값을 변환해 새 배열을 얻고 싶다면 map을 써야 한다. forEach는 본질적으로 부수효과를 일으키기 위한 메서드다.","code":"const doubled = [1, 2, 3].forEach(n =&gt; n * 2);","o":["undefined","[2, 4, 6]","[1, 2, 3]","12"],"a":0},{"t":"choice","k":"fp-side-list1","q":"다음 중 부수효과가 아닌 것은?","ex":"map은 원본을 그대로 두고 새 배열을 만들어 돌려주므로 함수 밖에서 관찰되는 변화가 없다. 전역 변수 변경, 인자 객체 변경, DOM 조작은 모두 대표적인 부수효과다. 부수효과의 기준은 함수 경계 밖에서 그 변화를 볼 수 있는가이다.","o":["함수 안에서 전역 카운터 변수를 1 증가시킴","받은 배열을 map으로 바꿔 새 배열 반환이다","document.querySelector로 찾은 요소의 텍스트를 바꿈","인자로 받은 배열에 push로 원소를 추가함"],"a":1},{"t":"choice","k":"fp-side-log1","q":"함수 안에 console.log를 한 줄 추가하면 그 함수는 어떻게 되는가?","ex":"console.log는 콘솔이라는 외부 세계에 쓰기를 수행하는 I/O이므로 엄밀히 말하면 함수를 불순하게 만든다. 실무에서는 관대하게 다루기도 하지만, 정의상 부수효과라는 점은 분명히 알아야 한다. 반환값 자체는 그대로 유지된다.","o":["반환값이 조금도 바뀌지 않으므로 여전히 순수한 함수로 볼 수 있다","함수가 undefined를 반환하게 된다","출력이라는 I/O 부수효과가 생기므로 엄밀히는 순수하지 않다","로그 출력은 개발용 도구이므로 순수성을 따질 때 제외하고 보는 것이 관례다"],"a":2},{"t":"choice","k":"fp-side-shell1","q":"\"함수형 코어, 명령형 셸\"이라는 설계 원칙이 뜻하는 것은?","ex":"프로그램이 쓸모 있으려면 결국 화면에 그리거나 파일을 써야 하므로 부수효과를 없앨 수는 없다. 대신 결정 로직을 순수함수로 몰아넣고, 그 결과를 실제로 실행하는 얇은 셸만 불순하게 두는 것이다. 그러면 테스트가 필요한 부분의 대부분이 순수해진다.","o":["말 그대로 모든 I/O를 프로그램에서 완전히 제거해야 비로소 진짜 함수형 프로그램이 된다","부수효과가 있는 함수는 async 로 선언해 비동기로 다뤄야 한다는 원칙","핵심 로직은 클래스로, 나머지는 함수로 작성한다","계산 로직은 순수하게 두고, I/O와 상태 변경은 프로그램 바깥 얇은 층에 모은다"],"a":3},{"t":"input","k":"fp-side-arg1","q":"인자로 받은 객체나 배열을 함수 안에서 직접 고치는 것을 무엇이라 부르는가? (한국어 세 글자, 예: OO OO)","ex":"인자로 받은 객체를 고치면 호출한 쪽의 데이터가 몰래 바뀌므로 추적하기 어려운 버그의 원인이 된다. 이는 대표적인 부수효과이며, 스프레드 문법으로 복사본을 만들어 반환하면 피할 수 있다. 인자 변조 또는 인자 변형이라고도 한다.","a":["인자 변경"]},{"t":"choice","k":"fp-side-inject1","q":"아래 함수를 순수하게 만드는 가장 적절한 방법은?","ex":"난수와 현재 시각은 함수 밖의 세계에서 오는 값이므로, 함수 안에서 직접 읽는 한 결과를 예측할 수 없다. 값을 인자로 주입받으면 함수 자체는 순수해지고, 난수를 만드는 불순한 책임은 호출부 경계로 밀려난다. Date.now()도 똑같이 불순하므로 교체는 해결책이 아니다.","code":"function makeId(prefix) {\n  return prefix + Math.random().toString(16).slice(2);\n}","o":["함수 이름 앞에 pure를 붙여 의도를 표시한다","return 값을 const 변수에 먼저 담았다가 반환한다","난수 값을 두 번째 인자로 주입받아 makeId(prefix, rand) 형태로 바꾼다","Math.random() 대신 Date.now() 를 써서 값이 겹치지 않게 만들어 준다"],"a":2}],"th":{"sum":"순수함수는 같은 입력에 항상 같은 출력을 내고 관찰 가능한 부수효과가 없는 함수다. 부수효과를 경계 바깥으로 밀어내고 데이터를 불변으로 다루면 코드는 예측 가능하고 테스트하기 쉬워진다.","body":[{"h":"순수함수의 두 가지 조건","t":"첫째, 참조 투명성이다. 같은 인자를 넣으면 언제 어디서 호출하든 항상 같은 값을 돌려준다. 둘째, 관찰 가능한 부수효과가 없다. 함수 내부에서 지역 변수를 만들고 그 값을 계속 바꾸더라도, 그 변화가 함수 밖에서는 전혀 보이지 않으므로 순수성은 깨지지 않는다."},{"h":"무엇이 부수효과인가","t":"콘솔 출력이나 파일 쓰기 같은 I/O, 전역 변수 변경, DOM 조작, 인자로 받은 객체나 배열의 내용 변경이 대표적인 부수효과다. 현재 시각을 읽는 Date.now()나 Math.random()도 호출할 때마다 결과가 달라지므로 순수하지 않다. 이런 값들은 함수 안에서 직접 읽지 말고 인자로 주입받으면 그 함수는 다시 순수해진다."},{"h":"불변성과 const의 오해","t":"const는 변수 바인딩의 재할당만 막을 뿐, 그 변수가 가리키는 객체의 내부 프로퍼티 변경은 전혀 막지 못한다. Object.freeze는 실제로 프로퍼티 변경을 막지만 얕은 동결이라 중첩된 객체 안쪽까지는 보호하지 못한다. 그래서 상태를 갱신할 때는 원본을 고치는 대신 스프레드 문법 등으로 새 객체나 새 배열을 만들어 돌려주는 방식을 쓴다."}],"code":{"c":"// 불순: 인자로 받은 배열을 직접 변경\nfunction addItemBad(cart, item) {\n  cart.push(item);\n  return cart;\n}\n\n// 순수: 새 배열을 반환, 원본은 그대로\nfunction addItem(cart, item) {\n  return [...cart, item];\n}\n\nconst cart = [{ id: 1 }];\nconst next = addItem(cart, { id: 2 });\nconsole.log(cart.length, next.length); // 1 2","cap":"인자를 변경하는 대신 새 값을 반환하면 호출자는 원본을 계속 신뢰할 수 있다."},"key":["순수함수 = 같은 입력 -> 같은 출력 + 관찰 가능한 부수효과 없음","지역 변수 변경은 외부에서 안 보이므로 순수성을 깨지 않는다","const는 재할당만 막고, Object.freeze는 얕은 동결이다"]}},{"t":"불변성과 안전한 상태 갱신","q":[{"t":"choice","k":"fp-imm-const1","q":"아래 코드의 실행 결과로 옳은 것은?","ex":"const는 user라는 바인딩에 다른 값을 재할당하는 것만 막을 뿐, 그 객체 내부 프로퍼티 변경은 전혀 막지 않는다. 따라서 age는 정상적으로 21이 된다. user = {} 처럼 재할당을 시도했을 때만 TypeError가 난다.","code":"const user = { name: '민지', age: 20 };\nuser.age = 21;\nconsole.log(user.age);","o":["20이 나온다","SyntaxError로 실행조차 되지 않는다","21이 출력된다","TypeError가 발생한다"],"a":2},{"t":"choice","k":"fp-imm-arr1","q":"배열 메서드 중 원본 배열을 직접 변경하는 것끼리 묶인 것은?","ex":"push, sort, splice, reverse는 원본을 제자리에서 변경하는 메서드다. map, filter, slice, concat 등은 새 배열을 만들어 반환하므로 원본이 안전하다. 정렬을 불변으로 하고 싶다면 [...xs].sort(...) 처럼 복사본을 먼저 만들면 된다.","o":["concat, flat, join","push, sort, splice","reduce, find, includes","map, filter, slice"],"a":1},{"t":"choice","k":"fp-imm-freeze1","q":"Object.freeze에 대한 설명으로 옳은 것은?","ex":"Object.freeze는 얕은 동결이라 obj.a는 못 바꿔도 obj.nested.b는 그대로 바꿀 수 있다. 깊은 불변성이 필요하면 중첩 객체마다 재귀적으로 freeze를 적용해야 한다. const는 재할당만 막을 뿐 동결과는 완전히 다른 개념이다.","o":["최상위 프로퍼티만 동결하는 얕은 동결이라 중첩 객체는 여전히 변경 가능하다","동결된 객체는 읽기도 제한된다","const로 선언된 객체는 자동으로 동결된다","객체와 안에 중첩된 모든 객체까지 재귀적으로 동결해 주는 깊은 동결"],"a":0},{"t":"input","k":"fp-imm-copy1","q":"기존 배열을 바꾸지 않고 원소 하나를 덧붙인 새 배열을 만드는 표현을 완성하라. 빈칸에 들어갈 연산자를 답하라. (기호 세 글자) 예: const next = [ ___xs, item];","ex":"전개(spread) 연산자 ...는 기존 배열의 원소를 새 배열 리터럴 안에 펼쳐 넣는다. 그 결과 원본 xs는 그대로 남고 새 배열만 만들어진다. push와 달리 부수효과가 없어 불변 갱신에 적합하다.","a":["..."]},{"t":"choice","k":"fp-imm-update1","q":"불변 방식으로 객체의 한 필드만 갱신한 코드는?","ex":"스프레드 문법은 기존 프로퍼티를 복사한 새 객체를 만들고 age만 덮어쓰므로 원본 user는 그대로 남는다. Object.assign(user, ...)은 첫 인자를 직접 변경하므로 불변이 아니다. Object.assign({}, user, { age: 21 })처럼 빈 객체를 대상으로 삼아야 안전하다.","o":["const next = { ...user, age: 21 };","const next = Object.assign(user, { age: 21 });","const next = user.age++;","const next = user; next.age = 21;"],"a":0},{"t":"choice","k":"fp-imm-nested1","q":"state.user.profile.city만 불변으로 바꾸려 할 때 올바른 코드는?","ex":"중첩 객체를 불변으로 갱신하려면 바꾸려는 값까지 이어지는 경로의 모든 층을 각각 복사해야 한다. 층을 건너뛰면 zip 같은 형제 프로퍼티가 통째로 사라진다. 깊이가 깊어지면 Immer 같은 라이브러리로 이 반복을 줄이기도 한다.","code":"const state = { user: { profile: { city: '서울', zip: '01000' } } };","o":["{ ...state, city: '부산' }","{ ...state, user: { ...state.user, addr: { ...state.user.addr, city: '부산' } } }","state.user.profile.city = '부산';","{ ...state, user: { ...state.user, profile: { ...state.user.profile, city: '부산' } } }"],"a":3}],"th":{"sum":"순수함수는 같은 입력에 항상 같은 출력을 내고 관찰 가능한 부수효과가 없는 함수다. 부수효과를 경계 바깥으로 밀어내고 데이터를 불변으로 다루면 코드는 예측 가능하고 테스트하기 쉬워진다.","body":[{"h":"순수함수의 두 가지 조건","t":"첫째, 참조 투명성이다. 같은 인자를 넣으면 언제 어디서 호출하든 항상 같은 값을 돌려준다. 둘째, 관찰 가능한 부수효과가 없다. 함수 내부에서 지역 변수를 만들고 그 값을 계속 바꾸더라도, 그 변화가 함수 밖에서는 전혀 보이지 않으므로 순수성은 깨지지 않는다."},{"h":"무엇이 부수효과인가","t":"콘솔 출력이나 파일 쓰기 같은 I/O, 전역 변수 변경, DOM 조작, 인자로 받은 객체나 배열의 내용 변경이 대표적인 부수효과다. 현재 시각을 읽는 Date.now()나 Math.random()도 호출할 때마다 결과가 달라지므로 순수하지 않다. 이런 값들은 함수 안에서 직접 읽지 말고 인자로 주입받으면 그 함수는 다시 순수해진다."},{"h":"불변성과 const의 오해","t":"const는 변수 바인딩의 재할당만 막을 뿐, 그 변수가 가리키는 객체의 내부 프로퍼티 변경은 전혀 막지 못한다. Object.freeze는 실제로 프로퍼티 변경을 막지만 얕은 동결이라 중첩된 객체 안쪽까지는 보호하지 못한다. 그래서 상태를 갱신할 때는 원본을 고치는 대신 스프레드 문법 등으로 새 객체나 새 배열을 만들어 돌려주는 방식을 쓴다."}],"code":{"c":"// 불순: 인자로 받은 배열을 직접 변경\nfunction addItemBad(cart, item) {\n  cart.push(item);\n  return cart;\n}\n\n// 순수: 새 배열을 반환, 원본은 그대로\nfunction addItem(cart, item) {\n  return [...cart, item];\n}\n\nconst cart = [{ id: 1 }];\nconst next = addItem(cart, { id: 2 });\nconsole.log(cart.length, next.length); // 1 2","cap":"인자를 변경하는 대신 새 값을 반환하면 호출자는 원본을 계속 신뢰할 수 있다."},"key":["순수함수 = 같은 입력 -> 같은 출력 + 관찰 가능한 부수효과 없음","지역 변수 변경은 외부에서 안 보이므로 순수성을 깨지 않는다","const는 재할당만 막고, Object.freeze는 얕은 동결이다"]}},{"t":"직접 짜 보기 — 밖을 건드리지 않기","th":{"sum":"순수함수는 **같은 입력이면 같은 출력이고, 밖을 건드리지 않는** 함수다.","body":[{"h":"시험하기 쉬워진다","t":"밖에 의존하는 게 없으면 값만 넣어 보면 된다. 데이터베이스도, 시계도, 가짜 객체도 필요 없다 — 테스트가 짧아지는 것은 결과일 뿐이고, 진짜 이득은 '이 함수만 보면 안다' 는 점이다."},{"h":"부수효과는 밖으로 몰아 둔다","t":"없앨 수는 없다. 파일도 쓰고 화면도 그려야 한다. 대신 계산은 순수하게 두고, 효과는 가장자리에서 한 번에 처리하면 대부분의 코드가 시험 가능해진다."},{"h":"불변성은 복사로 만든다","t":"배열을 바꾸는 대신 새 배열을 만든다. `push` 대신 전개 연산자, `sort` 대신 복사 후 정렬 — `sort` 와 `reverse` 는 원본을 바꾸는 대표적인 함정이다."},{"h":"숨은 입력을 조심한다","t":"`Date.now()` 나 전역 설정을 함수 안에서 읽으면, 같은 인자에도 결과가 달라진다. 그런 값은 인자로 받는다 — 그것만으로 함수가 순수해진다."}],"code":{"c":"// 원본을 바꾼다\narr.sort();  arr.reverse();  arr.push(x);\n\n// 새로 만든다\n[...arr].sort();  [...arr].reverse();  [...arr, x];\n\n// 숨은 입력을 인자로\nfunction expired(t, now) { return t < now; }","cap":"복사하면 밖이 안 바뀐다"},"key":["같은 입력 → 같은 출력","`sort`·`reverse` 는 원본을 바꾼다","숨은 입력은 인자로 받는다"]},"q":[{"k":"sortedCopy · 정렬해도 원본은 그대로","cat":"internals","q":"오름차순으로 정렬한 <b>새 배열</b>을 돌려주세요. 원본은 <b>그대로</b>여야 한다.","src":"function sortedCopy(xs) {\n  return xs.sort((a, b) => a - b);\n}\n","sol":"function sortedCopy(xs) {\n  return [...xs].sort((a, b) => a - b);\n}\n","ex":"`sort` 는 새 배열을 주는 것처럼 보이지만 **원본을 정렬하고 그것을 돌려준다**. 반환값만 확인하면 통과해서, 화면 목록이 원래 순서를 잃은 뒤에야 발견돼요. 앞에 `[...xs]` 하나면 끝난다.","t":"code","run":"js","tests":[{"in":"sortedCopy([3,1,2])","out":"[1,2,3]"},{"in":"(() => { const a = [3,1,2]; sortedCopy(a); return a; })()","out":"[3,1,2]"},{"in":"sortedCopy([])","out":"[]"}],"edge":[{"in":"sortedCopy([10,9])","out":"[9,10]"},{"in":"(() => { const a = [2,1]; const b = sortedCopy(a); return a[0]; })()","out":"2"}]},{"k":"isExpired · 시계를 인자로 받기","cat":"internals","q":"만료 시각과 <b>현재 시각</b>을 받아 만료됐으면 true 를 돌려주세요.","src":"function isExpired(t) {\n  return t < Date.now();\n}\n","sol":"function isExpired(t, now) {\n  return t < now;\n}\n","ex":"함수 안에서 시계를 읽으면 같은 인자에도 결과가 달라진다 — '어제는 통과했는데 오늘은 실패하는 테스트' 의 정체예요. 시간을 인자로 받으면 만료 직전·직후를 마음대로 시험할 수 있다.","t":"code","run":"js","tests":[{"in":"isExpired(100, 200)","out":"true"},{"in":"isExpired(300, 200)","out":"false"},{"in":"isExpired(200, 200)","out":"false"}],"edge":[{"in":"isExpired(0, 1)","out":"true"},{"in":"isExpired(1, 1)","out":"false"}]},{"k":"addItem · 새 상태를 만들어 돌려주기","cat":"internals","q":"장바구니 객체 <code>{items: [...]}</code> 에 항목을 더한 <b>새 객체</b>를 돌려주세요. 원본은 그대로다.","src":"function addItem(cart, item) {\n  cart.items.push(item);\n  return cart;\n}\n","sol":"function addItem(cart, item) {\n  return { ...cart, items: [...cart.items, item] };\n}\n","ex":"원본을 바꿔서 돌려주면 새 객체가 아니라 **같은 객체**다. 이전 상태와 견줘 화면을 다시 그리는 프레임워크는 '안 바뀌었다' 고 판단해 갱신을 건너뛰어요 — 리액트에서 '상태를 바꿨는데 화면이 그대로' 인 사고의 대부분이 이것이다.","t":"code","run":"js","tests":[{"in":"addItem({items:['a']}, 'b')","out":"{items:['a','b']}"},{"in":"(() => { const c = {items:['a']}; addItem(c, 'b'); return c.items; })()","out":"['a']"},{"in":"addItem({items:[]}, 'x')","out":"{items:['x']}"}],"edge":[{"in":"(() => { const c = {items:[]}; const d = addItem(c,'x'); return c === d; })()","out":"false"},{"in":"addItem({items:['a'], id: 1}, 'b')","out":"{items:['a','b'], id: 1}"}]}]}],"ord":1},{"t":"고차함수와 함수 합성","l":[{"t":"고차함수의 개념","q":[{"t":"choice","k":"fp-hof-def1","q":"고차함수(higher-order function)의 정의는?","ex":"고차함수는 함수를 값처럼 다루는 함수로, 인자로 받거나 반환값으로 내놓으면 해당한다. map, filter, setTimeout, 함수를 만들어 주는 팩토리가 모두 여기에 속한다. 인자 개수나 재귀 여부는 기준이 아니다.","o":["다른 함수를 인자로 받거나 함수를 반환하는 함수","인자가 세 개 이상인 함수","클래스 안에 메서드 형태로 정의되어 있는 함수","안에서 자기 자신을 다시 재귀 호출하는 모든 함수"],"a":0},{"t":"input","k":"fp-hof-closure1","q":"함수가 자신이 정의된 위치의 변수(예: factor)를 계속 기억하는 성질 또는 그런 함수를 무엇이라 하는가? (한국어 세 글자)","ex":"클로저는 함수가 만들어질 때의 렉시컬 환경을 함께 붙들고 다니는 구조다. makeMultiplier(3)이 반환한 함수는 호출이 끝난 뒤에도 factor가 3이라는 사실을 기억한다. 커링과 부분적용이 동작하는 근본 원리이기도 하다.","a":["클로저"]},{"t":"choice","k":"fp-hof-return1","q":"아래 makeMultiplier에 대한 설명으로 옳은 것은?","ex":"makeMultiplier는 n =&gt; n * factor라는 함수를 반환하므로 고차함수의 조건을 만족한다. 반환된 함수는 클로저로 factor 값을 계속 기억하므로 triple(5)는 15가 된다. 반대로 triple 자체는 숫자를 받아 숫자를 돌려주는 평범한 함수다.","code":"const makeMultiplier = factor =&gt; n =&gt; n * factor;\nconst triple = makeMultiplier(3);\nconsole.log(triple(5));","o":["triple(5)는 3을 출력한다","factor는 makeMultiplier 호출이 끝나면 사라져 triple 호출 시 undefined가 된다","makeMultiplier는 고차함수가 아니고 실제로 triple 쪽만 고차함수에 해당한다","makeMultiplier는 함수를 반환하므로 고차함수이고, triple(5)는 15다"],"a":3},{"t":"choice","k":"fp-hof-firstclass1","q":"일급 함수(first-class function)라는 말의 의미는?","ex":"일급이란 그 언어에서 값과 똑같은 대우를 받는다는 뜻이다. 함수를 변수에 담고, 배열에 넣고, 인자로 넘기고, 반환할 수 있으면 일급 함수다. 이 성질이 있어야 고차함수가 성립한다.","o":["함수가 클래스보다 우선순위가 높다는 뜻이다","함수 선언이 호이스팅된다는 뜻이다","함수가 변수에 담기고 인자로 전달되고 반환값이 될 수 있다는 뜻이다","함수가 프로그램 안에서 가장 먼저 실행되도록 보장된다는 뜻으로 쓴다"],"a":2},{"t":"choice","k":"fp-hof-callback1","q":"고차함수를 사용해 반복 로직을 추상화했을 때 얻는 이점으로 가장 적절한 것은?","ex":"map이나 filter는 순회와 인덱스 관리라는 반복적인 뼈대를 숨기고, 각 원소에 대해 무엇을 할지만 콜백으로 표현하게 해 준다. 그 결과 코드의 의도가 이름으로 드러나고 실수도 줄어든다. 성능이 무조건 좋아지거나 순수성이 보장되는 것은 아니다.","o":["메모리를 전혀 사용하지 않게 된다","인덱스 관리 같은 반복의 뼈대를 감추고 '무엇을 할지'만 드러내 의도가 명확해진다","모든 함수가 자동으로 순수해진다","결과적으로 실행 속도가 직접 쓴 for 문보다 빨라지므로 성능까지 함께 좋아진다"],"a":1}],"th":{"sum":"고차함수는 함수를 인자로 받거나 함수를 반환하는 함수이며, map/filter/reduce가 대표적인 예다. 작은 순수함수들을 합성해 파이프라인으로 잇는 것이 함수형 설계의 핵심 기법이다.","body":[{"h":"고차함수의 정의","t":"함수를 값처럼 인자로 넘기거나 결과로 돌려줄 수 있을 때 그 함수를 일급 함수라 하고, 그런 함수를 받거나 반환하는 함수를 고차함수라 부른다. setTimeout처럼 콜백을 받는 것도, 함수를 만들어 반환하는 팩토리도 모두 고차함수다. 덕분에 반복 구조는 라이브러리에 맡기고 우리는 각 원소에 무엇을 할지만 표현하면 된다."},{"h":"map, filter, reduce","t":"map은 각 원소를 변환해 같은 길이의 새 배열을, filter는 조건을 만족하는 원소만 골라 새 배열을 만든다. 둘 다 원본을 변경하지 않는다. reduce는 누적값과 원소를 접어 나가며 임의의 타입을 만들 수 있어서 숫자뿐 아니라 객체, 배열, 문자열도 결과가 될 수 있다. 다만 초기값 없이 빈 배열에 reduce를 호출하면 TypeError가 발생한다."},{"h":"합성과 파이프라인","t":"compose(f, g)(x)는 f(g(x))와 같아서 오른쪽 함수부터 적용되고, pipe(f, g)(x)는 g(f(x))로 왼쪽부터 적용된다. 합성은 결합법칙을 만족하므로 어디서 묶어도 결과가 같고, 아무것도 하지 않는 항등함수 x => x는 합성의 항등원 역할을 한다. 이 성질 덕분에 작은 함수들을 자유롭게 묶어 재사용할 수 있다."}],"code":{"c":"const compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);\nconst pipe = (...fns) => x => fns.reduce((acc, f) => f(acc), x);\n\nconst double = n => n * 2;\nconst inc = n => n + 1;\n\nconsole.log(compose(double, inc)(3)); // inc 먼저 -> 8\nconsole.log(pipe(double, inc)(3));    // double 먼저 -> 7","cap":"compose는 오른쪽부터, pipe는 왼쪽부터 적용된다."},"key":["고차함수 = 함수를 인자로 받거나 함수를 반환하는 함수","map/filter는 새 배열을 반환하고 forEach는 undefined를 반환한다","compose(f, g)(x) === f(g(x)), pipe는 반대 순서"]}},{"t":"map / filter / reduce","q":[{"t":"choice","k":"fp-arr-empty1","q":"아래 코드의 실행 결과는?","ex":"초기값 없이 reduce를 호출하면 첫 원소가 초기 누적값이 되는데, 빈 배열에는 첫 원소가 없어 'Reduce of empty array with no initial value' TypeError가 난다. [].reduce((a, b) =&gt; a + b, 0)처럼 초기값을 주면 0이 안전하게 반환된다. 초기값을 명시하는 습관이 중요한 이유다.","code":"[].reduce((a, b) =&gt; a + b);","o":["undefined 를 반환한다","0을 반환한다","TypeError가 발생한다","NaN 이라는 값을 그대로 반환한다"],"a":2},{"t":"choice","k":"fp-arr-chain1","q":"아래 코드에서 result의 값은?","ex":"filter가 홀수 [1, 3, 5]를 남기고, map이 [10, 30, 50]으로 바꾸고, reduce가 초기값 0부터 더해 90이 된다. 각 단계가 새 배열을 만들기 때문에 원본 배열은 그대로 유지된다. 이런 체이닝이 전형적인 데이터 변환 파이프라인이다.","code":"const result = [1, 2, 3, 4, 5]\n  .filter(n =&gt; n % 2 === 1)\n  .map(n =&gt; n * 10)\n  .reduce((acc, n) =&gt; acc + n, 0);","o":["60","90","150","30"],"a":1},{"t":"choice","k":"fp-arr-map1","q":"map에 대한 설명으로 옳은 것은?","ex":"map은 각 원소에 콜백을 적용한 결과를 모아 새 배열을 만들며 원본은 전혀 건드리지 않는다. 길이는 항상 원본과 같다. 길이를 줄이는 것은 filter, undefined를 반환하는 것은 forEach다.","o":["원본을 두고 새 배열을 반환","조건에 맞는 원소만 남겨 길이가 줄어든 배열을 만든다","원본 배열의 각 원소를 제자리에서 변경한다","항상 undefined를 반환한다"],"a":0},{"t":"choice","k":"fp-arr-reduce1","q":"reduce에 대한 설명으로 옳은 것은?","ex":"reduce는 폴드(fold)라 불리는 일반적인 접기 연산으로, 누적값의 타입에 제한이 없다. 배열을 객체로 그룹핑하거나 문자열로 이어붙이는 것도 전부 reduce로 표현할 수 있다. map과 filter도 사실 reduce로 구현할 수 있다.","o":["원본 배열의 길이를 항상 유지한다","결과 타입은 숫자여야 하며 합계나 곱 같은 것만 계산할 수 있도록 정해져 있다","콜백이 false를 반환하면 순회를 중단한다","누적값과 원소를 접어 나가며 객체, 배열, 문자열 등 임의의 타입을 만들 수 있다"],"a":3},{"t":"input","k":"fp-arr-foreach1","q":"[1, 2, 3].forEach(n =&gt; n * 2)의 반환값은 무엇인가? (소문자 영어 한 단어)","ex":"forEach는 콜백을 실행만 하고 결과를 수집하지 않으므로 언제나 undefined를 반환한다. 그래서 체이닝을 이어갈 수 없고, 변환 결과가 필요하면 map을 써야 한다. forEach는 부수효과를 일으키려는 목적일 때만 적합하다.","a":["undefined"]},{"t":"choice","k":"fp-arr-groupby1","q":"reduce로 배열을 카테고리별 객체로 묶을 때 초기값으로 가장 적절한 것은?","ex":"최종 결과가 카테고리를 키로 갖는 객체이므로 누적값의 초기 형태도 빈 객체 {}여야 한다. reduce의 초기값은 항상 만들고자 하는 결과 타입의 '비어 있는 값'으로 두면 된다. null을 주면 acc[key] 접근에서 바로 오류가 난다.","code":"items.reduce((acc, item) =&gt; {\n  const key = item.category;\n  return { ...acc, [key]: [...(acc[key] ?? []), item] };\n}, ???);","o":["new Array()","숫자 0","null","{}"],"a":3}],"th":{"sum":"고차함수는 함수를 인자로 받거나 함수를 반환하는 함수이며, map/filter/reduce가 대표적인 예다. 작은 순수함수들을 합성해 파이프라인으로 잇는 것이 함수형 설계의 핵심 기법이다.","body":[{"h":"고차함수의 정의","t":"함수를 값처럼 인자로 넘기거나 결과로 돌려줄 수 있을 때 그 함수를 일급 함수라 하고, 그런 함수를 받거나 반환하는 함수를 고차함수라 부른다. setTimeout처럼 콜백을 받는 것도, 함수를 만들어 반환하는 팩토리도 모두 고차함수다. 덕분에 반복 구조는 라이브러리에 맡기고 우리는 각 원소에 무엇을 할지만 표현하면 된다."},{"h":"map, filter, reduce","t":"map은 각 원소를 변환해 같은 길이의 새 배열을, filter는 조건을 만족하는 원소만 골라 새 배열을 만든다. 둘 다 원본을 변경하지 않는다. reduce는 누적값과 원소를 접어 나가며 임의의 타입을 만들 수 있어서 숫자뿐 아니라 객체, 배열, 문자열도 결과가 될 수 있다. 다만 초기값 없이 빈 배열에 reduce를 호출하면 TypeError가 발생한다."},{"h":"합성과 파이프라인","t":"compose(f, g)(x)는 f(g(x))와 같아서 오른쪽 함수부터 적용되고, pipe(f, g)(x)는 g(f(x))로 왼쪽부터 적용된다. 합성은 결합법칙을 만족하므로 어디서 묶어도 결과가 같고, 아무것도 하지 않는 항등함수 x => x는 합성의 항등원 역할을 한다. 이 성질 덕분에 작은 함수들을 자유롭게 묶어 재사용할 수 있다."}],"code":{"c":"const compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);\nconst pipe = (...fns) => x => fns.reduce((acc, f) => f(acc), x);\n\nconst double = n => n * 2;\nconst inc = n => n + 1;\n\nconsole.log(compose(double, inc)(3)); // inc 먼저 -> 8\nconsole.log(pipe(double, inc)(3));    // double 먼저 -> 7","cap":"compose는 오른쪽부터, pipe는 왼쪽부터 적용된다."},"key":["고차함수 = 함수를 인자로 받거나 함수를 반환하는 함수","map/filter는 새 배열을 반환하고 forEach는 undefined를 반환한다","compose(f, g)(x) === f(g(x)), pipe는 반대 순서"]}},{"t":"함수 합성과 파이프라인","q":[{"t":"choice","k":"fp-comp-pipe1","q":"아래 코드의 출력은?","ex":"pipe는 왼쪽부터 적용하므로 3에 inc를 적용해 4, 다시 double을 적용해 8이 된다. 같은 함수들을 compose(inc, double)(3)으로 묶으면 double이 먼저 적용돼 7이 나온다. 방향이 다르면 값도 다르다는 점이 핵심이다.","code":"const pipe = (...fns) =&gt; x =&gt; fns.reduce((acc, f) =&gt; f(acc), x);\nconst inc = n =&gt; n + 1;\nconst double = n =&gt; n * 2;\nconsole.log(pipe(inc, double)(3));","o":["7","9","8","6"],"a":2},{"t":"choice","k":"fp-comp-id1","q":"함수 합성의 항등원 역할을 하는 함수는?","ex":"항등함수 x =&gt; x는 받은 값을 그대로 돌려주므로 어떤 함수와 합성해도 그 함수를 바꾸지 않는다. 그래서 compose(f, id) === f 라는 항등원 법칙이 성립한다. 값을 버리거나 바꾸는 다른 보기들은 이 성질을 만족하지 않는다.","o":["() =&gt; {}","x =&gt; x","x =&gt; !x","x =&gt; null"],"a":1},{"t":"choice","k":"fp-comp-unary1","q":"함수들을 파이프라인으로 매끄럽게 이으려면 각 단계 함수가 갖추면 좋은 형태는?","ex":"파이프라인은 앞 함수의 반환값을 그대로 뒤 함수의 유일한 인자로 넘기므로, 단항 함수여야 자연스럽게 연결된다. 인자가 여러 개인 함수는 커링이나 부분적용으로 단항으로 만들어 끼워 넣는다. 아무것도 반환하지 않으면 다음 단계로 넘길 값이 없다.","o":["인자를 하나 받고 값을 하나 반환하는 단항 함수","인자를 두 개 이상 받아 처리하는 다항 함수","전역 변수를 갱신하는 함수","아무 값도 반환하지 않는 함수"],"a":0},{"t":"choice","k":"fp-comp-order1","q":"compose(f, g)(x)와 같은 의미의 표현은?","ex":"compose는 수학의 합성 표기 f∘g를 따라 오른쪽 함수부터 적용하므로 compose(f, g)(x)는 f(g(x))다. 왼쪽부터 읽히는 순서를 원한다면 pipe(g, f)(x)를 쓰면 같은 결과를 얻는다. 순서를 헷갈리면 결과가 완전히 달라진다.","o":["g∘f(x)","f(x) 다음에 g(x)를 각각 따로 호출한 것","f(x) + g(x)","f(g(x))"],"a":3},{"t":"input","k":"fp-comp-impl1","q":"compose를 배열 메서드 하나로 구현할 때 오른쪽부터 접기 위해 사용하는 메서드 이름은? (영어, 예: someMethod)","ex":"reduceRight는 배열을 오른쪽 끝에서 왼쪽으로 접어 나가므로 compose의 적용 순서와 맞는다. 반대로 pipe는 왼쪽부터 접는 reduce로 구현한다. 두 구현은 순회 방향만 다르고 구조는 같다.","a":["reduceRight"]},{"t":"choice","k":"fp-comp-assoc1","q":"함수 합성이 만족하는 성질로 옳은 것은?","ex":"합성은 결합법칙을 만족하므로 어떻게 묶어 그룹핑해도 결과 함수는 동일하다. 또 항등함수 id = x =&gt; x가 항등원이라 compose(f, id)와 compose(id, f)는 모두 f와 같다. 반면 교환법칙은 성립하지 않아 순서를 바꾸면 결과가 달라진다.","o":["교환법칙을 만족해 compose(f, g) 와 compose(g, f) 가 어떤 경우에도 언제나 항상 같은 결과를 내놓는다","합성 결과는 순수하지 않은 함수가 된다","항등원이 존재하지 않는다","결합법칙을 만족해 compose(compose(f, g), h)와 compose(f, compose(g, h))가 같다"],"a":3}],"th":{"sum":"고차함수는 함수를 인자로 받거나 함수를 반환하는 함수이며, map/filter/reduce가 대표적인 예다. 작은 순수함수들을 합성해 파이프라인으로 잇는 것이 함수형 설계의 핵심 기법이다.","body":[{"h":"합성과 파이프라인","t":"compose(f, g)(x)는 f(g(x))와 같아서 오른쪽 함수부터 적용되고, pipe(f, g)(x)는 g(f(x))로 왼쪽부터 적용된다. 합성은 결합법칙을 만족하므로 어디서 묶어도 결과가 같고, 아무것도 하지 않는 항등함수 x => x는 합성의 항등원 역할을 한다. 이 성질 덕분에 작은 함수들을 자유롭게 묶어 재사용할 수 있다."},{"h":"고차함수의 정의","t":"함수를 값처럼 인자로 넘기거나 결과로 돌려줄 수 있을 때 그 함수를 일급 함수라 하고, 그런 함수를 받거나 반환하는 함수를 고차함수라 부른다. setTimeout처럼 콜백을 받는 것도, 함수를 만들어 반환하는 팩토리도 모두 고차함수다. 덕분에 반복 구조는 라이브러리에 맡기고 우리는 각 원소에 무엇을 할지만 표현하면 된다."},{"h":"map, filter, reduce","t":"map은 각 원소를 변환해 같은 길이의 새 배열을, filter는 조건을 만족하는 원소만 골라 새 배열을 만든다. 둘 다 원본을 변경하지 않는다. reduce는 누적값과 원소를 접어 나가며 임의의 타입을 만들 수 있어서 숫자뿐 아니라 객체, 배열, 문자열도 결과가 될 수 있다. 다만 초기값 없이 빈 배열에 reduce를 호출하면 TypeError가 발생한다."}],"code":{"c":"const compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);\nconst pipe = (...fns) => x => fns.reduce((acc, f) => f(acc), x);\n\nconst double = n => n * 2;\nconst inc = n => n + 1;\n\nconsole.log(compose(double, inc)(3)); // inc 먼저 -> 8\nconsole.log(pipe(double, inc)(3));    // double 먼저 -> 7","cap":"compose는 오른쪽부터, pipe는 왼쪽부터 적용된다."},"key":["고차함수 = 함수를 인자로 받거나 함수를 반환하는 함수","map/filter는 새 배열을 반환하고 forEach는 undefined를 반환한다","compose(f, g)(x) === f(g(x)), pipe는 반대 순서"]}},{"t":"직접 짜 보기 — 함수를 받고 함수를 돌려주기","th":{"sum":"고차함수는 **함수를 값처럼 다루는 함수**다. 그래서 '무엇을 할지' 를 인자로 넘길 수 있다.","body":[{"h":"동작을 인자로 넘긴다","t":"정렬 기준, 거를 조건, 바꾸는 방법을 함수로 받으면 하나의 틀로 온갖 경우를 다룰 수 있다. `sort(비교함수)` 가 바로 그것이다."},{"h":"reduce 는 나머지를 다 만든다","t":"`map` 도 `filter` 도 `reduce` 로 쓸 수 있다. 초기값과 '한 걸음' 만 정하면 나머지는 같은 모양이다 — 초기값을 빠뜨리면 빈 배열에서 터진다."},{"h":"합성은 이어 붙이기","t":"`compose(f, g)(x)` 는 `f(g(x))` 다. 작은 함수 여럿을 이름 붙여 두고 필요할 때 이어 붙이면, 새 조합을 만드는 데 새 코드가 거의 안 든다."},{"h":"이름을 붙이면 읽힌다","t":"`xs.filter(x => x.age >= 19)` 보다 `xs.filter(isAdult)` 가 낫다. 조건에 이름을 주는 것만으로 주석이 필요 없어진다."}],"code":{"c":"const compose = (f, g) => x => f(g(x));\nconst pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);\n\nxs.reduce((acc, x) => acc + x, 0);   // 초기값 필수","cap":"함수도 값이다"},"key":["동작을 인자로 넘긴다","`reduce` 는 초기값을 준다","조건에 이름을 붙인다"]},"q":[{"k":"sumOf · 무엇을 더할지 넘겨받기","cat":"internals","q":"배열과 <b>값을 꺼내는 함수</b>를 받아 그 값들의 합을 돌려주세요. 빈 배열이면 0 이다.","src":"function sumOf(xs, f) {\n  return xs.map(f).reduce((a, b) => a + b);\n}\n","sol":"function sumOf(xs, f) {\n  return xs.reduce((acc, x) => acc + f(x), 0);\n}\n","ex":"초기값 없는 `reduce` 는 빈 배열에서 예외를 던진다 — 목록이 비는 것은 예외적인 상황이 아니라 매일 일어나는 일이에요. 초기값 `0` 하나가 그 경계를 없앤다.","t":"code","run":"js","tests":[{"in":"sumOf([{n:1},{n:2}], o => o.n)","out":"3"},{"in":"sumOf([], o => o.n)","out":"0"},{"in":"sumOf([1,2,3], x => x * 2)","out":"12"}],"edge":[{"in":"sumOf([{n:5}], o => o.n)","out":"5"},{"in":"sumOf([0,0], x => x)","out":"0"}]},{"k":"compose2 · 두 함수를 이어 붙이기","cat":"internals","q":"<code>compose2(f, g)(x)</code> 가 <code>f(g(x))</code> 가 되게 만드세요.","src":"function compose2(f, g) {\n  return x => g(f(x));\n}\n","sol":"function compose2(f, g) {\n  return x => f(g(x));\n}\n","ex":"`compose` 는 수학의 합성 표기(f∘g)를 따라 **오른쪽부터** 적용한다. 왼쪽부터 하고 싶으면 그건 `pipe` 예요 — 이름이 다른 이유가 순서라서, 둘을 섞으면 결과가 조용히 뒤집힌다.","t":"code","run":"js","tests":[{"in":"compose2(x => x + 1, x => x * 10)(1)","out":"11"},{"in":"compose2(x => x * 10, x => x + 1)(1)","out":"20"},{"in":"compose2(x => x, x => x)(5)","out":"5"}],"edge":[{"in":"compose2(s => s.length, n => String(n))(1000)","out":"4"},{"in":"compose2(x => x - 1, x => x - 1)(10)","out":"8"}]},{"k":"byKey · 정렬 기준을 만들어 주기","cat":"internals","q":"키 이름을 받아 <b>그 키로 오름차순 비교하는 함수</b>를 돌려주세요. 정렬에 바로 넘길 수 있어야 한다.","src":"function byKey(k) {\n  return (a, b) => a[k] > b[k];\n}\n","sol":"function byKey(k) {\n  return (a, b) => (a[k] < b[k] ? -1 : a[k] > b[k] ? 1 : 0);\n}\n","ex":"비교 함수는 음수·0·양수를 돌려줘야 한다. `true`/`false` 를 주면 각각 1과 0으로 읽혀 '작다' 를 표현할 방법이 없어져요 — 원소가 적으면 우연히 맞기도 해서 더 나쁘다.","t":"code","run":"js","tests":[{"in":"[{n:3},{n:1},{n:2}].sort(byKey('n')).map(o => o.n)","out":"[1,2,3]"},{"in":"byKey('n')({n:1},{n:2})","out":"-1"},{"in":"byKey('n')({n:2},{n:2})","out":"0"}],"edge":[{"in":"byKey('n')({n:2},{n:1})","out":"1"},{"in":"[{s:'b'},{s:'a'}].sort(byKey('s')).map(o => o.s)","out":"['a','b']"}]}]}],"ord":2},{"t":"반복 대신 재귀 — 스택과 누산기","g":"","l":[{"t":"재귀와 스택 I","q":[{"t":"choice","k":"바꾸지 않고 돌기","cat":"knowledge","q":"함수형 코드가 반복문 대신 재귀를 쓰는 이유로 가장 정확한 것은?","code":"반복문                       재귀\n  let s = 0;                   const sum = (xs) =>\n  for (const x of xs)            xs.length === 0 ? 0\n    s += x;                        : xs[0] + sum(xs.slice(1));\n  ↑ s 와 x 가 계속 바뀐다      ↑ 바뀌는 것이 없다","o":["값을 안 바꾸고 반복을 쓸 수 있어서","반복문은 순수함수 안에서 문법적으로 쓸 수 없기 때문","재귀가 반복문보다 빠르기 때문","재귀는 스택을 쓰지 않아 메모리를 덜 쓰기 때문"],"a":0,"ex":"네 번째 보기가 흔한 오해다 — <b>반복문을 써도 함수 안에서만 쓰면 순수하다</b>.\n개념: 재귀를 쓰는 이유는 금지 때문이 아니라 표현 방식 때문이다. '무엇인지' 를 적는 스타일에 재귀가 더 잘 맞는다.\n실무: 그리고 이 예제는 사실 성능이 나쁘다 — <code>slice</code> 가 매번 새 배열을 만들어 전체가 제곱 시간이 된다. 재귀로 쓴다고 저절로 좋아지지는 않는다.\n왜 그 답인가: 매 호출이 자기 인자를 받으므로 갱신되는 변수가 없다"},{"t":"choice","k":"스택은 유한하다","cat":"internals","q":"재귀 깊이를 직접 재 보니 약 9600단계에서 끊긴다. 이 결과가 뜻하는 것은?","code":"function depth(n){ try { return depth(n + 1); } catch(e){ return n; } }\ndepth(0)\n\n  →  9637\n\n같은 일을 반복문으로 하면 몇 억 번을 돌아도 문제가 없다","o":["재귀 함수는 1만 번까지만 부를 수 있도록 언어가 제한하기 때문","호출마다 스택을 쓰는데 스택이 유한하기 때문","try/catch 를 쓰면 스택 사용량이 늘어나 생기는 현상","메모리가 부족해서이며 메모리를 늘리면 제한도 없어진다"],"a":1,"ex":"정확한 숫자는 환경마다 다르다 — <b>스택 한 칸의 크기가 함수마다 다르기</b> 때문이다.\n개념: 호출할 때마다 돌아올 주소와 지역 변수를 쌓아야 한다. 인자가 많은 함수는 한 칸이 커서 더 얕은 깊이에서 넘친다.\n실무: 그래서 '얼마까지 안전한가' 를 숫자로 외우는 것은 소용없다. 물어야 할 것은 '<b>이 재귀의 깊이가 무엇에 비례하는가</b>' 다 — 뒤에서 다시 나온다.\n왜 그 답인가: 재귀에는 반복문에 없는 깊이 제한이 있다"},{"t":"choice","k":"꼬리 위치란","cat":"internals","q":"아래 두 재귀 중 호출이 <b>꼬리 위치</b>에 있는 쪽과 그 판별 기준은?","code":"A)  sum(n) = n === 0 ? 0 : n + sum(n - 1)\n\nB)  sum(n, acc) = n === 0 ? acc : sum(n - 1, acc + n)","o":["둘 다 꼬리 위치가 아니다 — 삼항 연산자 안에 들어 있는 호출은 꼬리 위치로 치지 않기 때문이다","둘 다 꼬리 위치다 — 재귀 호출이 조건식의 마지막 가지에 있기 때문이다","B 다 — 재귀 호출의 결과에 더 이상 손대지 않고 그대로 돌려주므로, 돌아와서 할 일이 없다","A 다 — 호출이 식의 오른쪽 끝에 적혀 있기 때문이다"],"a":2,"ex":"판별 기준은 <b>적힌 위치가 아니라 돌아온 뒤에 할 일이 있는가</b> 다.\n개념: A 는 <code>sum(n-1)</code> 이 값을 내놓아야 <code>n +</code> 를 할 수 있다. 그러니 그 <code>n</code> 을 어딘가에 기억해 두어야 하고, 그 자리가 스택이다.\n실무: 두 번째 보기의 함정에 주의한다. 오른쪽 끝에 있어도 <code>return f(n-1) + 1</code> 이면 꼬리가 아니다. <code>return f(...)</code> 형태여야 한다."},{"t":"choice","k":"누산기를 붙인다","cat":"impl","q":"일반 재귀를 꼬리 재귀로 바꾸는 표준적인 방법은?","code":"바꾸기 전\n  reverse(xs) = xs.length === 0 ? [] : [...reverse(xs.slice(1)), xs[0]]\n\n바꾼 뒤\n  reverse(xs, acc = []) = xs.length === 0 ? acc\n                                          : reverse(xs.slice(1), [xs[0], ...acc])","o":["재귀 깊이를 절반으로 줄이도록 두 단계씩 진행하는 것이다","조건 분기를 모두 없애고 하나의 식으로 합쳐 두는 일이다","재귀 호출을 함수의 맨 마지막 줄로 옮겨 적는 것","돌아와서 할 일을 인자로 미리 넘기는 것이다"],"a":3,"ex":"'스택에 기억해 두던 것' 을 <b>인자로 들고 내려간다</b>는 것이 발상의 전부다.\n개념: 그래서 꼬리 재귀 버전은 마지막 호출이 답을 알고 있다. 위로 돌아오며 조립할 필요가 없으니 돌아올 자리를 기억할 이유도 없다.\n실무: 다만 누산기를 붙이면 읽기가 어려워진다. 그리고 다음 문제에서 보듯 <b>자바스크립트에서는 그렇게 고쳐도 스택이 그대로 쌓인다</b>.\n왜 그 답인가: 중간 결과를 누산기에 담아 내려보내면 마지막 호출이 답을 그대로 갖게 된다"}],"th":{"sum":"함수형에서는 <b>변수를 바꾸지 않으려</b> 하는데, 반복문은 카운터를 계속 바꾼다. 그래서 반복을 <b>재귀</b>로 표현하죠. 다만 재귀에는 반복문에 없는 비용이 하나 있다 — <b>호출마다 스택이 쌓인다</b>는 것, 그리고 스택은 유한하다는 것이다.","body":[{"h":"재귀는 반복을 값으로 표현한 것","t":"반복문이 '<b>i 를 바꿔 가며 다시 돈다</b>' 라면 재귀는 '<b>다음 값으로 나를 다시 부른다</b>' 다. 바뀌는 것이 없고, 매 호출이 자기만의 인자를 받아요. 그래서 추론하기 쉽고, 이 트랙이 지금까지 말해 온 성질들과 잘 맞다."},{"h":"호출은 공짜가 아니다","t":"함수를 부르면 <b>돌아올 자리와 지역 변수를 스택에 쌓는다</b>. 그 스택은 정해진 크기가 있어서 넘치면 프로그램이 멈춰요. 이 환경에서 재어 보면 약 <b>9600단계</b>에서 끊긴다. 반복문은 아무리 돌아도 이 문제가 없다."},{"h":"꼬리 위치와 누산기","t":"재귀 호출이 <b>그 함수가 하는 마지막 일</b>이면 꼬리 위치에 있다고 한다. 이때는 돌아와서 할 일이 없으니 원리상 스택을 재활용할 수 있어요. <code>f(n-1) + n</code> 은 더하기가 남아 있어 꼬리가 아니고, <code>f(n-1, acc+n)</code> 처럼 <b>누산기</b>를 넘기면 꼬리가 된다."},{"h":"그러나 언어가 해 주지 않는다면","t":"꼬리 위치라고 <b>자동으로 최적화되지는 않는다</b>. 자바스크립트 표준에는 들어 있지만 대부분의 엔진이 구현하지 않아, 꼬리 재귀로 고쳐 써도 여전히 스택이 넘친다. 그럴 때는 <b>호출 대신 '다음에 할 일' 을 값으로 돌려주고 바깥에서 반복</b>하는 방법을 쓴다."}],"code":{"t":"누산기를 넘기면 꼬리가 된다","c":"꼬리가 아니다 — 돌아와서 더해야 한다\n  sum(n) = n === 0 ? 0 : n + sum(n - 1)\n                            ↑ 이 덧셈이 남아 있다\n  sum(3) → 3 + sum(2) → 3 + (2 + sum(1)) → ...\n  스택에 3, 2, 1 을 기억해 두어야 한다\n\n꼬리다 — 부르고 나면 할 일이 없다\n  sum(n, acc) = n === 0 ? acc : sum(n - 1, acc + n)\n                                 ↑ 이것이 마지막 일\n  sum(3, 0) → sum(2, 3) → sum(1, 5) → sum(0, 6) → 6\n  기억해 둘 것이 없다\n\n다만 자바스크립트 엔진은 대부분 이 차이를 활용하지 않는다\n  꼬리 재귀로 고쳐 써도 10만 단계에서 여전히 넘친다"},"key":["재귀는 값을 바꾸지 않고 반복을 표현하는 방법이다","호출마다 스택이 쌓이고 스택은 유한하다","누산기를 넘기면 재귀 호출이 꼬리 위치로 간다","꼬리라고 언어가 최적화해 주지는 않는다","깊이가 데이터 크기에 비례하면 위험하고 로그면 대체로 안전하다"]}},{"t":"재귀와 스택 II","q":[{"t":"choice","k":"고쳐도 넘친다","cat":"debug","q":"꼬리 재귀로 고쳐 썼는데도 아래처럼 실패한다. 무엇을 알려 주는가?","code":"function sumTail(n, acc){\n  if (n === 0) return acc;\n  return sumTail(n - 1, acc + n);      // 완전한 꼬리 위치\n}\n\nsumTail(100000, 0)\n  →  RangeError: Maximum call stack size exceeded","o":["꼬리 위치에 있다고 엔진이 스택을 재활용해 주지는 않는다","10만은 어떤 방식으로도 처리할 수 없는 크기이기 때문이다","누산기 방식이 잘못 구현되어 실제로는 꼬리 위치가 아니기 때문이다","엄격 모드를 켜지 않아 최적화가 비활성화된 것이다"],"a":0,"ex":"이 코드는 정말로 꼬리 위치에 있다 — <b>그런데도 넘친다</b>.\n개념: 꼬리 호출 최적화 여부는 언어 명세가 아니라 <b>구현</b>에 달려 있다. 어떤 언어와 런타임에서는 되고, 자바스크립트 주요 엔진에서는 대체로 안 된다.\n실무: 그래서 '꼬리 재귀로 썼으니 안전하다' 는 추론은 위험하다. 쓰는 환경에서 <b>깊은 입력으로 직접 확인</b>해 봐야 하고, 안 되면 다음 문제의 방법을 쓴다.\n왜 그 답인가: 표준에는 있지만 대부분의 자바스크립트 엔진이 구현하지 않았다"},{"t":"choice","k":"부르지 말고 돌려주기","cat":"impl","q":"아래 방식이 깊이 제한을 없애는 원리는?","code":"function trampoline(f){\n  let r = f;\n  while (typeof r === 'function') r = r();     // 바깥에서 반복한다\n  return r;\n}\n\nconst sumT = (n, acc) => n === 0 ? acc : () => sumT(n - 1, acc + n);\n                                          ↑ 부르지 않고 '할 일' 을 돌려준다\n\ntrampoline(() => sumT(10000000, 0))  →  50000005000000","o":["화살표 함수는 스택 프레임을 만들지 않기 때문이다","재귀 호출을 즉시 하지 않고 함수로 감싸 돌려주므로 스택이 쌓이지 않는다","while 문이 안쪽에서 쌓인 스택을 주기적으로 한 번씩 비워 주기 때문","함수를 값으로 다루면 엔진이 자동으로 꼬리 호출 최적화를 적용하기 때문이다"],"a":1,"ex":"1000만 단계를 돌았다 — 일반 재귀로는 <b>1만도 못 가는</b> 깊이다.\n개념: 각 단계에서 함수가 곧바로 <b>끝나고</b> 다음 할 일을 값으로 남긴다. 끝났으니 스택에서 내려가고, 바깥 반복문이 그것을 받아 다시 부른다.\n실무: 이 트랙의 주제와 이어진다 — '할 일' 을 값으로 다루면 실행 시점을 바깥에서 정할 수 있다. 대신 함수 객체를 매 단계 만들므로 그냥 반복문보다 느리다.\n왜 그 답인가: 실제 반복은 바깥의 while 문이 한다"},{"t":"choice","k":"깊이가 무엇에 비례하나","cat":"design","q":"재귀를 그대로 써도 되는지 판단하는 가장 실용적인 기준은?","code":"목록 n 개를 하나씩 처리      깊이 n        원소 10만이면 10만 단계\n절반씩 나누어 처리           깊이 log n    원소 1000만이면 24단계\n트리 순회                    깊이 = 트리 높이","o":["꼬리 위치에 있으면 언제나 안전하다","입력이 배열이면 안전하고 객체면 위험하다 — 배열은 길이가 정해져 있어 깊이를 미리 알 수 있지만 객체는 얼마나 중첩됐는지 알 수 없기 때문이다","<b>깊이가 입력 크기에 비례하면 위험하고, 로그에 비례하면 대체로 안전</b>하다 — 1000만 원소를 절반씩 나눠도 24단계면 끝난다","재귀 함수의 줄 수가 짧으면 안전하다"],"a":2,"ex":"24라는 숫자가 이 기준을 설명한다 — <b>절반씩 줄이면 아주 큰 입력도 금방 바닥에 닿는다</b>.\n개념: 그래서 병합 정렬이나 이진 탐색 같은 분할 정복은 재귀로 써도 안전하다. 목록을 하나씩 벗겨 내려가는 재귀가 위험하다.\n실무: 트리 순회는 애매하다. 균형 잡힌 트리는 로그지만, 한쪽으로 늘어진 트리는 원소 수만큼 깊어진다 — <b>입력이 바깥에서 오면 최악을 가정</b>해야 한다."},{"t":"choice","k":"서로 부르는 경우","cat":"internals","q":"두 함수가 서로를 부르며 도는 상호 재귀는 스택 관점에서 어떤가?","code":"const isEven = (n) => n === 0 ? true  : isOdd(n - 1);\nconst isOdd  = (n) => n === 0 ? false : isEven(n - 1);\n\nisEven(100000)","o":["함수가 서로 다르면 꼬리 호출 최적화가 적용되어 안전하다","상호 재귀는 반복문으로 변환되므로 깊이 제한이 없다","두 함수가 번갈아 부르므로 각각의 스택이 절반씩만 쌓여 두 배까지 견딘다","같은 문제가 생긴다"],"a":3,"ex":"'재귀' 라는 말이 <b>자기 자신을 부르는 것만 뜻하지는 않는다</b>.\n개념: 스택은 어느 함수가 쌓였는지 구분하지 않는다. 순환하는 호출 관계가 있으면 그 순환의 길이만큼 쌓인다.\n실무: 상호 재귀는 파서나 상태 기계에서 자연스럽게 나온다. 이럴 때도 트램폴린을 쓸 수 있다 — 두 함수 모두 부르는 대신 '다음 할 일' 을 돌려주게 고치면 된다.\n왜 그 답인가: 누가 누구를 부르든 호출은 호출이라 스택이 쌓이고, 여기서도 10만 단계에서 넘친다"}],"th":{"sum":"함수형에서는 <b>변수를 바꾸지 않으려</b> 하는데, 반복문은 카운터를 계속 바꾼다. 그래서 반복을 <b>재귀</b>로 표현하죠. 다만 재귀에는 반복문에 없는 비용이 하나 있다 — <b>호출마다 스택이 쌓인다</b>는 것, 그리고 스택은 유한하다는 것이다.","body":[{"h":"재귀는 반복을 값으로 표현한 것","t":"반복문이 '<b>i 를 바꿔 가며 다시 돈다</b>' 라면 재귀는 '<b>다음 값으로 나를 다시 부른다</b>' 다. 바뀌는 것이 없고, 매 호출이 자기만의 인자를 받아요. 그래서 추론하기 쉽고, 이 트랙이 지금까지 말해 온 성질들과 잘 맞다."},{"h":"호출은 공짜가 아니다","t":"함수를 부르면 <b>돌아올 자리와 지역 변수를 스택에 쌓는다</b>. 그 스택은 정해진 크기가 있어서 넘치면 프로그램이 멈춰요. 이 환경에서 재어 보면 약 <b>9600단계</b>에서 끊긴다. 반복문은 아무리 돌아도 이 문제가 없다."},{"h":"꼬리 위치와 누산기","t":"재귀 호출이 <b>그 함수가 하는 마지막 일</b>이면 꼬리 위치에 있다고 한다. 이때는 돌아와서 할 일이 없으니 원리상 스택을 재활용할 수 있어요. <code>f(n-1) + n</code> 은 더하기가 남아 있어 꼬리가 아니고, <code>f(n-1, acc+n)</code> 처럼 <b>누산기</b>를 넘기면 꼬리가 된다."},{"h":"그러나 언어가 해 주지 않는다면","t":"꼬리 위치라고 <b>자동으로 최적화되지는 않는다</b>. 자바스크립트 표준에는 들어 있지만 대부분의 엔진이 구현하지 않아, 꼬리 재귀로 고쳐 써도 여전히 스택이 넘친다. 그럴 때는 <b>호출 대신 '다음에 할 일' 을 값으로 돌려주고 바깥에서 반복</b>하는 방법을 쓴다."}],"code":{"t":"누산기를 넘기면 꼬리가 된다","c":"꼬리가 아니다 — 돌아와서 더해야 한다\n  sum(n) = n === 0 ? 0 : n + sum(n - 1)\n                            ↑ 이 덧셈이 남아 있다\n  sum(3) → 3 + sum(2) → 3 + (2 + sum(1)) → ...\n  스택에 3, 2, 1 을 기억해 두어야 한다\n\n꼬리다 — 부르고 나면 할 일이 없다\n  sum(n, acc) = n === 0 ? acc : sum(n - 1, acc + n)\n                                 ↑ 이것이 마지막 일\n  sum(3, 0) → sum(2, 3) → sum(1, 5) → sum(0, 6) → 6\n  기억해 둘 것이 없다\n\n다만 자바스크립트 엔진은 대부분 이 차이를 활용하지 않는다\n  꼬리 재귀로 고쳐 써도 10만 단계에서 여전히 넘친다"},"key":["재귀는 값을 바꾸지 않고 반복을 표현하는 방법이다","호출마다 스택이 쌓이고 스택은 유한하다","누산기를 넘기면 재귀 호출이 꼬리 위치로 간다","꼬리라고 언어가 최적화해 주지는 않는다","깊이가 데이터 크기에 비례하면 위험하고 로그면 대체로 안전하다"]}},{"t":"재귀와 스택 III","q":[{"t":"choice","k":"대부분은 접기다","cat":"design","q":"아래 세 재귀 함수의 공통 구조는 무엇인가?","code":"sum(xs)    = xs 없으면 0    아니면 xs[0] +    sum(나머지)\nlength(xs) = xs 없으면 0    아니면 1 +         length(나머지)\njoin(xs)   = xs 없으면 ''   아니면 xs[0] + ',' + join(나머지)\n\n달라지는 것은 두 곳뿐이다","o":["시작값과 합치는 방법 두 가지만 다르다 — 그래서 셋 다 reduce 한 줄로 쓸 수 있고, 재귀를 직접 쓸 필요가 없다","셋 다 꼬리 재귀이므로 스택이 쌓이지 않는다는 점이 공통이다 — 그래서 입력이 아무리 커지더라도 언제나 안전하게 쓸 수 있다","공통 구조는 없다 — 우연히 모양이 비슷할 뿐이다","셋 다 배열의 첫 원소만 사용한다는 점이 공통이다"],"a":0,"ex":"이 모양을 알아보면 <b>재귀를 직접 쓸 일이 크게 줄어든다</b>.\n개념: 목록을 하나씩 벗겨 가며 값을 모으는 재귀는 거의 전부 접기다. 접기는 이미 반복문으로 구현되어 있으므로 스택 문제도 함께 사라진다.\n실무: 그래서 재귀를 쓰기 전에 물어본다 — '이거 <code>reduce</code> 아닌가?' 트리처럼 가지가 여러 갈래일 때가 진짜 재귀가 필요한 자리다."},{"t":"choice","k":"왼쪽과 오른쪽","cat":"internals","q":"왼쪽부터 접는 것과 오른쪽부터 접는 것의 차이 중, 스택과 관련된 것은?","code":"왼쪽부터   ((0 + a) + b) + c        앞에서부터 값을 쌓아 간다\n오른쪽부터  a + (b + (c + 0))        끝에 닿아야 계산이 시작된다","o":["오른쪽부터 접기는 배열을 뒤집어야 하므로 메모리를 두 배 쓴다","오른쪽부터 접기는 끝에 닿을 때까지 아무것도 계산하지 못하고 미뤄 두므로, 재귀로 구현하면 목록 길이만큼 스택이 쌓인다","둘 다 같다 — 접는 방향은 결과에만 영향을 주고 스택과는 무관하다","왼쪽부터 접기가 스택을 더 많이 쓴다 — 중간 결과를 계속 들고 있어야 하기 때문이며, 목록이 길어질수록 그만큼 더 많이 쌓인다"],"a":1,"ex":"왼쪽부터 접기는 <b>누산기를 들고 내려가는 꼬리 재귀와 같은 모양</b>이다.\n개념: 오른쪽 접기는 <code>a + (b + (c + 0))</code> 을 만들려고 a 와 b 를 붙들고 있어야 한다. 그것이 스택이다.\n실무: 자바스크립트의 <code>reduce</code> 와 <code>reduceRight</code> 는 둘 다 반복문으로 구현되어 있어 이 문제가 없다. 이 이야기가 중요해지는 것은 <b>재귀로 직접 구현할 때</b>다."},{"t":"choice","k":"끝없는 목록","cat":"knowledge","q":"그렇다면 오른쪽부터 접기는 왜 쓰는가? 게으른 언어에서 어떤 일이 가능해지는가?","code":"오른쪽부터 접으며 '합치는 함수' 가 두 번째 인자를 안 볼 수도 있다면\n\n  any(xs, f) = f(xs[0]) ? true : any(나머지, f)\n                ↑ 참이면 나머지를 아예 계산하지 않는다\n\n끝없는 목록에서도 답이 나온다","o":["게으른 언어에서는 왼쪽부터 접기를 지원하지 않기 때문이다","오른쪽부터 접으면 계산이 자동으로 병렬로 나뉘어 더 빠르기 때문이다 — 끝에서부터 시작하면 앞뒤가 서로 독립이 된다","합치는 함수가 <b>나머지를 안 봐도 답이 정해지는 경우 거기서 멈출 수</b> 있다 — 그래서 무한한 목록에서도 결과가 나온다","오른쪽부터 접어야 원본 순서가 보존되기 때문이다"],"a":2,"ex":"왼쪽부터 접기는 <b>끝까지 가야 답이 나오므로</b> 무한 목록에서 영원히 멈추지 않는다.\n개념: 오른쪽 접기는 바깥부터 조립하므로, 바깥에서 답이 정해지면 안쪽을 계산할 이유가 없다. 게으른 평가가 그 '계산할 이유가 없다' 를 실제로 실행하지 않는 것으로 만들어 준다.\n실무: 자바스크립트에는 게으른 평가가 없으므로 이 이득을 그대로 쓸 수 없다. 대신 제너레이터나 <code>some</code> 처럼 <b>중간에 멈추는 함수</b>가 같은 일을 한다."},{"t":"choice","k":"스택을 직접 들기","cat":"impl","q":"깊은 트리를 재귀 없이 순회하려면 어떻게 하는가?","code":"재귀 순회               직접 스택을 들고 순회\n  walk(node) {            const stack = [root];\n    보기(node);            while (stack.length) {\n    자식마다 walk(자식);     const n = stack.pop();\n  }                          보기(n);\n                             stack.push(...n.children);\n                           }","o":["반복문으로 바꾸면 방문 순서가 같아지므로 완전히 동일한 코드다","스택 대신 큐를 써야만 깊이 제한을 피할 수 있다","배열을 쓰면 메모리를 덜 쓰기 때문이다","호출 스택이 하던 일을 배열로 직접 하는 것이다"],"a":3,"ex":"재귀가 쓰던 것을 없앤 것이 아니라 <b>내가 관리하는 자료구조로 옮긴 것</b>이다.\n개념: 호출 스택은 크기가 정해져 있고 늘리기 어렵다. 배열은 힙에 있으므로 메모리가 허락하는 만큼 커진다. 같은 알고리즘인데 담는 장소만 바꾼 셈이다.\n실무: 두 번째 보기가 틀린 이유도 알아 두면 좋다 — 위 코드는 자식을 넣은 순서의 <b>반대로</b> 방문한다. 순서를 맞추려면 자식을 뒤집어 넣어야 한다.\n왜 그 답인가: 배열은 힙에 있어 크기 제한이 훨씬 느슨하므로 깊이가 문제되지 않는다"}],"th":{"sum":"함수형에서는 <b>변수를 바꾸지 않으려</b> 하는데, 반복문은 카운터를 계속 바꾼다. 그래서 반복을 <b>재귀</b>로 표현하죠. 다만 재귀에는 반복문에 없는 비용이 하나 있다 — <b>호출마다 스택이 쌓인다</b>는 것, 그리고 스택은 유한하다는 것이다.","body":[{"h":"재귀는 반복을 값으로 표현한 것","t":"반복문이 '<b>i 를 바꿔 가며 다시 돈다</b>' 라면 재귀는 '<b>다음 값으로 나를 다시 부른다</b>' 다. 바뀌는 것이 없고, 매 호출이 자기만의 인자를 받아요. 그래서 추론하기 쉽고, 이 트랙이 지금까지 말해 온 성질들과 잘 맞다."},{"h":"호출은 공짜가 아니다","t":"함수를 부르면 <b>돌아올 자리와 지역 변수를 스택에 쌓는다</b>. 그 스택은 정해진 크기가 있어서 넘치면 프로그램이 멈춰요. 이 환경에서 재어 보면 약 <b>9600단계</b>에서 끊긴다. 반복문은 아무리 돌아도 이 문제가 없다."},{"h":"꼬리 위치와 누산기","t":"재귀 호출이 <b>그 함수가 하는 마지막 일</b>이면 꼬리 위치에 있다고 한다. 이때는 돌아와서 할 일이 없으니 원리상 스택을 재활용할 수 있어요. <code>f(n-1) + n</code> 은 더하기가 남아 있어 꼬리가 아니고, <code>f(n-1, acc+n)</code> 처럼 <b>누산기</b>를 넘기면 꼬리가 된다."},{"h":"그러나 언어가 해 주지 않는다면","t":"꼬리 위치라고 <b>자동으로 최적화되지는 않는다</b>. 자바스크립트 표준에는 들어 있지만 대부분의 엔진이 구현하지 않아, 꼬리 재귀로 고쳐 써도 여전히 스택이 넘친다. 그럴 때는 <b>호출 대신 '다음에 할 일' 을 값으로 돌려주고 바깥에서 반복</b>하는 방법을 쓴다."}],"code":{"t":"누산기를 넘기면 꼬리가 된다","c":"꼬리가 아니다 — 돌아와서 더해야 한다\n  sum(n) = n === 0 ? 0 : n + sum(n - 1)\n                            ↑ 이 덧셈이 남아 있다\n  sum(3) → 3 + sum(2) → 3 + (2 + sum(1)) → ...\n  스택에 3, 2, 1 을 기억해 두어야 한다\n\n꼬리다 — 부르고 나면 할 일이 없다\n  sum(n, acc) = n === 0 ? acc : sum(n - 1, acc + n)\n                                 ↑ 이것이 마지막 일\n  sum(3, 0) → sum(2, 3) → sum(1, 5) → sum(0, 6) → 6\n  기억해 둘 것이 없다\n\n다만 자바스크립트 엔진은 대부분 이 차이를 활용하지 않는다\n  꼬리 재귀로 고쳐 써도 10만 단계에서 여전히 넘친다"},"key":["재귀는 값을 바꾸지 않고 반복을 표현하는 방법이다","호출마다 스택이 쌓이고 스택은 유한하다","누산기를 넘기면 재귀 호출이 꼬리 위치로 간다","꼬리라고 언어가 최적화해 주지는 않는다","깊이가 데이터 크기에 비례하면 위험하고 로그면 대체로 안전하다"]}},{"t":"재귀와 스택 IV","q":[{"t":"choice","k":"입력이 깊이를 정한다","cat":"security","q":"깊게 중첩된 JSON 을 넣어 본 아래 결과가 드러내는 위험은?","code":"대괄호만 깊게 중첩한 JSON 문자열을 넣어 본다\n\n  JSON.parse 자체        100만 깊이도 통과   (반복으로 구현되어 있다)\n  내가 쓴 재귀 순회 함수   3386 깊이에서 실패\n\n  function walk(v){ return Array.isArray(v) ? v.map(walk) : v; }","o":["파싱은 통과한 입력이 내 코드에서 터진다","JSON.parse 에 버그가 있어 잘못된 입력을 통과시킨 것이다","재귀 순회 함수의 구현이 잘못되어 불필요한 호출이 생긴 것이다","3386 이면 충분히 깊으므로 실무에서 문제되지 않는다"],"a":0,"ex":"공격 문자열은 <code>[[[[...]]]]</code> 뿐이라 <b>몇 킬로바이트면 된다</b>.\n개념: 입력 크기 제한만으로는 막히지 않는다. 크기가 작아도 깊이는 얼마든지 깊을 수 있기 때문이다. 막으려면 깊이를 따로 세야 한다.\n실무: 바깥에서 오는 자료를 재귀로 훑는다면 <b>깊이 상한을 인자로 들고 다니며</b> 넘으면 거절한다. 또는 앞 문제처럼 직접 스택을 들고 순회한다.\n왜 그 답인가: 바깥에서 오는 데이터가 재귀 깊이를 정하므로, 짧은 문자열 하나로 서버를 멈출 수 있다"},{"t":"choice","k":"같은 것을 다시 세지 않기","cat":"perf","q":"아래 결과에서 200배 가까운 차이가 나는 이유는?","code":"fib(n) = n &lt; 2 ? n : fib(n-1) + fib(n-2)\n\n  fib(32) 그냥                  25.8 ms   (호출 704만 번)\n  fib(32) 결과를 기억해 두면     0.132 ms\n\n약 196배","o":["기억해 두는 방식이 재귀를 반복문으로 바꿔 주기 때문이다","같은 인자에 대한 계산이 <b>수없이 되풀이되는데 순수함수라 결과가 항상 같으므로</b>, 한 번 구한 값을 기억해 두면 다시 계산할 필요가 없다","재귀 깊이가 줄어들어 스택 비용이 사라지기 때문이다","기억해 둔 값이 CPU 캐시 메모리에 올라가 있어 접근이 훨씬 빠르기 때문이다 — 같은 계산이라도 캐시 메모리에서 읽으면 몇 배 빨라진다"],"a":1,"ex":"704만 번의 호출 중 <b>서로 다른 인자는 33가지뿐</b>이다. 나머지는 전부 되풀이다.\n개념: 이 최적화가 성립하는 전제가 순수성이다. 같은 입력에 항상 같은 출력이라야 지난 답을 그대로 써도 된다.\n실무: 그래서 순수함수는 최적화하기 쉽다. 반대로 안에서 시각을 읽거나 밖의 값을 참조하는 함수를 기억해 두면 <b>낡은 답을 돌려주는 버그</b>가 된다."},{"t":"choice","k":"재귀냐 반복이냐","cat":"design","q":"실무에서 재귀와 반복 중 무엇을 고를지 판단하는 순서로 가장 적절한 것은?","code":"고려할 것\n  a) 자료 구조가 재귀적인가 (트리, 중첩 객체)\n  b) 깊이가 무엇에 비례하는가\n  c) 이미 있는 접기 함수로 되는가\n  d) 읽기 쉬운가","o":["재귀를 고른다 — 함수형 코드에서 반복문은 쓰지 않는다","항상 반복문을 고른다 — 재귀는 스택이 넘칠 위험이 있어 어떤 경우에도 실무에는 부적합하다고 보는 것이 원칙이다","이미 있는 함수로 되는지를 먼저 보고, 안 되면 깊이가 안전한지를 본 다음, 그 위에서 읽기 쉬운 쪽을 고른다","읽기 쉬운 쪽을 먼저 고르고 문제가 생기면 그때 바꾼다"],"a":2,"ex":"순서가 중요하다 — <b>안전 여부를 확인한 뒤에 취향을 따진다</b>.\n개념: 대부분의 목록 처리는 이미 있는 접기 함수로 끝난다. 남는 것은 트리처럼 자료 자체가 재귀적인 경우이고, 거기서 깊이가 바깥 입력에 달렸는지를 본다.\n실무: 마지막 보기가 위험한 이유는 스택 넘침이 <b>운영 환경의 깊은 입력에서만</b> 드러나기 때문이다. 개발 중 쓰는 자료는 대체로 얕다."},{"t":"choice","k":"리뷰에서 무엇을 볼까","cat":"review","q":"중첩 댓글을 재귀로 렌더링하는 코드를 리뷰한다. 가장 먼저 물어야 할 것은?","code":"function render(comment){\n  return [comment.text, ...comment.replies.map(render)];\n}\n\n// 댓글에는 답글이 달리고, 답글에도 답글이 달린다","o":["재귀 대신 반복문으로 쓰면 더 빠른지다","comment.text 가 비어 있을 때의 처리다","map 대신 forEach 를 쓰면 메모리를 아낄 수 있는지다","답글 깊이에 상한이 있는지다"],"a":3,"ex":"이 코드 자체는 깔끔하다. 문제는 <b>깊이를 누가 정하느냐</b> 다.\n개념: 서비스에 깊이 제한이 있다면 재귀로 두어도 좋다. 없다면 언젠가 사용자가 그 한계를 찾아낸다 — 악의가 없어도 그렇다.\n실무: 대개는 제품 쪽에서 답글 깊이를 제한하는 것이 가장 간단한 해결이다. 화면에서도 깊게 들여쓴 댓글은 읽기 어려우므로 <b>기술적 제약과 사용성이 같은 방향</b>을 가리킨다.\n왜 그 답인가: 없다면 사용자가 답글에 답글을 계속 달아 깊이를 얼마든지 늘릴 수 있다"}],"th":{"sum":"함수형에서는 <b>변수를 바꾸지 않으려</b> 하는데, 반복문은 카운터를 계속 바꾼다. 그래서 반복을 <b>재귀</b>로 표현하죠. 다만 재귀에는 반복문에 없는 비용이 하나 있다 — <b>호출마다 스택이 쌓인다</b>는 것, 그리고 스택은 유한하다는 것이다.","body":[{"h":"재귀는 반복을 값으로 표현한 것","t":"반복문이 '<b>i 를 바꿔 가며 다시 돈다</b>' 라면 재귀는 '<b>다음 값으로 나를 다시 부른다</b>' 다. 바뀌는 것이 없고, 매 호출이 자기만의 인자를 받아요. 그래서 추론하기 쉽고, 이 트랙이 지금까지 말해 온 성질들과 잘 맞다."},{"h":"호출은 공짜가 아니다","t":"함수를 부르면 <b>돌아올 자리와 지역 변수를 스택에 쌓는다</b>. 그 스택은 정해진 크기가 있어서 넘치면 프로그램이 멈춰요. 이 환경에서 재어 보면 약 <b>9600단계</b>에서 끊긴다. 반복문은 아무리 돌아도 이 문제가 없다."},{"h":"꼬리 위치와 누산기","t":"재귀 호출이 <b>그 함수가 하는 마지막 일</b>이면 꼬리 위치에 있다고 한다. 이때는 돌아와서 할 일이 없으니 원리상 스택을 재활용할 수 있어요. <code>f(n-1) + n</code> 은 더하기가 남아 있어 꼬리가 아니고, <code>f(n-1, acc+n)</code> 처럼 <b>누산기</b>를 넘기면 꼬리가 된다."},{"h":"그러나 언어가 해 주지 않는다면","t":"꼬리 위치라고 <b>자동으로 최적화되지는 않는다</b>. 자바스크립트 표준에는 들어 있지만 대부분의 엔진이 구현하지 않아, 꼬리 재귀로 고쳐 써도 여전히 스택이 넘친다. 그럴 때는 <b>호출 대신 '다음에 할 일' 을 값으로 돌려주고 바깥에서 반복</b>하는 방법을 쓴다."}],"code":{"t":"누산기를 넘기면 꼬리가 된다","c":"꼬리가 아니다 — 돌아와서 더해야 한다\n  sum(n) = n === 0 ? 0 : n + sum(n - 1)\n                            ↑ 이 덧셈이 남아 있다\n  sum(3) → 3 + sum(2) → 3 + (2 + sum(1)) → ...\n  스택에 3, 2, 1 을 기억해 두어야 한다\n\n꼬리다 — 부르고 나면 할 일이 없다\n  sum(n, acc) = n === 0 ? acc : sum(n - 1, acc + n)\n                                 ↑ 이것이 마지막 일\n  sum(3, 0) → sum(2, 3) → sum(1, 5) → sum(0, 6) → 6\n  기억해 둘 것이 없다\n\n다만 자바스크립트 엔진은 대부분 이 차이를 활용하지 않는다\n  꼬리 재귀로 고쳐 써도 10만 단계에서 여전히 넘친다"},"key":["재귀는 값을 바꾸지 않고 반복을 표현하는 방법이다","호출마다 스택이 쌓이고 스택은 유한하다","누산기를 넘기면 재귀 호출이 꼬리 위치로 간다","꼬리라고 언어가 최적화해 주지는 않는다","깊이가 데이터 크기에 비례하면 위험하고 로그면 대체로 안전하다"]}}],"ord":3},{"t":"커링, 부분적용, 대수적 데이터 타입","l":[{"t":"커링","q":[{"t":"choice","k":"fp-curry-call1","q":"아래 코드에서 add(1)(2)(3)의 값은?","ex":"add(1)은 b를 기다리는 함수를, add(1)(2)는 c를 기다리는 함수를 돌려주고, 마지막 (3)에서 비로소 1 + 2 + 3이 계산된다. 각 단계는 클로저로 앞선 인자를 기억한다. 이것이 전형적인 커리된 함수의 호출 방식이다.","code":"const add = a =&gt; b =&gt; c =&gt; a + b + c;","o":["[1, 2, 3]","TypeError","1","6"],"a":3},{"t":"choice","k":"fp-curry-def1","q":"커링(currying)의 정의로 옳은 것은?","ex":"커링은 f(a, b, c)를 f(a)(b)(c) 형태로, 각 단계가 인자 하나만 받는 단항 함수의 연쇄가 되도록 바꾸는 구조적 변환이다. 인자 순서를 바꾸는 것은 flip, 결과 캐싱은 메모이제이션, 함수를 잇는 것은 합성이다. 이름이 비슷해 보이는 개념들과 구분해야 한다.","o":["함수 호출 결과를 캐싱해 두었다가 같은 인자로 다시 부를 때 그대로 재사용하는 최적화 기법","여러 함수를 하나로 합치는 변환","n개의 인자를 받는 함수를 한 번에 인자 하나씩 받는 함수들의 연쇄로 바꾸는 변환","함수의 인자 순서를 뒤집는 변환"],"a":2},{"t":"input","k":"fp-curry-arity1","q":"커링을 거친 각 단계의 함수는 인자를 몇 개 받는가? (숫자로)","ex":"커링의 정의상 각 단계는 인자를 정확히 하나만 받는 단항 함수다. 마지막 인자가 들어왔을 때 비로소 최종 값이 계산된다. 여러 인자를 한 번에 받는 형태는 커링이 아니라 부분적용에 가깝다.","a":["1"]},{"t":"choice","k":"fp-curry-partialcall1","q":"커리된 함수 add = a =&gt; b =&gt; c =&gt; a + b + c 에서 add(1, 2, 3)을 호출하면?","ex":"커리된 함수의 첫 단계는 매개변수 a 하나만 선언하고 있으므로 나머지 인자 2와 3은 그냥 버려진다. 결과는 여전히 b를 기다리는 함수이며 오류는 발생하지 않는다. 이것이 커링과 일반 다항 함수의 호출 규약이 다르다는 증거다.","o":["인자 개수가 맞지 않아 TypeError 가 난다","여분의 인자는 무시되고 b를 기다리는 함수가 반환된다","NaN이 반환된다","6이 반환된다"],"a":1},{"t":"choice","k":"fp-curry-why1","q":"커링이 함수 파이프라인과 잘 어울리는 이유는?","ex":"pipe나 compose는 단항 함수를 이어 붙이므로, 커링으로 설정값을 먼저 넣어 두면 데이터만 받는 단항 함수가 남아 그대로 끼워 넣을 수 있다. 예를 들어 map(fn)을 미리 만들어 두고 배열만 흘려보내는 식이다. 순수성이나 타입 검사와는 무관하다.","o":["설정값을 먼저 고정하고 데이터 하나만 받는 단항 함수를 얻을 수 있기 때문이다","커링은 함수 호출 비용을 줄여 주기 때문이다","커링된 함수는 넘어온 인자의 타입을 단계마다 검사해 주므로 안전하기 때문","커링된 함수는 항상 순수하기 때문이다"],"a":0}],"th":{"sum":"커링은 여러 인자를 받는 함수를 한 번에 인자 하나씩 받는 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 고정해 더 적은 인자를 받는 새 함수를 만드는 기법이다. 대수적 데이터 타입과 패턴 매칭은 없을 수 있는 값과 실패를 타입으로 드러내 준다.","body":[{"h":"커링과 부분적용은 다르다","t":"커링은 f(a, b, c)를 f(a)(b)(c)처럼 반드시 한 번에 하나씩 받는 단항 함수의 연쇄로 바꾸는 구조적 변환이다. 부분적용은 f(a, b, c)에서 a와 b를 한꺼번에 고정해 c만 받는 함수를 만드는 것으로, 결과가 단항 연쇄일 필요가 없다. JavaScript의 Function.prototype.bind는 여러 인자를 한 번에 고정할 수 있으므로 부분적용에 해당한다."},{"h":"곱 타입과 합 타입","t":"대수적 데이터 타입은 곱 타입과 합 타입으로 구성된다. 곱 타입은 레코드나 튜플처럼 여러 필드를 동시에 가지는 것이고, 합 타입은 태그된 유니온처럼 여러 경우 중 정확히 하나인 것이다. Optional/Maybe는 Some과 None 중 하나, Either는 실패를 뜻하는 Left와 성공을 뜻하는 Right 중 하나인 합 타입이다."},{"h":"패턴 매칭과 완전성","t":"합 타입의 값은 패턴 매칭으로 각 경우를 나눠 처리하며, 컴파일러는 모든 경우를 다뤘는지 완전성(exhaustiveness)을 검사해 준다. 덕분에 None 처리를 빠뜨린 실수를 실행 전에 잡을 수 있어 null 참조 오류를 구조적으로 막는다. Optional의 map은 None이면 함수를 적용하지 않고 None을 그대로 돌려주는 펑터로 동작한다."}],"code":{"c":"// 커링: 한 번에 인자 하나씩\nconst add = a => b => a + b;\nconsole.log(add(2)(3)); // 5\n\n// 부분적용: 여러 인자를 한 번에 고정\nfunction volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2); // w, h 동시 고정\nconsole.log(flat(3)); // 60\n\n// Optional의 map: None이면 그대로 통과\nconst mapOpt = (opt, f) =>\n  opt.tag === 'some' ? { tag: 'some', value: f(opt.value) } : opt;","cap":"커링은 단항 연쇄로의 변환, 부분적용은 인자 고정 — 서로 다른 개념이다."},"key":["커링: f(a,b,c) -> f(a)(b)(c), 부분적용: 인자 일부를 미리 고정","Optional은 값의 부재만, Either는 실패 이유까지 담는다","패턴 매칭의 완전성 검사가 누락된 경우를 컴파일 타임에 잡는다"]}},{"t":"부분적용과 커링의 차이","q":[{"t":"choice","k":"fp-partial-shape1","q":"3항 함수 f(a, b, c)를 커링한 결과의 호출 형태는?","ex":"커링은 각 단계가 인자 하나만 받도록 완전히 쪼개므로 f(a)(b)(c) 형태가 된다. f(a, b)(c)나 f(a)(b, c)처럼 어딘가에서 두 인자를 한꺼번에 받는 형태는 부분적용에 가깝다. 이 형태 차이가 두 개념을 가르는 기준이다.","o":["f(a, b)(c)","f(a)(b)(c)","f(a)(b, c)","f(a, b, c)"],"a":1},{"t":"choice","k":"fp-partial-multi1","q":"부분적용만의 특징으로 옳은 것은?","ex":"부분적용은 원하는 만큼의 인자를 한꺼번에 채워 넣을 수 있다는 점이 커링과 구별되는 지점이다. 반면 커링은 정의상 한 번에 하나씩만 받는다. 어느 쪽이든 원본 함수는 그대로 남고 새 함수가 만들어진다.","o":["한 번에 여러 개의 인자를 동시에 고정할 수 있다","인자를 한 번에 하나씩만 고정할 수 있다","원본 함수를 변경한다","반환값이 항상 원시값이다"],"a":0},{"t":"choice","k":"fp-partial-bind1","q":"아래 코드에서 bind가 수행한 것은 무엇이며 flat(3)의 값은?","ex":"bind는 w와 h를 한 번에 고정해 d만 받는 새 함수를 만들었으므로 부분적용이다. flat(3)은 10 * 2 * 3 = 60을 곧바로 계산해 반환한다. 커링이었다면 인자를 하나씩만 받아 flat(3)이 또 다른 함수를 돌려줬을 것이다.","code":"function volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2);","o":["커링이며 flat(3)은 함수를 반환한다","합성이며 flat(3)은 15다","메모이제이션이며 flat(3)은 10이다","부분적용이며 flat(3)은 60이다"],"a":3},{"t":"input","k":"fp-partial-bindname1","q":"JavaScript에서 인자 일부를 미리 고정해 새 함수를 만들 때 쓰는 Function.prototype의 메서드 이름은? (영어 소문자)","ex":"bind는 this와 앞쪽 인자들을 한 번에 고정한 새 함수를 반환하므로 부분적용의 도구다. 여러 인자를 동시에 고정할 수 있다는 점에서 커링과 구별된다. 화살표 함수로 (...rest) =&gt; f(고정값, ...rest)를 쓰는 것도 같은 효과를 낸다.","a":["bind"]},{"t":"choice","k":"fp-partial-usecase1","q":"부분적용이 특히 유용한 상황은?","ex":"log(level, message)에서 level을 'error'로 고정한 logError를 만들면 호출부가 훨씬 간결해진다. 이렇게 반복되는 설정 인자를 미리 채워 두는 것이 부분적용의 전형적인 쓰임이다. 인자가 매번 달라진다면 고정할 이유가 없다.","o":["모든 인자가 호출할 때마다 매번 달라지는 함수를 여러 번 반복해서 부르게 되는 상황일 때","함수를 클래스 메서드로 바꿔야 할 때","로거의 레벨이나 API의 기본 URL처럼 자주 반복되는 설정 인자를 미리 고정할 때","배열의 길이를 줄여야 할 때"],"a":2},{"t":"choice","k":"fp-partial-diff1","q":"커링과 부분적용의 관계로 옳은 것은?","ex":"커링은 함수의 구조를 f(a)(b)(c)라는 단항 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 채워 남은 인자만 받는 새 함수를 만드는 기법이다. 부분적용은 한 번에 여러 인자를 고정할 수 있고 결과가 단항 연쇄일 필요도 없다. 결과가 비슷해 보여 자주 혼동되지만 분명히 다른 개념이다.","o":["둘은 이름만 다른 완전히 같은 개념이다","커링은 단항 함수 연쇄로의 변환이고, 부분적용은 인자 일부를 고정해 더 적은 인자를 받는 함수를 만드는 것으로 서로 다르다","부분적용은 커링의 결과를 되돌리는 연산이다","커링은 인자를 하나씩 고정해 나가는 것이고, 부분적용은 받는 인자의 개수를 오히려 늘려 주는 것이라서 서로 정반대의 변환이다"],"a":1}],"th":{"sum":"커링은 여러 인자를 받는 함수를 한 번에 인자 하나씩 받는 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 고정해 더 적은 인자를 받는 새 함수를 만드는 기법이다. 대수적 데이터 타입과 패턴 매칭은 없을 수 있는 값과 실패를 타입으로 드러내 준다.","body":[{"h":"커링과 부분적용은 다르다","t":"커링은 f(a, b, c)를 f(a)(b)(c)처럼 반드시 한 번에 하나씩 받는 단항 함수의 연쇄로 바꾸는 구조적 변환이다. 부분적용은 f(a, b, c)에서 a와 b를 한꺼번에 고정해 c만 받는 함수를 만드는 것으로, 결과가 단항 연쇄일 필요가 없다. JavaScript의 Function.prototype.bind는 여러 인자를 한 번에 고정할 수 있으므로 부분적용에 해당한다."},{"h":"곱 타입과 합 타입","t":"대수적 데이터 타입은 곱 타입과 합 타입으로 구성된다. 곱 타입은 레코드나 튜플처럼 여러 필드를 동시에 가지는 것이고, 합 타입은 태그된 유니온처럼 여러 경우 중 정확히 하나인 것이다. Optional/Maybe는 Some과 None 중 하나, Either는 실패를 뜻하는 Left와 성공을 뜻하는 Right 중 하나인 합 타입이다."},{"h":"패턴 매칭과 완전성","t":"합 타입의 값은 패턴 매칭으로 각 경우를 나눠 처리하며, 컴파일러는 모든 경우를 다뤘는지 완전성(exhaustiveness)을 검사해 준다. 덕분에 None 처리를 빠뜨린 실수를 실행 전에 잡을 수 있어 null 참조 오류를 구조적으로 막는다. Optional의 map은 None이면 함수를 적용하지 않고 None을 그대로 돌려주는 펑터로 동작한다."}],"code":{"c":"// 커링: 한 번에 인자 하나씩\nconst add = a => b => a + b;\nconsole.log(add(2)(3)); // 5\n\n// 부분적용: 여러 인자를 한 번에 고정\nfunction volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2); // w, h 동시 고정\nconsole.log(flat(3)); // 60\n\n// Optional의 map: None이면 그대로 통과\nconst mapOpt = (opt, f) =>\n  opt.tag === 'some' ? { tag: 'some', value: f(opt.value) } : opt;","cap":"커링은 단항 연쇄로의 변환, 부분적용은 인자 고정 — 서로 다른 개념이다."},"key":["커링: f(a,b,c) -> f(a)(b)(c), 부분적용: 인자 일부를 미리 고정","Optional은 값의 부재만, Either는 실패 이유까지 담는다","패턴 매칭의 완전성 검사가 누락된 경우를 컴파일 타임에 잡는다"]}},{"t":"Optional / Either와 패턴 매칭","q":[{"t":"choice","k":"fp-adt-map1","q":"Optional의 map이 None에 대해 하는 동작은?","ex":"Optional은 펑터라서 map은 컨테이너 안에 값이 있을 때만 함수를 적용하고 같은 모양의 컨테이너를 돌려준다. None이면 적용을 건너뛰고 None을 그대로 통과시키므로 값이 없는 경우를 매번 검사할 필요가 없다. 덕분에 변환을 안전하게 연결할 수 있다.","o":["함수를 적용하지 않고 None을 그대로 반환한다","null로 변환해 반환한다","예외를 던진다","함수를 적용한 뒤 결과를 Some 으로 감싼다"],"a":0},{"t":"choice","k":"fp-adt-exh1","q":"패턴 매칭의 완전성(exhaustiveness) 검사가 주는 이점은?","ex":"완전성 검사는 합 타입의 모든 태그를 다뤘는지 컴파일러가 확인해 주는 기능이다. None 처리를 빼먹으면 실행 전에 오류로 알려 주므로 null 참조 버그를 구조적으로 막는다. 나중에 새로운 경우를 추가했을 때 고쳐야 할 지점을 전부 찾아 준다는 점도 큰 이점이다.","o":["합 타입에 여러 경우를 자동으로 하나로 합쳐 정리해 준다","런타임에 예외를 자동으로 잡아 준다","실행 속도가 if 문보다 빨라진다","처리하지 않은 경우가 있으면 컴파일 타임에 오류로 알려 준다"],"a":3},{"t":"choice","k":"fp-adt-prod1","q":"곱 타입(product type)에 해당하는 것은?","ex":"곱 타입은 여러 필드를 동시에 모두 갖는 타입으로 레코드와 튜플이 대표적이다. 가능한 값의 수가 각 필드 경우의 수의 곱이 되기 때문에 곱 타입이라 부른다. Either, Optional, 태그된 상태는 여러 경우 중 하나만 성립하는 합 타입이다.","o":["Some 또는 None 중 하나인 Optional이다","'success' 또는 'error' 둘 중 하나만 갖는 상태 태그","{ name, age } 형태의 레코드","Either(Left|Right)"],"a":2},{"t":"choice","k":"fp-adt-sum1","q":"합 타입(sum type)의 예로 옳은 것은?","ex":"합 타입은 여러 경우 중 정확히 하나인 값을 나타내는 태그된 유니온이며 Optional의 Some|None이 대표적이다. 레코드나 튜플처럼 여러 필드를 동시에 갖는 것은 곱 타입이다. 이 둘을 조합해 도메인을 표현하는 것이 대수적 데이터 타입이다.","o":["숫자를 원소로 갖는 배열","Some 또는 None 중 정확히 하나인 Optional","두 값을 함께 담는 튜플","이름과 나이 두 값을 함께 갖는 레코드 형태의 타입"],"a":1},{"t":"input","k":"fp-adt-tag1","q":"합 타입의 값이 지금 어떤 경우인지 구분하기 위해 함께 저장하는 표식을 무엇이라 하는가? (한국어 두 글자, 영어로는 tag)","ex":"태그는 { tag: 'some', value: 3 }처럼 그 값이 어느 경우인지 알려 주는 식별자다. 패턴 매칭은 이 태그를 보고 분기하며, 컴파일러도 태그 목록을 근거로 완전성을 검사한다. 그래서 합 타입을 태그된 유니온이라고도 부른다.","a":["태그"]},{"t":"choice","k":"fp-adt-either1","q":"Optional(Maybe)과 Either의 차이로 옳은 것은?","ex":"Optional의 None은 값이 없다는 사실만 알려줄 뿐 왜 없는지는 알려주지 못한다. Either는 Left에 오류 메시지나 오류 객체를 실어 실패의 원인을 전달할 수 있고 Right가 성공을 나타낸다. 둘 다 합 타입이며, 원인을 알려야 할 때 Either를 고른다.","o":["Either는 곱 타입이고 Optional은 합 타입이다","Optional 은 값을 두 개까지 담을 수 있고 Either 는 하나만 담을 수 있다는 차이가 있다","Optional은 실패 이유를 담을 수 없지만 Either는 Left에 실패 이유를 담을 수 있다","Either는 성공만 표현할 수 있고 Optional은 실패한 경우만 표현할 수 있어 쓰임이 정반대"],"a":2}],"th":{"sum":"커링은 여러 인자를 받는 함수를 한 번에 인자 하나씩 받는 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 고정해 더 적은 인자를 받는 새 함수를 만드는 기법이다. 대수적 데이터 타입과 패턴 매칭은 없을 수 있는 값과 실패를 타입으로 드러내 준다.","body":[{"h":"커링과 부분적용은 다르다","t":"커링은 f(a, b, c)를 f(a)(b)(c)처럼 반드시 한 번에 하나씩 받는 단항 함수의 연쇄로 바꾸는 구조적 변환이다. 부분적용은 f(a, b, c)에서 a와 b를 한꺼번에 고정해 c만 받는 함수를 만드는 것으로, 결과가 단항 연쇄일 필요가 없다. JavaScript의 Function.prototype.bind는 여러 인자를 한 번에 고정할 수 있으므로 부분적용에 해당한다."},{"h":"곱 타입과 합 타입","t":"대수적 데이터 타입은 곱 타입과 합 타입으로 구성된다. 곱 타입은 레코드나 튜플처럼 여러 필드를 동시에 가지는 것이고, 합 타입은 태그된 유니온처럼 여러 경우 중 정확히 하나인 것이다. Optional/Maybe는 Some과 None 중 하나, Either는 실패를 뜻하는 Left와 성공을 뜻하는 Right 중 하나인 합 타입이다."},{"h":"패턴 매칭과 완전성","t":"합 타입의 값은 패턴 매칭으로 각 경우를 나눠 처리하며, 컴파일러는 모든 경우를 다뤘는지 완전성(exhaustiveness)을 검사해 준다. 덕분에 None 처리를 빠뜨린 실수를 실행 전에 잡을 수 있어 null 참조 오류를 구조적으로 막는다. Optional의 map은 None이면 함수를 적용하지 않고 None을 그대로 돌려주는 펑터로 동작한다."}],"code":{"c":"// 커링: 한 번에 인자 하나씩\nconst add = a => b => a + b;\nconsole.log(add(2)(3)); // 5\n\n// 부분적용: 여러 인자를 한 번에 고정\nfunction volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2); // w, h 동시 고정\nconsole.log(flat(3)); // 60\n\n// Optional의 map: None이면 그대로 통과\nconst mapOpt = (opt, f) =>\n  opt.tag === 'some' ? { tag: 'some', value: f(opt.value) } : opt;","cap":"커링은 단항 연쇄로의 변환, 부분적용은 인자 고정 — 서로 다른 개념이다."},"key":["커링: f(a,b,c) -> f(a)(b)(c), 부분적용: 인자 일부를 미리 고정","Optional은 값의 부재만, Either는 실패 이유까지 담는다","패턴 매칭의 완전성 검사가 누락된 경우를 컴파일 타임에 잡는다"]}},{"t":"직접 짜 보기 — 인자를 나눠 받고, 경우를 나눠 담기","th":{"sum":"커링은 **인자를 한 번에 다 안 받는 것**이고, ADT 는 **가능한 경우를 타입으로 못 박는 것**이다.","body":[{"h":"부분적용은 설정을 미리 고정한다","t":"`log('ERROR')` 로 수준을 고정한 함수를 만들어 두면, 쓰는 자리에서는 메시지만 넘기면 된다. 같은 인자를 반복해 적는 일이 사라진다."},{"h":"커링은 합성을 쉽게 한다","t":"인자가 하나인 함수끼리는 그냥 이어 붙일 수 있다. 커링해 두면 `map(add(1))` 처럼 바로 넘길 수 있다."},{"h":"합 타입은 '둘 중 하나'","t":"성공이거나 실패, 값이 있거나 없거나. 두 경우를 한 값으로 담고 꺼낼 때 반드시 갈라 보게 하면, '실패인데 값을 읽는' 코드가 아예 안 만들어진다."},{"h":"null 대신 경우를 만든다","t":"`null` 은 '없음' 을 뜻하지만 왜 없는지는 말해 주지 않는다. `{ok:false, error:'…'}` 는 이유까지 담아, 부르는 쪽이 제대로 다루게 만든다."}],"code":{"c":"const add = a => b => a + b;\nconst add1 = add(1);\n[1,2,3].map(add1);      // [2,3,4]\n\n// 합 타입\n{ ok: true,  value: 5 }\n{ ok: false, error: '없음' }","cap":"나눠 받고, 갈라 담는다"},"key":["부분적용은 설정을 고정","커링하면 합성이 쉽다","실패도 값으로 담는다"]},"q":[{"k":"curry2 · 인자를 나눠 받기","cat":"internals","q":"두 인자 함수를 받아 <code>f(a)(b)</code> 로 부를 수 있게 바꾸세요.","src":"function curry2(f) {\n  return (a, b) => f(a, b);\n}\n","sol":"function curry2(f) {\n  return a => b => f(a, b);\n}\n","ex":"두 인자를 한 번에 받으면 `map` 에 바로 넘길 수 없다 — `map` 은 인자 하나짜리 함수를 기대하거든요. 나눠 받으면 첫 인자를 고정한 함수가 그대로 하나짜리가 되어 어디든 끼워 넣을 수 있다.","t":"code","run":"js","tests":[{"in":"curry2((a,b) => a + b)(1)(2)","out":"3"},{"in":"[1,2,3].map(curry2((a,b) => a + b)(10))","out":"[11,12,13]"},{"in":"curry2((a,b) => a * b)(3)(4)","out":"12"}],"edge":[{"in":"typeof curry2((a,b) => a)(1)","out":"'function'"},{"in":"curry2((a,b) => b)(1)(9)","out":"9"}]},{"k":"tryParse · 실패도 값으로 담기","cat":"internals","q":"문자열을 정수로 읽어 <code>{ok:true, value:n}</code> 또는 <code>{ok:false, error:'정수가 아님'}</code> 을 돌려주세요. 공백뿐이거나 숫자가 아니면 실패다.","src":"function tryParse(s) {\n  return { ok: true, value: parseInt(s, 10) };\n}\n","sol":"function tryParse(s) {\n  const t = s.trim();\n  if (t === '' || !/^-?\\d+$/.test(t)) return { ok: false, error: '정수가 아님' };\n  return { ok: true, value: Number(t) };\n}\n","ex":"`parseInt('12abc')` 는 12 를 돌려준다 — 앞에서 읽히는 만큼만 읽고 나머지를 버려요. 실패가 성공처럼 보이는 건다. 그리고 `parseInt('abc')` 의 NaN 을 `ok:true` 로 감싸면, 부르는 쪽은 그 NaN 을 계산에 그대로 쓴다.","t":"code","run":"js","tests":[{"in":"tryParse('42')","out":"{ok:true, value:42}"},{"in":"tryParse('abc')","out":"{ok:false, error:'정수가 아님'}"},{"in":"tryParse('  7 ')","out":"{ok:true, value:7}"}],"edge":[{"in":"tryParse('')","out":"{ok:false, error:'정수가 아님'}"},{"in":"tryParse('12abc')","out":"{ok:false, error:'정수가 아님'}"},{"in":"tryParse('-3')","out":"{ok:true, value:-3}"}]},{"k":"mapOk · 성공일 때만 이어 가기","cat":"internals","q":"<code>{ok, value, error}</code> 와 함수를 받아, <b>성공이면</b> 값에 함수를 적용한 새 결과를, <b>실패면 그대로</b> 돌려주세요.","src":"function mapOk(r, f) {\n  return { ...r, value: f(r.value) };\n}\n","sol":"function mapOk(r, f) {\n  if (!r.ok) return r;\n  return { ok: true, value: f(r.value) };\n}\n","ex":"실패한 결과에도 함수를 적용하면 `undefined` 가 계산에 들어가거나 그 자리에서 터진다. 실패를 만나면 더 진행하지 않고 그대로 흘려보내는 것 — 그게 합 타입을 쓰는 이유예요. 오류 처리가 흐름에서 자연히 빠진다.","t":"code","run":"js","tests":[{"in":"mapOk({ok:true, value:2}, x => x * 10)","out":"{ok:true, value:20}"},{"in":"mapOk({ok:false, error:'없음'}, x => x * 10)","out":"{ok:false, error:'없음'}"},{"in":"mapOk({ok:true, value:0}, x => x + 1)","out":"{ok:true, value:1}"}],"edge":[{"in":"mapOk({ok:false, error:'e'}, () => { throw new Error('불려선 안 됨'); })","out":"{ok:false, error:'e'}"},{"in":"mapOk({ok:true, value:'a'}, s => s + 'b')","out":"{ok:true, value:'ab'}"}]}]}],"ord":4},{"t":"함수형으로 진짜 프로그램 쓰기 — 상태·시간·오류","g":"","l":[{"t":"실전 함수형 I","q":[{"t":"choice","k":"상태를 값으로 넘기기","cat":"design","q":"장바구니를 모듈 안의 변수로 들고 여러 함수가 고치던 코드를 함수형으로 바꾸려 한다. 어떤 모양이 되는가?","code":"// 전\nlet cart = [];\nfunction add(item) { cart.push(item); }\n\n// 후 — ?","o":["(상태, 사건) → 새 상태 모양으로 바꿔 상태를 인자로 받고 새 상태를 돌려준다. 실제로 값을 들고 바꾸는 일은 바깥의 얇은 층 한 곳이 맡는다","상태가 필요한 프로그램은 함수형으로 쓸 수 없으므로 이 부분만 명령형으로 남겨 두고 나머지 부분만 함수형으로 바꾸는 것이 현실적인 절충","전역 변수를 <code>const</code> 로 바꾸면 불변이 되므로 함수는 그대로 두어도 된다","함수마다 자기 사본을 들게 하면 서로 간섭하지 않으므로 그것으로 충분하다"],"a":0,"ex":"함수형은 상태를 부정하지 않는다 — 어디에 둘지를 정할 뿐이다.\n개념: <code>add(cart, item)</code> 이 새 배열을 돌려주면 그 함수는 순수하다. 같은 입력에 같은 출력이고 바깥을 건드리지 않으니 테스트도 쉽고 순서에 의존하지 않는다. 바뀐 값을 어딘가에 담아 두는 일만 한 곳에 남는다.\n실무: 프런트엔드의 상태 관리, 이벤트 소싱, 게임 루프가 모두 이 모양이다. 핵심은 <b>상태를 바꾸는 지점이 하나</b>라는 것 — 값이 언제 왜 바뀌었는지 추적할 수 있게 된다."},{"t":"choice","k":"루프를 접는다","q":"누적 변수를 두고 도는 반복문을 <code>reduce</code>(fold) 로 바꿔 쓸 수 있는 이유는?","code":"let sum = 0;\nfor (const x of xs) sum = sum + x;\n\nxs.reduce((sum, x) => sum + x, 0)","o":["<code>reduce</code> 가 내부적으로 병렬 처리를 하므로 언제나 더 빠르기 때문이다","반복문의 본질이 '누적값과 다음 원소로 새 누적값을 만드는 일' 을 되풀이하는 것이기 때문이다. 그 한 걸음을 함수로 떼어 내면 되풀이하는 부분은 reduce 가 맡는다","reduce 는 배열 전용이라 일반 반복문과는 대응 관계가 없으며 겉보기에 우연히 비슷해 보일 뿐이다. 반복문 쪽이 훨씬 더 넓은 범위의 계산을 자유롭게 다룰 수 있는 도구다","반복문은 순수하지 않고 <code>reduce</code> 는 언제나 순수하기 때문이다"],"a":1,"ex":"map 과 filter 도 사실 fold 로 만들 수 있다 — 접기가 더 근본이다.\n개념: 반복문에서 바뀌는 것은 누적값 하나뿐이다. '이전 누적값 + 이번 원소 → 새 누적값' 이라는 <b>한 걸음</b>을 순수 함수로 적으면, 그 함수를 원소마다 적용하는 골격은 매번 똑같아서 라이브러리에 맡길 수 있다.\n실무: 다만 <code>reduce</code> 로 뭐든 쓸 수 있다고 해서 뭐든 쓰는 게 좋은 건 아니다. 누적값이 복잡해지면 읽기 어려워지므로, 뜻이 분명한 <code>map</code>·<code>filter</code>·<code>group</code> 이 있으면 그쪽을 쓴다."},{"t":"choice","k":"지금 시각을 얻는 자리","cat":"review","q":"쿠폰 만료를 판정하는 함수가 안에서 현재 시각을 직접 읽는다. 무엇이 문제이고 어떻게 고치는가?","code":"function 만료됐나(쿠폰) {\n  return 쿠폰.만료 < Date.now();\n}","o":["문제 없다. 시각을 읽는 것은 부수효과가 아니라 단순한 값 읽기이므로 순수하다","성능 문제다 — 시각을 매번 읽으면 느리므로 모듈을 로드하는 시점에 한 번만 읽어 저장해 두고 그 값을 계속 쓴다. 그렇게 하면 함수를 호출할 때마다 드는 비용이 완전히 사라진다","부를 때마다 결과가 달라져 순수하지 않고, 특정 시점을 테스트에서 재현할 수 없다. 현재 시각을 인자로 받게 바꾸면 함수는 순수해지고 비결정성은 부르는 쪽 한 줄로 밀려난다","함수 이름을 바꾸면 되며 구현은 그대로 두어도 된다"],"a":2,"ex":"'테스트하기 어렵다' 는 대개 '순수하지 않다' 의 다른 말이다.\n개념: 순수함수의 조건은 같은 입력에 같은 출력이다. 함수 안에서 시각을 읽으면 입력이 같아도 출력이 달라진다 — 만료 직전·직후 같은 경계를 시험하려면 시스템 시계를 조작하는 수밖에 없어진다.\n실무: 모듈 로드 때 한 번 읽어 두는 방식은 <b>더 나쁘다</b> — 오래 도는 프로세스에서 시각이 영원히 멈춘다. 인자로 받되 기본값을 주는 절충도 흔하지만, 기본값을 쓰는 경로는 여전히 테스트가 어렵다는 점을 알고 쓴다."},{"t":"choice","k":"난수와 아이디","cat":"design","q":"주문 객체를 만드는 함수가 안에서 무작위 아이디를 생성한다. 함수형 관점에서 어떻게 다루는 것이 좋은가?","code":"function 주문만들기(항목들) {\n  return { id: 무작위아이디(), 항목들 };\n}","o":["난수 씨앗을 전역에 고정해 두면 함수는 순수해진다","무작위성은 피할 수 없으므로 이 함수는 순수하게 만들 수 없고 그대로 두어야 한다","아이디 생성은 부수효과가 아니므로 이미 순수한 함수","아이디나 아이디를 만드는 함수를 인자로 받는다"],"a":3,"ex":"시각과 완전히 같은 처방이다 — 예측 못 하는 것은 밖에서 받는다.\n개념: 함수 안에서 난수를 뽑으면 반환값이 매번 달라져 결과를 비교할 수 없다. 값을 받아 오면 본체는 '주어진 아이디로 주문을 조립하는 일' 만 하게 되어 순수해진다.\n실무: 전역 씨앗을 고정하는 방법은 <b>테스트끼리 서로 영향을 준다</b> — 실행 순서가 바뀌면 값이 달라진다. 함수를 인자로 받는 방식이 더 낫고, 실제 아이디 생성은 프로그램 가장자리 한 곳에 모아 둔다.\n왜 그 답인가: 그러면 본체는 순수해지고 테스트에서는 고정된 값을 넣어 결과를 그대로 비교할 수 있다"}],"th":{"sum":"순수함수와 합성은 배웠는데 막상 프로그램을 쓰려니 막힌다 — <b>상태는 어디에 두고, 지금 시각은 어떻게 얻고, 오류는 어떻게 던지나</b>. 함수형은 이것들을 없애는 것이 아니라 <b>한곳으로 몰아두는</b> 방식이다.","body":[{"h":"상태를 없애는 게 아니라 넘겨준다","t":"가변 변수를 지우면 상태가 사라지는 게 아니라 <b>인자와 반환값으로 옮겨 간다</b>. <code>(상태, 사건) → 새 상태</code> 모양으로 쓰면 함수는 순수한 채로 남고, 실제로 값을 바꿔 들고 있는 일은 <b>바깥의 얇은 층 한 군데</b>가 맡는다."},{"h":"예측 불가능한 것은 인자로 받는다","t":"지금 시각·난수·아이디처럼 <b>부를 때마다 달라지는 것</b>을 함수 안에서 직접 얻으면 그 함수는 더 이상 순수하지 않고 테스트도 어려워진다. 대신 <b>값으로 받아</b> 오면 함수는 순수해지고, 테스트에서는 원하는 값을 넣어 볼 수 있다. 비결정성은 사라지지 않고 <b>바깥으로 밀려날 뿐</b>이다."},{"h":"오류도 값이다","t":"예외를 던지면 <b>함수 시그니처에 아무 흔적이 남지 않는다</b> — 부르는 쪽은 무엇이 튀어나올지 읽을 수 없어요. 성공과 실패를 <b>하나의 값</b>으로 돌려주면 실패가 타입에 드러나고, 처리하지 않으면 다음 단계로 넘어가지 않는다."}],"code":{"t":"부수효과를 바깥으로 밀어내기","c":"안 좋은 예 — 함수 안에서 직접 얻는다\n    function 만료됐나(주문) {\n      return 주문.만료 < Date.now();     // 부를 때마다 다르다\n    }\n\n좋은 예 — 값으로 받는다\n    function 만료됐나(주문, 지금) {\n      return 주문.만료 < 지금;           // 순수하다\n    }\n\n    만료됐나(주문, Date.now())            ← 비결정성은 여기 한 줄에만\n\n상태도 같은 방식으로\n    (상태, 사건) → 새 상태          순수\n    실제로 들고 바꾸는 일은 바깥 한 곳에서"},"key":["상태는 없애는 게 아니라 인자와 반환값으로 옮긴다","시각·난수처럼 달라지는 것은 값으로 받는다","오류를 값으로 돌려주면 타입에 드러나고 빠뜨릴 수 없다","게으름과 불변성에는 대가가 있다 — 어디서 멈출지 정한다"]}},{"t":"실전 함수형 II","q":[{"t":"choice","k":"던지기와 돌려주기","q":"실패할 수 있는 함수를 만들 때, 예외를 던지는 것과 성공·실패를 담은 값을 돌려주는 것의 가장 큰 차이는?","code":"function 파싱(s) { throw new Error('...'); }\nfunction 파싱(s) { return { ok: false, error: '...' }; }","o":["값으로 돌려주면 실패 가능성이 반환 타입에 드러나 부르는 쪽이 처리하지 않고는 값을 꺼낼 수 없다. 예외는 시그니처에 흔적이 없어 빠뜨려도 컴파일 단계에서 드러나지 않는다","값으로 돌려주는 쪽이 빠르므로 순전히 성능 때문에 선택한다 — 예외는 스택을 풀어야 하므로 실패가 잦은 경로에서는 결과 값을 만드는 비용이 훨씬 싸고, 그 밖의 차이는 없다","둘은 완전히 같으며 문법적 취향의 차이일 뿐이다 — 어느 쪽이든 실패는 호출자에게 전달되고, 처리하지 않으면 프로그램이 멈추므로 안전성은 같고 팀 규약으로 정하면 된다","예외는 함수형 언어에 존재하지 않으므로 쓸 수 없다 — 순수 함수는 반환값 말고는 바깥에 영향을 줄 수 없으므로 던지기 자체가 불가능하고, 값으로 돌려주는 것이 유일한 길이다"],"a":0,"ex":"'실패할 수 있다' 를 코드에 적어 두느냐 아니냐의 차이다.\n개념: 예외는 호출 흐름을 건너뛰어 어딘가로 튄다. 함수 선언만 보고는 무엇이 던져지는지 알 수 없어서, 처리를 빠뜨려도 조용히 넘어가다 운영 중에 터진다. 값으로 돌려주면 <b>성공을 꺼내려면 실패 경우를 반드시 마주쳐야</b> 한다.\n실무: 그렇다고 모든 예외를 없앨 필요는 없다. <b>일어날 만한 실패</b>(입력이 틀림, 없는 자원)는 값으로, <b>일어나면 안 되는 상황</b>(내부 불변식 깨짐)은 예외로 나누는 것이 흔한 절충이다."},{"t":"choice","k":"map 으로 부족할 때","cat":"internals","q":"값이 있을 수도 없을 수도 있는 결과에 <code>map</code> 을 썼는데, 넘긴 함수도 '있을 수도 없을 수도 있는 값' 을 돌려준다. 무슨 일이 생기고 어떻게 해결하는가?","code":"찾기(id)            → Some(user) | None\nuser => 이메일찾기(user)  → Some(email) | None\n\n찾기(id).map(이메일찾기)  → ?","o":["<code>map</code> 이 자동으로 겹을 펴 주므로 결과는 언제나 한 겹이다","Some(Some(email)) 처럼 두 겹으로 감싸진다. 겹을 하나로 펴 주는 flatMap(bind, chain) 을 쓰면 Some(email) 로 이어지고 어느 단계에서 없어도 자연스럽게 없음으로 흐른다","예외가 던져지므로 감싸서 잡아야 한다","빈 값이 되어 정보가 사라지므로 map 대신 반복문을 써야 한다. 감싸진 값 안에서 또 감싸진 값을 돌려주면 바깥쪽이 안쪽을 인식하지 못해 결과가 통째로 비어 버리고, 이런 경우에는 함수형 방식을 포기하는 편이 낫다"],"a":1,"ex":"이 '겹을 펴는 연산' 이 있느냐가 map 만 있는 타입과 체이닝되는 타입을 가른다.\n개념: <code>map</code> 은 안에 든 값에 함수를 적용해 <b>같은 껍질에 다시 담는다</b>. 그런데 함수 자체가 껍질을 씌워 돌려주면 껍질이 두 겹이 된다. <code>flatMap</code> 은 적용한 뒤 한 겹을 벗겨 준다.\n실무: 실패할 수 있는 단계를 여러 개 이을 때 이 연산이 없으면 중첩된 값을 손으로 벗기는 코드가 쌓인다. 프로미스 체이닝, 널 병합 연산자, 결과 타입의 <code>and_then</code> 이 전부 같은 모양이다."},{"t":"choice","k":"첫 실패에서 멈출까 모을까","cat":"design","q":"회원가입 폼의 다섯 필드를 검증한다. 함수형에서 흔히 쓰는 두 가지 방식과 각각이 맞는 자리는?","code":"이름 ✗   이메일 ✗   비밀번호 ✗   나이 ✓   약관 ✗","o":["두 방식은 결과가 같고 구현 방식만 다르므로 편한 쪽을 쓰면 된다","첫 실패에서 멈추는 것이 옳으며 실패를 모으는 방식은 함수형에 없다. 앞 단계가 실패했는데 뒤 단계를 계속 돌리면 잘못된 값 위에서 검증하게 되므로, 어떤 폼이든 첫 오류만 보여 주고 멈추는 것이 원칙","체이닝은 첫 실패에서 멈춰 뒤 단계를 건너뛰고, 모으는 방식은 모든 실패를 수집한다. 폼 검증처럼 사용자에게 한 번에 다 보여 줘야 하면 모으는 쪽이, 앞 단계 결과가 있어야 뒤가 성립하면 멈추는 쪽이 맞다","모두 모아야 하며 멈추는 방식은 정보를 잃으므로 쓰지 않는다"],"a":2,"ex":"'실패를 어떻게 합칠 것인가' 가 두 방식을 가른다.\n개념: 체이닝은 앞 단계의 <b>성공한 값</b>을 다음 단계가 쓰므로, 앞이 실패하면 뒤를 계산할 수가 없다. 반면 다섯 필드 검증은 서로 독립이라 전부 돌려 보고 실패를 모을 수 있다.\n실무: 폼 검증에서 첫 실패만 보여 주면 사용자는 고치고 제출하기를 다섯 번 반복하게 된다. 반대로 '사용자 조회 → 권한 확인 → 잔액 확인' 처럼 앞이 있어야 뒤가 있는 흐름은 멈추는 것이 맞다. <b>단계들이 서로 독립인지</b>를 보고 고른다."},{"t":"choice","k":"경계에서만 감싼다","cat":"review","q":"널을 없애려고 코드 곳곳에서 값을 Optional 로 감쌌더니 오히려 코드가 지저분해졌다. 어디서 감싸고 어디서 벗기는 것이 좋은가?","code":"바깥 세계 (DB · API · 사용자 입력)  ← 값이 없을 수 있다\n     ↓ 여기서 감싼다\n   내부 로직                       ← 값이 있다고 믿고 쓴다\n     ↓ 여기서 벗긴다\n바깥 세계 (응답 · 화면)","o":["Optional 은 반환값에만 쓰고 인자에는 쓰지 않으면 모든 문제가 해결된다 — 인자로 받은 값은 호출자가 이미 확인한 것이므로 함수 안에서는 벗길 일이 없고, 반환값만 감싸면 껍질이 한 겹으로 줄어든다","널을 쓰지 않으면 Optional 도 필요 없으므로 빈 문자열과 0 같은 기본값으로 대신한다 — '없음' 을 특별한 값으로 표현하면 타입이 단순해지고 감싸고 벗기는 코드가 통째로 사라진다","모든 함수가 Optional 을 주고받아야 안전하므로 지저분해도 그대로 두는 것이 옳다 — 어디서든 값이 없을 수 있다는 전제를 지켜야 널 접근이 원천 차단되고, 잡음은 안전의 대가다","값이 없을 수 있는 경계에서 한 번 감싸고, 안쪽 로직은 값이 있다는 전제로 단순하게 쓴 뒤 내보낼 때 한 번 벗긴다. 모든 함수가 감싸진 값을 주고받으면 껍질을 벗기고 씌우는 잡음만 늘어난다"],"a":3,"ex":"타입으로 문제를 미루기만 하면 잡음이 되고, 경계에서 해소하면 도구가 된다.\n개념: Optional 의 값어치는 '없을 수 있음' 을 <b>명시적으로 마주치게</b> 하는 데 있다. 그 마주침을 시스템 전체로 퍼뜨리면 어디서도 결론이 안 나고 껍질만 돌아다닌다. 경계에서 한 번 결론을 내면 안쪽은 깨끗해진다.\n실무: 함수형 코어와 명령형 셸을 나누는 것과 같은 발상이다. 없을 때 무엇을 할지(기본값·조기 반환·오류 응답)를 <b>바깥쪽에서 정하고</b>, 안쪽에는 확정된 값만 넘긴다."}],"th":{"sum":"순수함수와 합성은 배웠는데 막상 프로그램을 쓰려니 막힌다 — <b>상태는 어디에 두고, 지금 시각은 어떻게 얻고, 오류는 어떻게 던지나</b>. 함수형은 이것들을 없애는 것이 아니라 <b>한곳으로 몰아두는</b> 방식이다.","body":[{"h":"상태를 없애는 게 아니라 넘겨준다","t":"가변 변수를 지우면 상태가 사라지는 게 아니라 <b>인자와 반환값으로 옮겨 간다</b>. <code>(상태, 사건) → 새 상태</code> 모양으로 쓰면 함수는 순수한 채로 남고, 실제로 값을 바꿔 들고 있는 일은 <b>바깥의 얇은 층 한 군데</b>가 맡는다."},{"h":"예측 불가능한 것은 인자로 받는다","t":"지금 시각·난수·아이디처럼 <b>부를 때마다 달라지는 것</b>을 함수 안에서 직접 얻으면 그 함수는 더 이상 순수하지 않고 테스트도 어려워진다. 대신 <b>값으로 받아</b> 오면 함수는 순수해지고, 테스트에서는 원하는 값을 넣어 볼 수 있다. 비결정성은 사라지지 않고 <b>바깥으로 밀려날 뿐</b>이다."},{"h":"오류도 값이다","t":"예외를 던지면 <b>함수 시그니처에 아무 흔적이 남지 않는다</b> — 부르는 쪽은 무엇이 튀어나올지 읽을 수 없어요. 성공과 실패를 <b>하나의 값</b>으로 돌려주면 실패가 타입에 드러나고, 처리하지 않으면 다음 단계로 넘어가지 않는다."}],"code":{"t":"부수효과를 바깥으로 밀어내기","c":"안 좋은 예 — 함수 안에서 직접 얻는다\n    function 만료됐나(주문) {\n      return 주문.만료 < Date.now();     // 부를 때마다 다르다\n    }\n\n좋은 예 — 값으로 받는다\n    function 만료됐나(주문, 지금) {\n      return 주문.만료 < 지금;           // 순수하다\n    }\n\n    만료됐나(주문, Date.now())            ← 비결정성은 여기 한 줄에만\n\n상태도 같은 방식으로\n    (상태, 사건) → 새 상태          순수\n    실제로 들고 바꾸는 일은 바깥 한 곳에서"},"key":["상태는 없애는 게 아니라 인자와 반환값으로 옮긴다","시각·난수처럼 달라지는 것은 값으로 받는다","오류를 값으로 돌려주면 타입에 드러나고 빠뜨릴 수 없다","게으름과 불변성에는 대가가 있다 — 어디서 멈출지 정한다"]}},{"t":"실전 함수형 III","q":[{"t":"choice","k":"계산을 미루면","q":"지연 평가(게으른 평가)가 실제로 얻는 것은 무엇인가?","code":"const 값 = 비싼계산();          // 즉시 — 안 쓰더라도 계산됨\nconst 값 = lazy(비싼계산);       // 지연 — 요구할 때만","o":["쓰이지 않는 값은 아예 계산하지 않는다. 조건에 따라 안 쓰일 수 있는 값, 앞부분만 필요한 긴 목록, 무한한 구조를 다룰 수 있게 된다","여러 계산이 자동으로 병렬 실행된다","메모리 사용량이 언제나 줄어든다","계산 자체가 빨라져 같은 계산도 더 짧은 시간에 끝난다. 미뤄 두었다가 한꺼번에 처리하면 중간 단계가 최적화되므로 전체 수행 시간이 줄어든다"],"a":0,"ex":"게으름은 계산을 빠르게 하는 게 아니라 <b>안 하게</b> 하는 것이다.\n개념: 즉시 평가는 값을 만들어 두고 쓸지 말지 나중에 정한다. 지연 평가는 순서를 뒤집어, 필요하다고 요구받은 순간에만 계산한다. 그래서 쓰이지 않은 계산의 비용이 0 이 된다.\n실무: 조건 분기 안에서만 필요한 무거운 값, 로그 문자열 조립처럼 대개 버려지는 계산에서 효과가 크다. 반대로 <b>어차피 다 쓰는 값</b>에는 이득이 없고 감싸는 비용만 는다."},{"t":"choice","k":"끝없는 목록","cat":"internals","q":"자연수 전체처럼 끝이 없는 목록을 만들고 <code>제곱 → 3의 배수만 → 앞의 4개</code> 를 적용해도 프로그램이 멈추지 않고 끝난다. 어떻게 가능한가?","code":"자연수()          // 1, 2, 3, ... 끝없음\n  .map(제곱)\n  .filter(3의배수)\n  .take(4)","o":["언어가 무한 목록을 미리 잘라 유한하게 바꾼 뒤 처리하기 때문이다","각 단계가 목록 전체를 만들지 않고 <b>다음 원소를 요구받을 때 하나씩</b> 흘려보내기 때문이다. 마지막에서 4개만 요구하면 앞 단계들도 그만큼만 계산한다","무한 목록은 실제로는 아주 큰 유한 목록이라 언젠가는 끝나기 때문이다","메모리가 부족해질 때 자동으로 중단되며 그때까지 모은 것을 돌려주기 때문이다. 실행 환경이 한계를 감지해 목록 생성을 멈추므로 프로그램이 끝날 수 있다"],"a":1,"ex":"'전부 만들고 다음 단계로' 가 아니라 '한 개씩 끌어당긴다' 가 핵심이다.\n개념: 즉시 평가라면 <code>map</code> 이 무한 목록 전체를 변환하려다 영원히 멈추지 않는다. 지연 구조에서는 소비자가 원소를 하나 요구하면 그 요구가 앞 단계로 거슬러 올라가고, 필요한 만큼만 계산이 일어난다.\n실무: 큰 파일을 줄 단위로 읽어 거르는 작업도 같은 구조다. 중간 배열을 만들지 않아 메모리도 적게 쓴다. 다만 <b>끝을 정하는 단계가 없으면</b> 그대로 멈추지 않으니, 어딘가에서 반드시 개수를 제한해야 한다."},{"t":"choice","k":"기억해 두어도 되는 조건","cat":"perf","q":"함수 결과를 기억해 두었다가 같은 입력이면 다시 계산하지 않는 메모이제이션을 적용하려 한다. <b>안전하게 쓸 수 있는 조건</b>과 그 대가는?","code":"느린함수(x) → 기억해둔값[x] 가 있으면 그대로","o":["어떤 함수든 안전하게 적용할 수 있으며 대가도 없다","함수가 빠를수록 효과가 크므로 가벼운 함수에 먼저 적용한다","함수가 순수해야 한다","인자가 하나인 함수에만 적용할 수 있고 메모리 부담은 없다"],"a":2,"ex":"순수함수가 주는 이득 중 가장 실질적인 것.\n개념: 부수효과가 있는 함수를 기억해 두면 두 번째 호출에서 <b>그 효과가 일어나지 않는다</b> — 로그가 안 찍히거나 카운터가 안 오른다. 순수해야 '결과만 쓰면 된다' 가 성립한다.\n실무: 기억한 표에 상한을 두거나(오래된 것부터 버리기) 키 종류가 적은 함수에만 쓴다. 무한정 자라는 표는 그 자체가 메모리 누수다. 그리고 계산이 싼 함수에 적용하면 <b>키를 만들고 표를 뒤지는 비용이 더 클 수 있다</b>.\n왜 그 답인가: 같은 입력에 같은 출력이어야 기억한 값을 재사용해도 결과가 같다. 대가는 <b>메모리</b>이며, 입력 종류가 많으면 기억한 표가 끝없이 자란다"},{"t":"choice","k":"게으름의 함정","cat":"debug","q":"반복문 안에서 지연 값을 만들어 목록에 담고 나중에 한꺼번에 값을 꺼냈더니 전부 같은 결과가 나온다. 무엇이 문제인가?","code":"for (var i = 0; i < 3; i++)\n  목록.push(lazy(() => i));\n\n목록.map(f => f())   // 기대: 0,1,2   실제: 3,3,3","o":["지연 값은 한 번만 꺼낼 수 있으므로 두 번째부터는 처음 꺼낸 것과 같은 값이 그대로 나온다. 처음 계산한 결과가 안에 기억되어 이후 호출에서는 다시 계산하지 않기 때문에 생기는 일이다","목록에 담는 순서가 뒤집혀서 생기는 문제이므로 역순으로 담으면 된다","지연 평가는 마지막 값만 기억하도록 설계되어 있으므로 정상 동작이다","지연 값 안의 함수가 변수를 값이 아니라 그 자리 자체로 붙잡고 있어서, 나중에 꺼낼 때는 반복이 끝난 뒤의 값을 본다. 반복마다 새 변수가 생기게 하거나 값을 그때 붙잡아 두어야 한다"],"a":3,"ex":"'언제 계산되는가' 를 놓치면 게으름은 버그가 된다.\n개념: 계산을 미루면 그 계산이 <b>실제로 실행되는 시점의 환경</b>을 본다. 반복 변수를 함수 전체가 공유하고 있으면, 나중에 실행될 때는 반복이 이미 끝난 뒤의 값을 읽는다.\n실무: 반복마다 새로 묶이는 선언을 쓰거나, 값을 인자로 넘겨 그 순간에 고정한다. 더 근본적으로는 <b>지연 함수 안에서 바깥의 가변 변수를 읽지 않는 것</b>이 안전하다 — 순수하게 쓰면 이 문제가 아예 생기지 않는다."}],"th":{"sum":"순수함수와 합성은 배웠는데 막상 프로그램을 쓰려니 막힌다 — <b>상태는 어디에 두고, 지금 시각은 어떻게 얻고, 오류는 어떻게 던지나</b>. 함수형은 이것들을 없애는 것이 아니라 <b>한곳으로 몰아두는</b> 방식이다.","body":[{"h":"상태를 없애는 게 아니라 넘겨준다","t":"가변 변수를 지우면 상태가 사라지는 게 아니라 <b>인자와 반환값으로 옮겨 간다</b>. <code>(상태, 사건) → 새 상태</code> 모양으로 쓰면 함수는 순수한 채로 남고, 실제로 값을 바꿔 들고 있는 일은 <b>바깥의 얇은 층 한 군데</b>가 맡는다."},{"h":"예측 불가능한 것은 인자로 받는다","t":"지금 시각·난수·아이디처럼 <b>부를 때마다 달라지는 것</b>을 함수 안에서 직접 얻으면 그 함수는 더 이상 순수하지 않고 테스트도 어려워진다. 대신 <b>값으로 받아</b> 오면 함수는 순수해지고, 테스트에서는 원하는 값을 넣어 볼 수 있다. 비결정성은 사라지지 않고 <b>바깥으로 밀려날 뿐</b>이다."},{"h":"오류도 값이다","t":"예외를 던지면 <b>함수 시그니처에 아무 흔적이 남지 않는다</b> — 부르는 쪽은 무엇이 튀어나올지 읽을 수 없어요. 성공과 실패를 <b>하나의 값</b>으로 돌려주면 실패가 타입에 드러나고, 처리하지 않으면 다음 단계로 넘어가지 않는다."}],"code":{"t":"부수효과를 바깥으로 밀어내기","c":"안 좋은 예 — 함수 안에서 직접 얻는다\n    function 만료됐나(주문) {\n      return 주문.만료 < Date.now();     // 부를 때마다 다르다\n    }\n\n좋은 예 — 값으로 받는다\n    function 만료됐나(주문, 지금) {\n      return 주문.만료 < 지금;           // 순수하다\n    }\n\n    만료됐나(주문, Date.now())            ← 비결정성은 여기 한 줄에만\n\n상태도 같은 방식으로\n    (상태, 사건) → 새 상태          순수\n    실제로 들고 바꾸는 일은 바깥 한 곳에서"},"key":["상태는 없애는 게 아니라 인자와 반환값으로 옮긴다","시각·난수처럼 달라지는 것은 값으로 받는다","오류를 값으로 돌려주면 타입에 드러나고 빠뜨릴 수 없다","게으름과 불변성에는 대가가 있다 — 어디서 멈출지 정한다"]}},{"t":"실전 함수형 IV","q":[{"t":"choice","k":"복사하지 않는 불변 갱신","cat":"perf","q":"깊이 20 짜리 트리에서 잎 하나만 불변으로 바꿀 때, 전체를 복사하지 않고도 원본을 지킬 수 있는 이유는?","code":"바꾼 잎에서 뿌리까지의 경로: 노드 20개\n트리 전체 노드 수        : 약 100만 개","o":["바뀐 곳에서 뿌리까지의 경로에 있는 노드만 새로 만들고 나머지 가지는 원본과 그대로 공유하기 때문이다 — 100만 개가 아니라 20개만 새로 만들면 된다","내부적으로 원본을 몰래 고친 뒤 되돌릴 수 있게 기록해 두기 때문이다","불변 자료구조는 실제로는 매번 전체를 복사하며, 느린 것을 감수하는 것이 원칙이다. 원본을 지키려면 공유할 수 없으므로 깊이가 20 이든 얼마든 통째로 새로 만드는 수밖에 없다","가비지 컬렉터가 복사본을 자동으로 합쳐 주기 때문이다"],"a":0,"ex":"'불변이면 느리다' 는 오해가 여기서 깨진다.\n개념: 원본이 절대 안 바뀐다는 보장이 있으니 <b>손대지 않은 부분은 마음 놓고 같이 쓸 수 있다</b>. 그래서 갱신 비용이 전체 크기가 아니라 깊이에 비례한다 — 100만 개짜리에서도 스무 번 남짓이다.\n실무: 이 성질을 쓰려면 자료구조가 그렇게 설계돼 있어야 한다. 배열을 매번 통째로 복사하는 방식은 진짜로 O(n) 이라, 큰 목록을 자주 고친다면 구조 공유를 지원하는 불변 컬렉션을 쓴다."},{"t":"choice","k":"함수형이 손해인 자리","cat":"perf","q":"숫자 수백만 개를 여러 단계로 변환하는 계산에서 <code>map</code>·<code>filter</code> 체인이 반복문보다 눈에 띄게 느렸다. 왜 그런가?","code":"xs.map(f).filter(g).map(h)   // 중간 배열 2개\nfor (...) { ... }             // 중간 배열 없음","o":["불변성 때문에 값을 통째로 복사하느라 느린 것이며 피할 방법이 없다","단계마다 중간 배열이 만들어져 메모리를 쓰고 여러 번 훑기 때문이다.","실제로는 차이가 없고 측정 오류일 가능성이 높다","함수 호출은 반복문보다 느리므로 함수형은 성능이 필요한 곳에 쓸 수 없다"],"a":1,"ex":"함수형이 느린 게 아니라 <b>중간 결과를 만드는 것</b>이 느리다.\n개념: <code>map(f).filter(g).map(h)</code> 는 배열을 세 번 훑고 중간 배열을 두 개 만든다. 원소가 수백만이면 그 할당과 순회가 그대로 비용이 된다. 반복문은 한 번 훑으면서 세 가지를 함께 한다.\n실무: 세 단계를 하나의 <code>reduce</code> 로 합치거나 지연 스트림을 쓰면 중간 배열이 사라진다. <b>대부분의 코드에서는 이 차이가 문제되지 않으므로</b> 읽기 쉬운 쪽을 기본으로 두고, 측정해서 병목으로 확인된 곳만 바꾼다.\n왜 그 답인가: 한 번의 순회로 합치거나(fold 로 융합), 지연 스트림으로 중간 배열이 안 생기게 하면 차이가 줄어든다"},{"t":"choice","k":"인자 순서가 정하는 것","cat":"design","q":"함수형 라이브러리들이 <code>map(fn, list)</code> 처럼 <b>데이터를 마지막 인자로</b> 두는 관례를 따르는 이유는?","code":"map(제곱, xs)          // 데이터가 마지막\nconst 제곱들 = map(제곱)  // 부분적용하면 바로 쓸 수 있는 함수\n\npipe(제곱들, 홀수만, 합계)(xs)","o":["인자 순서는 성능에 영향을 주며 데이터가 뒤에 있을 때 더 빠르기 때문이다. 큰 값이 마지막에 오면 앞 인자들을 먼저 처리해 둘 수 있어 호출 비용이 줄어든다","관례일 뿐 실질적인 차이는 없으며 라이브러리마다 마음대로 정한 것이다","데이터를 마지막에 두면 앞 인자만 미리 채워 <b>데이터 하나만 받는 함수</b>를 얻을 수 있고, 그 함수를 그대로 파이프라인에 끼워 넣을 수 있기 때문이다","데이터가 앞에 오면 부분적용 자체가 문법적으로 불가능하기 때문이다"],"a":2,"ex":"커링과 합성이 실제로 쓸모 있으려면 인자 순서가 받쳐 줘야 한다.\n개념: 부분적용은 <b>앞에서부터</b> 인자를 채운다. 그래서 '설정에 해당하는 것' 을 앞에, '흘러가는 데이터' 를 뒤에 두면 설정만 채운 함수가 자연스럽게 만들어진다. 데이터가 앞에 있으면 이런 조합이 매번 감싸는 함수를 필요로 한다.\n실무: 언어의 메서드 문법은 반대로 데이터가 앞에 온다(<code>xs.map(f)</code>). 둘을 섞어 쓰면 어색해지므로, 한 코드베이스 안에서는 <b>한쪽 방식으로 통일</b>하는 편이 낫다."},{"t":"choice","k":"몰래 깨지는 참조 투명성","cat":"review","q":"순수하다고 생각한 함수가 사실은 순수하지 않은 경우가 있다. 다음 중 참조 투명성을 <b>깨는</b> 것은?","code":"A) 결과를 내부 표에 기억해 두고 재사용한다\nB) 진단용으로 호출 횟수를 세어 전역 변수에 더한다\nC) 인자로 받은 배열을 정렬해 돌려준다(원본을 정렬)\nD) 큰 값을 처음 쓸 때 계산해 내부에 담아 둔다","o":["C 만 문제이며 B 는 값을 돌려주지 않으므로 참조 투명성과는 무관하다. 반환값이 없는 함수는 식으로 쓰이지 않으니 다른 값으로 바꿔 넣을 일 자체가 없기 때문이다","A 와 D — 내부 상태를 들고 있으므로 순수하지 않다","네 가지 모두 참조 투명성을 깬다","B 와 C — 전역 변수를 바꾸고, 인자로 받은 원본을 고친다. A 와 D 는 바깥에서 관찰되는 결과가 달라지지 않으므로 참조 투명성을 깨지 않는다"],"a":3,"ex":"'내부 상태가 있느냐' 가 아니라 '바깥에서 차이를 볼 수 있느냐' 가 기준이다.\n개념: 참조 투명성은 <b>표현식을 그 결과값으로 바꿔 써도 프로그램의 의미가 같은가</b>를 묻는다. 메모이제이션이나 지연 초기화는 내부에 값을 담아 두지만 같은 입력에 같은 결과를 주고 바깥을 건드리지 않아 통과한다. 반면 전역 카운터나 인자 원본 수정은 다른 코드가 관찰할 수 있는 변화를 남긴다.\n실무: C 는 특히 잦은 사고다 — 정렬·뒤집기처럼 원본을 고치는 메서드를 쓰면서 새 값을 돌려준다고 착각하기 쉽다. 인자를 받으면 <b>고치지 말고 복사본을 만드는 것</b>을 기본으로 삼는다."}],"th":{"sum":"순수함수와 합성은 배웠는데 막상 프로그램을 쓰려니 막힌다 — <b>상태는 어디에 두고, 지금 시각은 어떻게 얻고, 오류는 어떻게 던지나</b>. 함수형은 이것들을 없애는 것이 아니라 <b>한곳으로 몰아두는</b> 방식이다.","body":[{"h":"상태를 없애는 게 아니라 넘겨준다","t":"가변 변수를 지우면 상태가 사라지는 게 아니라 <b>인자와 반환값으로 옮겨 간다</b>. <code>(상태, 사건) → 새 상태</code> 모양으로 쓰면 함수는 순수한 채로 남고, 실제로 값을 바꿔 들고 있는 일은 <b>바깥의 얇은 층 한 군데</b>가 맡는다."},{"h":"예측 불가능한 것은 인자로 받는다","t":"지금 시각·난수·아이디처럼 <b>부를 때마다 달라지는 것</b>을 함수 안에서 직접 얻으면 그 함수는 더 이상 순수하지 않고 테스트도 어려워진다. 대신 <b>값으로 받아</b> 오면 함수는 순수해지고, 테스트에서는 원하는 값을 넣어 볼 수 있다. 비결정성은 사라지지 않고 <b>바깥으로 밀려날 뿐</b>이다."},{"h":"오류도 값이다","t":"예외를 던지면 <b>함수 시그니처에 아무 흔적이 남지 않는다</b> — 부르는 쪽은 무엇이 튀어나올지 읽을 수 없어요. 성공과 실패를 <b>하나의 값</b>으로 돌려주면 실패가 타입에 드러나고, 처리하지 않으면 다음 단계로 넘어가지 않는다."}],"code":{"t":"부수효과를 바깥으로 밀어내기","c":"안 좋은 예 — 함수 안에서 직접 얻는다\n    function 만료됐나(주문) {\n      return 주문.만료 < Date.now();     // 부를 때마다 다르다\n    }\n\n좋은 예 — 값으로 받는다\n    function 만료됐나(주문, 지금) {\n      return 주문.만료 < 지금;           // 순수하다\n    }\n\n    만료됐나(주문, Date.now())            ← 비결정성은 여기 한 줄에만\n\n상태도 같은 방식으로\n    (상태, 사건) → 새 상태          순수\n    실제로 들고 바꾸는 일은 바깥 한 곳에서"},"key":["상태는 없애는 게 아니라 인자와 반환값으로 옮긴다","시각·난수처럼 달라지는 것은 값으로 받는다","오류를 값으로 돌려주면 타입에 드러나고 빠뜨릴 수 없다","게으름과 불변성에는 대가가 있다 — 어디서 멈출지 정한다"]}}],"ord":5},{"t":"여럿이 동시에 — 불변성과 병렬","g":"","l":[{"t":"불변성과 병렬 I","q":[{"t":"choice","k":"경쟁이 성립하는 조건","cat":"internals","q":"데이터 경쟁이 생기려면 세 가지가 겹쳐야 한다. 불변성은 그중 무엇을 없애는가?","code":"① 여럿이 같은 것을 본다 (공유)\n② 누군가 그것을 바꾼다 (변경)\n③ 그 일이 동시에 일어난다 (동시)","o":["변경을 없앤다 — 값이 바뀌지 않으면 공유되고 동시에 읽혀도 아무 문제가 없다. 락은 대신 '동시' 를 막는 방법이라 조율 비용이 든다","공유를 없앤다 — 불변 값은 스레드마다 복사본을 갖는다","셋 다 없애므로 어떤 동시성 문제도 남지 않는다","동시성을 없앤다 — 불변 값은 한 번에 하나씩만 접근되도록 런타임이 보장하므로, 여러 스레드가 한꺼번에 겹쳐 들어가는 일 자체가 생기지 않는다"],"a":0,"ex":"'락을 잘 쓰는 법' 과 '락이 필요 없게 만드는 법' 은 다른 접근이다.\n개념: 세 조건 중 하나만 깨면 경쟁이 성립하지 않는다. 락은 동시 접근을 순서대로 만들어 ③을 없애지만, 그러려면 모든 접근 지점이 규칙을 지켜야 하고 비용도 든다. 불변성은 ②를 없애 <b>지킬 규칙 자체를 만들지 않는다</b>.\n실무: 그래서 불변으로 만들 수 있는 것은 최대한 불변으로 두고, 정말 바뀌어야 하는 것만 한곳에 모아 거기서만 조율한다. 마지막 보기가 틀린 이유는 다음 문제들에서 본다 — 함수형이 동시성 문제를 전부 없애 주지는 않는다."},{"t":"choice","k":"어디서 돌려도 같다","q":"순수함수가 병렬 실행에 잘 맞는 이유를 가장 정확히 설명한 것은?","code":"순수함수: 같은 입력 → 같은 출력 · 바깥을 건드리지 않음","o":["순수함수는 실행 시간이 짧아 병렬화 이득이 크다","결과가 입력에만 달려 있어 언제 어느 스레드에서 돌든 같고, 바깥을 건드리지 않으니 서로 간섭할 것이 없다 — 실행 순서를 자유롭게 정할 수 있다","순수함수는 내부적으로 자동으로 여러 스레드에 나뉘어 실행되기 때문이다. 컴파일러가 부수효과가 없다는 것을 확인하면 알아서 병렬로 쪼개 주므로 따로 손댈 것이 없다","순수함수는 메모리를 쓰지 않아 경쟁이 생기지 않는다"],"a":1,"ex":"'순서를 바꿔도 된다' 는 성질이 병렬화의 전제다.\n개념: 병렬로 돌린다는 것은 실행 순서를 런타임에 맡긴다는 뜻이다. 순서가 결과를 바꾸면 그렇게 할 수 없다. 순수함수는 바깥 상태를 읽지도 쓰지도 않으므로 순서에 영향받지 않는다.\n실무: 다만 <b>자동으로 병렬이 되는 것은 아니다</b> — '나눠도 안전하다' 는 보장을 줄 뿐이고, 실제로 나눌지는 우리가 정한다. 그리고 나누고 합치는 비용이 있으니 작은 작업은 오히려 느려진다."},{"t":"choice","k":"읽기만 하면 락이 필요 없다","cat":"perf","q":"여러 스레드가 같은 불변 객체를 읽는다. 락이 필요 없는 이유와, 락을 쓰면 어떻게 되는가?","code":"불변 설정 객체 하나를 스레드 8개가 계속 읽는다","o":["락을 걸어야 캐시 일관성이 보장되므로 반드시 필요하다","락을 걸어도 성능에 영향이 없으므로 안전하게 걸어 두는 편이 낫다","값이 바뀌지 않으니 언제 읽어도 같은 것을 본다","불변 객체도 읽기 락은 필요하며 쓰기 락만 생략할 수 있다"],"a":2,"ex":"'혹시 모르니 락' 이 실제로 비용을 만드는 자리.\n개념: 락의 값어치는 변경을 순서대로 만드는 데 있다. 변경이 없으면 순서를 정할 것이 없다. 반면 락 자체는 코어 사이에서 상태를 주고받아야 해서, 경합이 없어도 비용이 있고 경합하면 훨씬 커진다.\n실무: 설정, 참조 표, 한 번 만들고 안 바꾸는 데이터는 불변으로 만들어 공유하는 것이 가장 빠르다. 다만 <b>'만드는 도중' 이 안전하게 끝났는지</b>는 보장해야 한다 — 다 만들어진 뒤에 공개하는 것이 원칙이다.\n왜 그 답인가: 락을 걸면 안전해지는 것 없이 <b>스레드들이 줄을 서게 되어</b> 오히려 느려진다"},{"t":"choice","k":"겉만 불변일 때","cat":"debug","q":"객체를 <code>const</code> 로 선언하고 필드도 바꾸지 않는데, 여전히 동시성 문제가 생긴다. 무엇을 놓쳤을 수 있는가?","code":"const conf = { name: 'a', tags: ['x'] };\n// conf 는 안 바꾼다\nconf.tags.push('y');   // ← 안쪽은?","o":["자바스크립트 객체는 원래부터 불변으로 만들 수 없으므로 락을 거는 것이 유일한 해결책","가비지 컬렉터가 객체를 옮기면서 생기는 문제다","const 는 재할당만 막고 값 자체는 언제든 바뀌므로 불변성과 무관하다는 뜻이며, 필드도 함께 바꿔야 한다","겉만 못 바꾸게 했을 뿐 안에 들어 있는 배열이나 객체는 여전히 가변이기 때문이다"],"a":3,"ex":"'한 겹만 얼린 것' 은 불변이 아니다.\n개념: 바깥 참조를 고정해도 그 참조가 가리키는 안쪽은 그대로 바뀔 수 있다. 다른 스레드가 그 배열을 읽는 동안 누군가 밀어 넣으면 앞에서 본 경쟁 조건이 그대로 성립한다.\n실무: 두 번째 보기도 절반은 맞는 말이지만 초점이 다르다 — 문제는 '재할당' 이 아니라 <b>안쪽 가변성</b>이다. 안쪽까지 얼리거나, 값을 넣을 때 복사본을 만들거나, 애초에 불변 컬렉션을 쓴다. 얼리는 비용이 크다면 <b>공유하는 경계에서만</b> 얼려도 된다.\n왜 그 답인가: 진짜 불변이 되려면 안쪽까지 내려가며 얼려야 한다"}],"th":{"sum":"함수형이 주는 가장 실질적인 이득은 <b>여럿이 동시에 돌 때</b> 드러난다. 동시성 버그의 뿌리는 '<b>누군가 읽는 동안 다른 누군가 바꾼다</b>' 인데, 바꾸지 않으면 그 조건 자체가 성립하지 않기 때문이다.","body":[{"h":"세 가지가 겹쳐야 사고가 난다","t":"데이터 경쟁은 <b>공유되고 · 변경되고 · 동시에 접근될 때</b> 생긴다. 락은 마지막 하나를 막는 방법이고, 불변성은 <b>가운데 하나를 없애는</b> 방법이에요. 값이 안 바뀌면 몇 개의 스레드가 읽든 아무 조율이 필요 없다."},{"h":"나눠서 합치려면 규칙이 필요하다","t":"<code>map</code> 은 원소끼리 독립이라 그냥 나눠 돌리면 된다. 하지만 <code>reduce</code> 를 나누려면 <b>어디서 끊어 합쳐도 결과가 같아야</b> 해요 — 이것이 결합법칙이다. 여기에 <b>빈 조각에 쓸 항등원</b>까지 있으면 조각 수와 상관없이 안전하게 합칠 수 있다."},{"h":"순수함수라는 전제가 깨지면 전부 무너진다","t":"'순수한 줄 알았는데 아니었던' 함수는 혼자 돌 때는 멀쩡하다가 <b>동시에 돌 때 처음 드러난다</b>. 내부 카운터 하나, 공유 캐시 한 줄이면 충분해요. 그리고 이런 버그는 <b>재현이 어렵다</b> — 타이밍이 맞아야만 나타나기 때문이다."}],"code":{"t":"나눠 합치려면 무엇이 필요한가","c":"map    [a,b,c,d] → 원소끼리 독립 → 아무렇게나 나눠도 된다\n\nreduce (((a+b)+c)+d)  를  ((a+b) + (c+d))  로 바꿔도 되려면\n         결합법칙:  (x ⊕ y) ⊕ z  =  x ⊕ (y ⊕ z)\n\n빈 조각이 생길 수 있으니\n         항등원:    x ⊕ e = x\n\n되는 것    + · × · min · max · 문자열 잇기 · 집합 합치기\n안 되는 것  −  ÷  평균  (그대로는 나눠 합칠 수 없다)"},"key":["데이터 경쟁은 공유·변경·동시 셋이 겹쳐야 생긴다","map 은 독립적이라 쉽고, reduce 는 결합법칙이 있어야 나뉜다","빈 조각을 다루려면 항등원이 필요하다","순수한 줄 알았던 함수는 동시에 돌 때 정체를 드러낸다"]}},{"t":"불변성과 병렬 II","q":[{"t":"choice","k":"map 이 쉬운 이유","q":"<code>map</code> 은 병렬로 나누기 쉽지만 <code>reduce</code> 는 그렇지 않다. 무엇이 다른가?","code":"map     [a,b,c,d] → [f(a),f(b),f(c),f(d)]\nreduce  (((a⊕b)⊕c)⊕d)","o":["map 은 원소마다 계산이 서로 독립이라 아무렇게나 나눠도 되지만, reduce 는 앞의 결과를 다음에 넘기는 사슬 구조라 그냥 끊을 수 없다","reduce 는 순차 실행하도록 표준에 정해져 있기 때문이다","map 은 결과 크기를 미리 알 수 있고 reduce 는 알 수 없기 때문이다. 크기를 알면 미리 자리를 잡아 두고 나눠 쓸 수 있지만, 모르면 나눌 방법이 없다","<code>map</code> 은 순수함수만 받고 <code>reduce</code> 는 아니기 때문이다"],"a":0,"ex":"'독립' 과 '사슬' 이라는 두 모양이 병렬화 난이도를 가른다.\n개념: <code>map</code> 에서 <code>f(c)</code> 를 계산하려고 <code>f(a)</code> 를 기다릴 필요가 없다. <code>reduce</code> 는 정의상 왼쪽부터 접어 나가므로, 나누려면 '중간에서 끊어 각자 접은 뒤 합쳐도 같은가' 를 따로 보장해야 한다.\n실무: 그 보장이 다음 문제에서 볼 결합법칙이다. 조건이 맞으면 <code>reduce</code> 도 나눌 수 있고, 실제로 큰 데이터 처리 도구들이 그 조건을 요구한다."},{"t":"choice","k":"끊어 합쳐도 같으려면","cat":"internals","q":"<code>reduce</code> 를 두 조각으로 나눠 각자 접은 뒤 합치려 한다. 연산이 만족해야 하는 성질은?","code":"순차   ((a⊕b)⊕c)⊕d\n병렬   (a⊕b) ⊕ (c⊕d)\n둘이 같으려면?","o":["교환법칙 — 순서를 바꿔도 결과가 같아야 한다","<b>결합법칙</b> — 묶는 위치를 바꿔도 결과가 같아야 한다.","분배법칙 — 두 연산이 서로 나눠 들어갈 수 있어야 한다","멱등성 — 두 번 적용해도 결과가 같아야 한다"],"a":1,"ex":"'묶는 위치' 와 '순서' 를 헷갈리기 쉽다.\n개념: 병렬 축약은 조각마다 따로 접은 뒤 그 결과들을 다시 접는다. 즉 <b>괄호의 위치가 달라진다</b>. 원소의 순서 자체는 유지되므로 교환법칙까지는 필요 없다 — 문자열 잇기가 좋은 예다. 순서가 바뀌면 안 되지만 어디서 끊어 붙여도 결과는 같다.\n실무: 뺄셈은 <code>(10-3)-2 = 5</code> 인데 <code>10-(3-2) = 9</code> 라 나눌 수 없다. 하지만 '부호를 붙여 더하기' 로 바꾸면 덧셈이 되어 나눌 수 있다 — <b>연산을 결합 가능한 형태로 바꾸는 것</b>이 병렬화의 첫 단계인 경우가 많다.\n왜 그 답인가: 덧셈·곱셈·최댓값·문자열 잇기는 만족하지만 뺄셈과 나눗셈은 만족하지 않는다"},{"t":"choice","k":"빈 조각을 만나면","cat":"design","q":"데이터를 조각으로 나눴는데 어떤 조각은 <b>비어 있다</b>. 이때도 안전하게 합치려면 무엇이 더 필요한가?","code":"조각1 [1,2]  조각2 []  조각3 [3]\n빈 조각의 접은 결과는 무엇으로 둘까?","o":["빈 조각이 생기지 않도록 균등하게 나누는 수밖에 없다","빈 조각을 미리 제거하면 되므로 추가로 필요한 것은 없다","항등원이 필요하다","교환법칙이 있으면 빈 조각도 자연스럽게 처리된다"],"a":2,"ex":"결합법칙과 항등원이 함께 있는 구조를 모노이드라 부른다.\n개념: 항등원이 있으면 '아무것도 없음' 을 값으로 표현할 수 있다. 그러면 조각이 몇 개든, 비어 있든, 코드가 한 가지 경로로 처리된다. 빈 조각을 미리 걸러 내는 방법도 되지만, 전체가 비었을 때 무엇을 돌려줄지는 여전히 정해야 한다.\n실무: 그래서 <code>reduce</code> 에 초기값을 주는 습관이 중요하다 — 초기값이 곧 항등원이고, 빈 배열에서 예외가 나지 않게 해 준다. 최솟값처럼 자연스러운 항등원이 없으면 <code>Infinity</code> 같은 값을 쓰거나 '없음' 을 표현하는 타입으로 감싼다.\n왜 그 답인가: 합쳐도 상대를 바꾸지 않는 값(덧셈은 0, 곱셈은 1, 문자열은 빈 문자열)을 빈 조각의 결과로 쓰면 조각 수와 상관없이 같은 답이 나온다"},{"t":"choice","k":"평균은 왜 안 되나","cat":"debug","q":"각 조각의 <b>평균</b>을 구한 뒤 그 평균들의 평균을 내면 전체 평균과 다르다. 왜 그렇고 어떻게 고치는가?","code":"조각1 [1,2,3] 평균 2\n조각2 [10]    평균 10\n평균의 평균 6   ·   전체 평균 4","o":["부동소수 오차 때문이며 정밀도를 높이면 일치한다","평균은 원래 병렬로 구할 수 없는 연산이다","조각 크기를 모두 같게 나누는 것 말고는 방법이 없다","평균은 결합법칙을 만족하지 않기 때문이다"],"a":3,"ex":"'결합 가능한 형태로 바꾸기' 의 가장 좋은 예다.\n개념: 평균 자체는 나눠 합칠 수 없지만, <b>(합, 개수)</b> 라는 쌍으로 바꾸면 그 쌍의 덧셈은 결합법칙을 만족한다. 조각마다 쌍을 만들어 더한 뒤 마지막에 한 번 나누면 된다. 항등원은 (0, 0) 이다.\n실무: 같은 요령이 분산·표준편차·상위 k개·중복 없는 개수 추정에도 쓰인다 — <b>중간에 무엇을 들고 다닐지</b>를 잘 고르면 대부분의 집계가 나뉜다. 분산 데이터 처리 프레임워크의 집계 함수들이 전부 이 모양으로 설계되어 있다.\n왜 그 답인가: 조각마다 <b>합과 개수를 함께</b> 들고 합친 뒤 <b>마지막에 한 번만 나누면</b> 나눠 계산해도 정확하다"}],"th":{"sum":"함수형이 주는 가장 실질적인 이득은 <b>여럿이 동시에 돌 때</b> 드러난다. 동시성 버그의 뿌리는 '<b>누군가 읽는 동안 다른 누군가 바꾼다</b>' 인데, 바꾸지 않으면 그 조건 자체가 성립하지 않기 때문이다.","body":[{"h":"세 가지가 겹쳐야 사고가 난다","t":"데이터 경쟁은 <b>공유되고 · 변경되고 · 동시에 접근될 때</b> 생긴다. 락은 마지막 하나를 막는 방법이고, 불변성은 <b>가운데 하나를 없애는</b> 방법이에요. 값이 안 바뀌면 몇 개의 스레드가 읽든 아무 조율이 필요 없다."},{"h":"나눠서 합치려면 규칙이 필요하다","t":"<code>map</code> 은 원소끼리 독립이라 그냥 나눠 돌리면 된다. 하지만 <code>reduce</code> 를 나누려면 <b>어디서 끊어 합쳐도 결과가 같아야</b> 해요 — 이것이 결합법칙이다. 여기에 <b>빈 조각에 쓸 항등원</b>까지 있으면 조각 수와 상관없이 안전하게 합칠 수 있다."},{"h":"순수함수라는 전제가 깨지면 전부 무너진다","t":"'순수한 줄 알았는데 아니었던' 함수는 혼자 돌 때는 멀쩡하다가 <b>동시에 돌 때 처음 드러난다</b>. 내부 카운터 하나, 공유 캐시 한 줄이면 충분해요. 그리고 이런 버그는 <b>재현이 어렵다</b> — 타이밍이 맞아야만 나타나기 때문이다."}],"code":{"t":"나눠 합치려면 무엇이 필요한가","c":"map    [a,b,c,d] → 원소끼리 독립 → 아무렇게나 나눠도 된다\n\nreduce (((a+b)+c)+d)  를  ((a+b) + (c+d))  로 바꿔도 되려면\n         결합법칙:  (x ⊕ y) ⊕ z  =  x ⊕ (y ⊕ z)\n\n빈 조각이 생길 수 있으니\n         항등원:    x ⊕ e = x\n\n되는 것    + · × · min · max · 문자열 잇기 · 집합 합치기\n안 되는 것  −  ÷  평균  (그대로는 나눠 합칠 수 없다)"},"key":["데이터 경쟁은 공유·변경·동시 셋이 겹쳐야 생긴다","map 은 독립적이라 쉽고, reduce 는 결합법칙이 있어야 나뉜다","빈 조각을 다루려면 항등원이 필요하다","순수한 줄 알았던 함수는 동시에 돌 때 정체를 드러낸다"]}},{"t":"불변성과 병렬 III","q":[{"t":"choice","k":"결과 순서가 뒤섞이나","q":"여러 항목을 병렬로 변환했다. 결과 배열의 <b>순서</b>는 어떻게 되는가?","code":"입력  [a, b, c, d]\n완료 순서  c, a, d, b  (제각각)\n결과 배열은?","o":["구현에 따라 다르다","완료된 순서대로 담기므로 순서가 보장되지 않는다","순서는 정렬을 따로 해야만 정해진다","입력 순서가 유지되므로 신경 쓸 필요가 없다"],"a":0,"ex":"'병렬이면 순서가 섞인다' 도 '항상 유지된다' 도 둘 다 틀렸다.\n개념: 실행 순서와 결과 배치는 별개다. 각 결과를 원래 인덱스 자리에 써 넣으면 실행이 뒤죽박죽이어도 순서가 유지된다. 반면 완료되는 대로 목록에 밀어 넣는 방식은 순서가 실행 타이밍을 따라간다.\n실무: 순서에 기대는 코드를 쓰기 전에 <b>쓰는 도구가 어느 쪽인지 확인</b>한다. 그리고 순서가 유지되더라도 <b>부수효과의 순서는 보장되지 않는다</b> — 로그가 뒤섞여 찍히는 것이 대표적이다.\n왜 그 답인가: 대부분의 병렬 <code>map</code> 은 <b>결과를 원래 자리에 넣어 입력 순서를 유지</b>하지만, 완료되는 대로 모으는 방식이라면 순서가 섞인다. 무엇을 쓰는지 확인해야 한다"},{"t":"choice","k":"실수 덧셈은 결합법칙이 깨진다","cat":"debug","q":"실수 배열의 합을 병렬로 구했더니 <b>실행할 때마다 마지막 자릿수가 다르다</b>. 원인은?","code":"(0.1 + 0.2) + 0.3 = 0.6000000000000001\n0.1 + (0.2 + 0.3) = 0.6","o":["병렬 실행 자체가 부동소수 결과를 바꾸지는 않으므로 코드 버그다","부동소수 덧셈은 결합법칙을 만족하지 않는다","여러 스레드가 같은 변수에 더해 경쟁이 생긴 것이다","실수 연산이 스레드마다 다른 정밀도로 수행되기 때문이다"],"a":1,"ex":"수학에서 참인 법칙이 부동소수에서는 참이 아닌 대표적인 자리.\n개념: 실수 덧셈은 매 단계에서 결과를 표현 가능한 값으로 반올림한다. 그래서 어떤 순서로 더하느냐에 따라 반올림이 쌓이는 모양이 달라진다. 위 예에서 두 값이 실제로 다르다.\n실무: 재현성이 필요하면 <b>조각 나누는 방식을 고정</b>해 항상 같은 순서로 합치거나, 순차로 계산한다. 정확도가 중요하면 보정 합산 알고리즘을 쓰거나 정수·고정소수점으로 다룬다. 금액을 실수로 다루면 안 되는 이유가 여기에도 있다.\n왜 그 답인가: 어디서 끊어 합치느냐에 따라 반올림이 달라지고, 병렬에서는 조각 나누기가 실행마다 달라질 수 있어 결과가 흔들린다"},{"t":"choice","k":"순수한 줄 알았던 함수","cat":"review","q":"혼자 돌릴 때는 멀쩡하다가 <b>병렬로 돌리자 결과가 이상해지는</b> 함수가 있다. 무엇을 의심해야 하는가?","code":"let 호출수 = 0;\nfunction 변환(x){ 호출수++; return 무거운계산(x); }","o":["함수가 너무 무거워 타임아웃이 난 것이다","병렬 실행은 원래 결과가 달라질 수 있으므로 정상이다","순수하지 않은 부분이 숨어 있는지 본다","스레드 수를 줄이면 근본적으로 해결된다"],"a":2,"ex":"'순수함수만 병렬로 돌려라' 를 지켰다고 생각했는데 아니었던 경우.\n개념: 순수성은 겉으로 잘 안 보인다. 진단용 카운터, 결과를 기억해 두는 표, 지연 초기화 같은 것이 슬쩍 들어가 있으면 혼자 돌 때는 티가 안 난다. 동시에 돌면 그 공유 지점에서 값이 어긋나거나 사라진다.\n실무: 공유 캐시는 특히 흔하다 — 메모이제이션은 결과만 보면 순수하지만 <b>표를 여럿이 동시에 고치면</b> 깨진다. 그래서 동시성이 있는 곳에서는 스레드 안전한 자료구조를 쓰거나, 캐시를 스레드마다 따로 둔다.\n왜 그 답인가: <b>내부 카운터, 공유 캐시, 모듈 수준 변수, 인자 원본 수정</b> 같은 것이 하나만 있어도 동시에 돌 때 어긋난다"},{"t":"choice","k":"재현이 안 되는 버그","cat":"debug","q":"동시성 버그가 <b>운영에서는 나는데 개발에서는 재현이 안 되는</b> 근본 이유는?","code":"필요한 조건: 두 스레드가 아주 짧은 구간에서 겹쳐야 함\n개발 환경: 부하 낮음 · 코어 적음 · 타이밍 다름","o":["운영 환경에만 있는 설정 차이 때문이며 타이밍과는 무관하다","개발 환경의 컴파일러 최적화 수준이 달라서다","동시성 버그는 원래 결정적이므로 재현이 안 된다면 다른 원인을 봐야 한다. 같은 코드에 같은 입력이면 같은 결과가 나오는 것이 원칙이므로 환경 차이를 먼저 의심한다","버그가 나려면 특정 타이밍이 맞아야 하는데 그 창이 아주 짧기 때문이다 — 부하·코어 수·스케줄링이 다르면 그 창에 들어갈 확률이 크게 달라진다"],"a":3,"ex":"'내 컴퓨터에서는 안 나는데요' 가 가장 잘 들어맞는 종류의 버그.\n개념: 경쟁 조건은 두 접근이 아주 짧은 구간에서 겹쳐야 나타난다. 그 확률은 코어 수, 동시 요청 수, 스케줄링에 따라 몇 자릿수씩 달라진다. 개발 기기에서 몇 번 돌려 안 났다는 것은 <b>없다는 증거가 아니다</b>.\n실무: 그래서 이런 버그는 재현을 노리기보다 <b>구조적으로 불가능하게</b> 만드는 편이 빠르다 — 공유를 없애거나 불변으로 바꾸는 것이다. 재현이 꼭 필요하면 부하를 올리고 코어를 늘리고 일부러 지연을 끼워 넣어 창을 벌린다."}],"th":{"sum":"함수형이 주는 가장 실질적인 이득은 <b>여럿이 동시에 돌 때</b> 드러난다. 동시성 버그의 뿌리는 '<b>누군가 읽는 동안 다른 누군가 바꾼다</b>' 인데, 바꾸지 않으면 그 조건 자체가 성립하지 않기 때문이다.","body":[{"h":"세 가지가 겹쳐야 사고가 난다","t":"데이터 경쟁은 <b>공유되고 · 변경되고 · 동시에 접근될 때</b> 생긴다. 락은 마지막 하나를 막는 방법이고, 불변성은 <b>가운데 하나를 없애는</b> 방법이에요. 값이 안 바뀌면 몇 개의 스레드가 읽든 아무 조율이 필요 없다."},{"h":"나눠서 합치려면 규칙이 필요하다","t":"<code>map</code> 은 원소끼리 독립이라 그냥 나눠 돌리면 된다. 하지만 <code>reduce</code> 를 나누려면 <b>어디서 끊어 합쳐도 결과가 같아야</b> 해요 — 이것이 결합법칙이다. 여기에 <b>빈 조각에 쓸 항등원</b>까지 있으면 조각 수와 상관없이 안전하게 합칠 수 있다."},{"h":"순수함수라는 전제가 깨지면 전부 무너진다","t":"'순수한 줄 알았는데 아니었던' 함수는 혼자 돌 때는 멀쩡하다가 <b>동시에 돌 때 처음 드러난다</b>. 내부 카운터 하나, 공유 캐시 한 줄이면 충분해요. 그리고 이런 버그는 <b>재현이 어렵다</b> — 타이밍이 맞아야만 나타나기 때문이다."}],"code":{"t":"나눠 합치려면 무엇이 필요한가","c":"map    [a,b,c,d] → 원소끼리 독립 → 아무렇게나 나눠도 된다\n\nreduce (((a+b)+c)+d)  를  ((a+b) + (c+d))  로 바꿔도 되려면\n         결합법칙:  (x ⊕ y) ⊕ z  =  x ⊕ (y ⊕ z)\n\n빈 조각이 생길 수 있으니\n         항등원:    x ⊕ e = x\n\n되는 것    + · × · min · max · 문자열 잇기 · 집합 합치기\n안 되는 것  −  ÷  평균  (그대로는 나눠 합칠 수 없다)"},"key":["데이터 경쟁은 공유·변경·동시 셋이 겹쳐야 생긴다","map 은 독립적이라 쉽고, reduce 는 결합법칙이 있어야 나뉜다","빈 조각을 다루려면 항등원이 필요하다","순수한 줄 알았던 함수는 동시에 돌 때 정체를 드러낸다"]}},{"t":"불변성과 병렬 IV","q":[{"t":"choice","k":"나누면 손해인 경우","cat":"perf","q":"배열 1,000개짜리 <code>map</code> 을 병렬로 바꿨더니 <b>더 느려졌다</b>. 왜 그런가?","code":"원소당 계산  아주 짧음\n나누고 넘기고 모으는 비용  고정으로 붙음","o":["나누고 각 조각을 넘기고 결과를 모으는 고정 비용이 실제 계산보다 크기 때문이다 — 원소가 적거나 원소당 계산이 가벼우면 순차가 빠르다","병렬 실행은 언제나 더 느리며 아주 큰 데이터에서만 예외적으로 빠르다 — 스레드를 만들고 동기화하는 비용이 워낙 커서 수백만 원소는 되어야 본전을 찾는다","자바스크립트는 병렬 실행을 지원하지 않기 때문이다 — 단일 스레드 언어라 '병렬' 이라 부르는 것은 실제로는 번갈아 도는 것이고, 전환 비용만 더해져 느려진다","배열은 병렬화할 수 없고 스트림으로 바꿔야 한다 — 배열은 인덱스로 묶여 있어 조각으로 나눌 수 없고, 지연 평가되는 스트림이어야 조각마다 독립적으로 계산된다"],"a":0,"ex":"병렬화는 공짜가 아니라 <b>고정 비용을 내고 사는 것</b>이다.\n개념: 조각을 만들고, 다른 실행 단위로 넘기고, 끝나기를 기다리고, 결과를 모으는 데 비용이 든다. 이 비용은 데이터가 작아도 그대로 붙는다. 그래서 '충분히 크고 충분히 무거울 때' 만 이득이 남는다.\n실무: 임계점은 환경마다 다르니 <b>재 보고 정한다</b>. 그리고 데이터를 스레드 사이로 넘길 때 복사가 일어나는 환경이라면 비용이 훨씬 커진다 — 이 경우 불변 자료구조의 구조 공유가 복사를 줄여 주기도 한다."},{"t":"choice","k":"일관된 한 장면 보기","cat":"design","q":"여러 값을 함께 읽어 보고서를 만드는 동안 다른 쪽에서 값이 계속 바뀐다. 불변 자료구조가 여기서 주는 것은?","code":"읽는 중  A=1 … (다른 쪽에서 갱신) … B=99\n결과: A 는 옛 값, B 는 새 값 — 섞인 장면","o":["읽는 동안 다른 쪽의 갱신을 자동으로 막아 준다","현재 상태의 참조 하나를 붙잡으면 그 시점의 장면이 통째로 고정된다 — 뒤이은 갱신은 새 값을 만들 뿐 내가 든 것을 바꾸지 않으므로, 락 없이 일관된 스냅샷을 읽을 수 있다","불변 자료구조로는 여러 값을 함께 읽는 문제를 해결할 수 없다. 값이 바뀌지 않더라도 어느 시점의 것을 읽었는지는 여전히 알 수 없으므로, 결국 읽는 동안 락을 걸어 갱신을 막는 수밖에 없다","값이 바뀔 때마다 알림을 보내 다시 읽게 해 준다"],"a":1,"ex":"'읽는 동안 세상이 멈추지 않는' 문제의 함수형 해법.\n개념: 가변 구조에서는 읽는 중간에 값이 바뀌어 <b>어느 시점도 아닌 장면</b>이 만들어진다. 불변 구조에서는 갱신이 기존 값을 건드리지 않고 새 값을 만들므로, 참조를 한 번 붙잡은 순간이 그대로 일관된 시점이 된다.\n실무: 데이터베이스의 스냅샷 격리와 발상이 같다. 다만 오래 붙잡고 있으면 그 시점의 데이터가 <b>메모리에 계속 남는다</b> — 긴 작업에서는 무엇을 얼마나 오래 들고 있는지 봐야 한다."},{"t":"choice","k":"공유하지 말고 건네기","cat":"design","q":"상태를 공유하는 대신 <b>메시지로 주고받는</b> 방식이 동시성을 다루기 쉽게 만드는 이유는?","code":"공유  여럿이 같은 상태를 직접 고친다 → 조율 필요\n전달  상태는 한 곳에만 · 나머지는 요청을 보낸다","o":["메시지 전달은 단일 스레드에서만 동작하므로 경쟁이 없다","메시지를 쓰면 순서가 자동으로 보장되어 모든 동시성 문제가 사라지기 때문이다. 보낸 순서대로 도착하고 그 순서대로 처리되므로 경쟁도 교착도 아예 생길 수 없게 된다","상태를 <b>한 곳만 소유</b>하고 나머지는 메시지를 보내므로, 그 한 곳이 메시지를 <b>하나씩 처리</b>하면 경쟁 자체가 생기지 않는다 — 앞서 본 '공유' 조건을 없애는 방법이다","메시지 전달이 락보다 빠르기 때문이다"],"a":2,"ex":"불변성이 '변경' 을 없앴다면 이쪽은 '공유' 를 없앤다.\n개념: 상태를 가진 쪽이 하나뿐이고 그쪽이 요청을 순서대로 처리하면, 내부에서는 동시성을 신경 쓸 필요가 없다. 바깥에서는 여럿이 동시에 요청을 보내도 되고, 그 조율은 메시지 큐가 맡는다.\n실무: 대신 새로운 문제가 생긴다 — 메시지가 순서대로 도착하지 않을 수 있고, 답을 기다리다 교착에 빠질 수 있고, 큐가 밀릴 수 있다. <b>문제가 사라진 게 아니라 다루기 쉬운 모양으로 옮겨진 것</b>이다."},{"t":"choice","k":"남는 문제","cat":"review","q":"코드를 전부 순수하게 만들고 자료구조를 불변으로 바꿨다. 그래도 <b>남는</b> 동시성 문제는?","code":"순수 함수 · 불변 자료구조로 다 바꿨다\n그래도 프로그램은 파일을 쓰고 요청을 보내고 화면을 갱신한다","o":["아무 문제도 남지 않는다 — 순수성과 불변성이 동시성 문제를 전부 없애 준다. 공유도 변경도 함께 사라지면 겹칠 것이 없으므로 조율할 대상 자체가 남지 않는다","성능 문제만 남고 정확성 문제는 사라진다","단일 스레드로 바꾸는 것 말고는 남은 문제를 다룰 방법이 없다","바깥과 주고받는 일은 여전히 남는다 — 파일·네트워크·화면 갱신의 순서와 조율, 어느 것을 먼저 반영할지, 실패했을 때 되돌릴지는 순수성으로 해결되지 않는다"],"a":3,"ex":"함수형은 동시성을 <b>없애 주는 것이 아니라 좁혀 주는 것</b>이다.\n개념: 계산 부분에서 경쟁이 사라지면 남는 것은 바깥과 닿는 얇은 층뿐이다. 그 층에서는 여전히 순서, 원자성, 실패 처리, 재시도를 다뤄야 한다. 다만 <b>다뤄야 할 면적이 훨씬 줄어든다</b>는 것이 이득이다.\n실무: 그래서 '함수형 코어, 명령형 셸' 구조가 동시성에서도 그대로 값을 한다 — 조율이 필요한 코드가 한곳에 모여 있으면 거기만 집중해서 검토하고 시험할 수 있다. 전부 순수하게 만들었다는 사실보다 <b>안 순수한 곳이 어디인지 아는 것</b>이 중요하다."}],"th":{"sum":"함수형이 주는 가장 실질적인 이득은 <b>여럿이 동시에 돌 때</b> 드러난다. 동시성 버그의 뿌리는 '<b>누군가 읽는 동안 다른 누군가 바꾼다</b>' 인데, 바꾸지 않으면 그 조건 자체가 성립하지 않기 때문이다.","body":[{"h":"세 가지가 겹쳐야 사고가 난다","t":"데이터 경쟁은 <b>공유되고 · 변경되고 · 동시에 접근될 때</b> 생긴다. 락은 마지막 하나를 막는 방법이고, 불변성은 <b>가운데 하나를 없애는</b> 방법이에요. 값이 안 바뀌면 몇 개의 스레드가 읽든 아무 조율이 필요 없다."},{"h":"나눠서 합치려면 규칙이 필요하다","t":"<code>map</code> 은 원소끼리 독립이라 그냥 나눠 돌리면 된다. 하지만 <code>reduce</code> 를 나누려면 <b>어디서 끊어 합쳐도 결과가 같아야</b> 해요 — 이것이 결합법칙이다. 여기에 <b>빈 조각에 쓸 항등원</b>까지 있으면 조각 수와 상관없이 안전하게 합칠 수 있다."},{"h":"순수함수라는 전제가 깨지면 전부 무너진다","t":"'순수한 줄 알았는데 아니었던' 함수는 혼자 돌 때는 멀쩡하다가 <b>동시에 돌 때 처음 드러난다</b>. 내부 카운터 하나, 공유 캐시 한 줄이면 충분해요. 그리고 이런 버그는 <b>재현이 어렵다</b> — 타이밍이 맞아야만 나타나기 때문이다."}],"code":{"t":"나눠 합치려면 무엇이 필요한가","c":"map    [a,b,c,d] → 원소끼리 독립 → 아무렇게나 나눠도 된다\n\nreduce (((a+b)+c)+d)  를  ((a+b) + (c+d))  로 바꿔도 되려면\n         결합법칙:  (x ⊕ y) ⊕ z  =  x ⊕ (y ⊕ z)\n\n빈 조각이 생길 수 있으니\n         항등원:    x ⊕ e = x\n\n되는 것    + · × · min · max · 문자열 잇기 · 집합 합치기\n안 되는 것  −  ÷  평균  (그대로는 나눠 합칠 수 없다)"},"key":["데이터 경쟁은 공유·변경·동시 셋이 겹쳐야 생긴다","map 은 독립적이라 쉽고, reduce 는 결합법칙이 있어야 나뉜다","빈 조각을 다루려면 항등원이 필요하다","순수한 줄 알았던 함수는 동시에 돌 때 정체를 드러낸다"]}}],"ord":6},{"t":"변환 자체를 값으로 — 트랜스듀서와 렌즈","g":"","l":[{"t":"값이 된 변환 I","q":[{"t":"choice","k":"무엇이 사라지는가","cat":"perf","q":"십만 개 배열에 <code>map</code> 과 <code>filter</code> 를 이어 쓴 것과 트랜스듀서로 합쳐 한 번 훑은 것을 비교했다. 무엇이 달라지는가?","code":"// 메서드 체인: map 100000번 · filter 100000번 · 중간 배열 1개(길이 100000)\n// 트랜스듀서 : map 100000번 · filter 100000번 · 중간 배열 없음","o":["변환 함수를 부르는 횟수는 같고, 사라지는 것은 중간 배열이다","변환 함수 호출 횟수가 절반으로 줄어든다","아무것도 달라지지 않는다 — 컴파일러가 알아서 합쳐 준다","filter 가 먼저 돌기 때문에 map 호출 횟수가 3분의 1로 준다"],"a":0,"ex":"직접 세어 본 값이다 — 양쪽 모두 map 100,000회, filter 100,000회.\n개념: 트랜스듀서를 '더 적게 계산하는 기법' 으로 오해하기 쉽다. 실제로 아끼는 것은 <b>단계마다 만들어지던 배열</b>이다. 원소가 크거나 단계가 많을수록 그 비용이 커진다.\n실무: 단계가 두어 개이고 배열이 작으면 메서드 체인이 더 낫다 — 읽기 쉽고 차이가 없다. 이득이 나타나는 자리는 큰 자료를 여러 단계로 흘릴 때다."},{"t":"choice","k":"결과는 같은가","q":"같은 map·filter 를 메서드 체인과 트랜스듀서로 각각 돌렸을 때 결과는?","code":"const A = into([], comp(mapT(sq), filterT(div3)), src);\nconst B = src.map(sq).filter(div3);\n// JSON.stringify(A) === JSON.stringify(B) → ?","o":["트랜스듀서 쪽에 중복이 생긴다","정확히 같다 — 같은 변환을 같은 순서로 적용하고 담는 방법만 다르다","부동소수점 오차 때문에 미세하게 달라진다","순서가 뒤집혀 나온다 — 트랜스듀서는 언제나 뒤에서부터 적용되기 때문이다"],"a":1,"ex":"실행해 확인했다 — <code>true</code>.\n개념: 트랜스듀서는 <b>같은 답을 다른 방법으로</b> 만든다. 결과가 달라진다면 그것은 최적화가 아니라 버그다.\n실무: 기존 파이프라인을 트랜스듀서로 바꿀 때는 두 결과를 대조하는 검사를 먼저 붙인다. 성능만 보고 바꾸면 조용한 차이를 놓친다."},{"t":"choice","k":"합성 방향","cat":"internals","q":"<code>comp(mapT(f), filterT(p))</code> 로 합치면 원소 하나에 대해 어떤 순서로 실행되는가?","code":"const t1 = mapT(x => { log(\"map \" + x); return x + 1; });\nconst t2 = filterT(x => { log(\"filter \" + x); return true; });\ninto([], comp(t1, t2), [10]);\n// 찍힌 순서: ?","o":["순서가 정해져 있지 않다","filter 10 → map 10 — 합성은 언제나 오른쪽부터 적용되기 때문이다","map 10 → filter 11 — 적은 순서대로 앞에서부터 적용된다","filter 11 → map 10 — 값이 뒤에서 앞으로 흐른다"],"a":2,"ex":"실행해 확인했다 — <code>['map 10', 'filter 11']</code>.\n개념: 트랜스듀서는 <b>step 을 감싸는 방향</b>과 <b>값이 흐르는 방향</b>이 반대다. 그래서 함수 합성을 평소처럼 오른쪽부터 적용하는 방식으로 써도, 값은 적은 순서대로 흐른다. 처음에 가장 헷갈리는 지점이다.\n실무: 헷갈리면 원소 하나를 넣고 로그를 찍어 보는 것이 가장 빠르다. 순서를 머리로 추론하려다 틀리는 경우가 많다."},{"t":"choice","k":"같은 변환, 다른 목적지","q":"같은 <code>xf</code> 로 배열에 담기·합계 구하기·개수 세기를 모두 할 수 있는 이유는?","code":"into([], xf, src);              // 배열   → 33333개\nsrc.reduce(xf((a,x) => a + x), 0);  // 합계   → 111112777761111\nsrc.reduce(xf(a => a + 1), 0);      // 개수   → 33333","o":["우연히 세 경우가 같은 모양이었을 뿐이며 조금만 달라져도 곧바로 안 되는 우연한","reduce 가 넘겨받은 결과 타입을 보고 알아서 자동으로 맞춰 주기 때문에 가능한 일이다","xf 안에 세 가지 목적지가 미리 들어 있기 때문이다","트랜스듀서는 <b>무엇을 할지</b>만 담고 <b>어디에 담을지</b>는 넘겨받은 step 이 정하기 때문이다"],"a":3,"ex":"세 값 모두 실행해 확인했다.\n개념: 이것이 트랜스듀서의 진짜 값어치다. <code>map</code>·<code>filter</code> 는 배열에 묶여 있지만, 트랜스듀서는 <b>배열·스트림·채널·문자열</b> 어디에든 같은 모양으로 붙는다.\n실무: 같은 필터 규칙을 목록 화면과 집계 화면에서 함께 쓰고 싶을 때, 규칙 하나를 두 곳에 넘기면 된다. 규칙이 두 벌로 갈려 어긋나는 일이 사라진다."}],"th":{"sum":"map·filter 를 이어 붙이면 중간 배열이 단계마다 생긴다. 변환을 값으로 만들어 먼저 합친 뒤 한 번만 훑으면 그 중간이 사라진다.","body":[{"t":"<code>xs.map(f).filter(p)</code> 는 읽기 좋지만 <b>중간 배열</b>을 하나 더 만든다. 원소가 십만 개면 십만 칸짜리 배열이 잠깐 살았다 죽는다. 단계가 늘수록 그런 배열도 늘어난다."},{"t":"트랜스듀서는 <b>'다음에 무엇을 할지'(step)를 받아 새 step 을 돌려주는 함수</b>다. map 도 filter 도 이 모양으로 쓰면 함수 합성으로 미리 이어 붙일 수 있고, 이어 붙인 것을 마지막에 딱 한 번 <code>reduce</code> 에 넘긴다. 중간 배열이 생길 자리가 없다."},{"t":"이어 붙인 변환은 <b>목적지와 무관</b>하다. 같은 변환으로 배열에 담을 수도, 합계로 접을 수도, 개수만 셀 수도 있다. 무엇을 할지(변환)와 어디에 담을지(step)가 분리되기 때문이다."},{"t":"다만 <code>reduce</code> 는 도중에 멈추지 못한다. 앞 세 개만 필요해도 끝까지 훑는다. 그래서 <b>'이제 그만' 신호</b>를 값에 실어 보내고, 훑는 쪽이 그것을 보면 멈추는 규칙을 함께 둔다."}],"code":{"c":"const mapT    = f => step => (acc, x) => step(acc, f(x));\nconst filterT = p => step => (acc, x) => p(x) ? step(acc, x) : acc;\nconst comp = (...fs) => fs.reduce((f, g) => (...a) => f(g(...a)));\n\nconst xf = comp(mapT(x => x * x), filterT(x => x % 3 === 0));\nsrc.reduce(xf((a, x) => (a.push(x), a)), []);   /* 중간 배열 없음 */"},"key":["트랜스듀서가 없애는 것은 호출 횟수가 아니라 중간 배열이다","합친 변환은 배열·합계·개수 어디에나 같은 모양으로 쓸 수 있다","reduce 는 멈추지 못하므로 조기 종료에는 별도 신호가 필요하다","렌즈는 '깊은 곳을 읽고 바꾸는 방법' 을 값으로 만든 것이다"]}},{"t":"값이 된 변환 II","q":[{"t":"choice","k":"멈추지 못한다","cat":"debug","q":"앞 3개만 필요해서 <code>takeT(3)</code> 을 합쳤는데도 원본 10만 개를 전부 훑었다. 왜인가?","code":"const early = comp(mapT(count), takeT(3));\ninto([], early, src);   // 결과 [1,2,3] · 훑은 개수 100000","o":["<code>reduce</code> 에는 도중에 멈출 방법이 없기 때문이다.","map 이 게으르지 않기 때문이며 map 을 제너레이터로 바꾸면 된다","take 를 합성의 앞쪽에 두었기 때문이다 — 뒤로 옮기면 멈춘다","훑은 개수를 잘못 셌을 뿐 실제로는 세 번만 돌았다"],"a":0,"ex":"실행해 확인했다 — 결과는 <code>[1,2,3]</code> 인데 훑은 개수는 100,000.\n개념: 답은 맞는데 일은 다 한다. 트랜스듀서는 <b>변환을 합치는 장치</b>이지 게으름을 주는 장치가 아니다.\n실무: 이 차이를 모르면 '트랜스듀서로 바꿨는데 왜 안 빨라지지' 에서 막힌다. 조기 종료가 필요하면 다음 문항의 신호 규칙을 함께 넣어야 한다.\n왜 그 답인가: take 는 3개를 넘긴 뒤 그냥 <b>아무것도 안 하고 통과</b>시킬 뿐이다"},{"t":"choice","k":"그만 신호","q":"조기 종료를 위해 '이제 그만' 신호를 도입했다. 훑는 쪽이 해야 할 일은?","code":"const reduced = v => ({ [REDUCED]: true, v });\n// 훑는 쪽\nfor (const x of src) {\n  const r = step(acc, x);\n  /* ??? */\n  acc = r;\n}","o":["step 이 알아서 멈추므로 훑는 쪽은 그대로 두면 된다","매 단계 결과가 '그만' 표시인지 확인하고, 맞으면 안에 든 값을 꺼내 즉시 반환한다","예외를 던져서 반복문을 빠져나오게 한다 — 다른 방법은 없으므로 그렇게 쓰는 것이 정석이다","결과가 undefined 인지 확인하면 된다"],"a":1,"ex":"신호를 붙이고 다시 재 보니 훑은 개수가 100,000 에서 <b>3</b> 으로 줄었다.\n개념: 값에 표시를 실어 보내고 바깥이 그것을 보는 방식이다. 예외로 빠져나오는 방법도 동작은 하지만, 정상 흐름에 예외를 쓰면 비용도 크고 다른 예외와 섞인다.\n실무: 실제 라이브러리(Clojure·transducers-js)가 쓰는 방식이 이것이다. 감싼 값을 벗기는 것을 잊으면 결과에 표시 객체가 그대로 새어 나간다."},{"t":"choice","k":"언제 쓰지 않는가","q":"어떤 경우에 트랜스듀서를 쓰지 않는 편이 나은가?","code":"const names = users.map(u => u.name);   // 20개짜리 배열, 한 단계","o":["변환이 순수하지 않을 때다 — 트랜스듀서는 순수 함수만 받는다","결과를 배열로 받고 싶을 때다 — 트랜스듀서로는 배열을 만들 수 없기 때문이다","원소가 적고 단계도 한둘일 때다 — 이득은 없고 읽기만 어려워진다","비동기가 섞일 때다 — 트랜스듀서는 동기 코드에서만 쓸 수 있다"],"a":2,"ex":"20개짜리 배열에서 중간 배열 하나를 아끼는 것은 의미가 없다.\n개념: 트랜스듀서는 <b>중간 배열이 아까울 만큼 클 때</b>와 <b>같은 변환을 여러 목적지에 쓸 때</b> 값어치가 있다. 그 둘 다 아니면 <code>map</code> 한 줄이 더 낫다.\n실무: 팀 코드에 트랜스듀서를 들일 때는 '어디에 쓰고 어디에 안 쓸지' 를 함께 정해 둔다. 안 그러면 모든 곳에 퍼지고 읽기 어려워진다."},{"t":"choice","k":"렌즈란 무엇인가","q":"렌즈(lens)를 한 문장으로 설명하면?","code":"const lens = (get, set) => ({ get, set });\nconst nameL = lens(o => o.name, (o, v) => ({ ...o, name: v }));","o":["타입을 검사해 주는 장치다","비동기 값을 감싸는 상자다","깊은 곳의 값을 바꾸려고 객체를 깊이 복사해 주는 함수 하나를 말한다","<b>깊은 곳을 읽는 방법과 바꾼 사본을 만드는 방법</b>을 한 값으로 묶은 것이다"],"a":3,"ex":"읽기(get)와 바꾸기(set) 한 쌍이 렌즈다.\n개념: 값으로 만들어 두면 <b>합칠 수 있다</b>. <code>user</code> 렌즈와 <code>address</code> 렌즈를 이으면 <code>user.address</code> 렌즈가 되고, 이어 놓은 것을 여기저기서 재사용할 수 있다.\n실무: 경로 문자열(\"user.address.city\")로 다루는 방법도 있지만 오타를 컴파일 시점에 못 잡는다. 렌즈는 그냥 함수라 이름을 잘못 쓰면 바로 걸린다."}],"th":{"sum":"map·filter 를 이어 붙이면 중간 배열이 단계마다 생긴다. 변환을 값으로 만들어 먼저 합친 뒤 한 번만 훑으면 그 중간이 사라진다.","body":[{"t":"<code>xs.map(f).filter(p)</code> 는 읽기 좋지만 <b>중간 배열</b>을 하나 더 만든다. 원소가 십만 개면 십만 칸짜리 배열이 잠깐 살았다 죽는다. 단계가 늘수록 그런 배열도 늘어난다."},{"t":"트랜스듀서는 <b>'다음에 무엇을 할지'(step)를 받아 새 step 을 돌려주는 함수</b>다. map 도 filter 도 이 모양으로 쓰면 함수 합성으로 미리 이어 붙일 수 있고, 이어 붙인 것을 마지막에 딱 한 번 <code>reduce</code> 에 넘긴다. 중간 배열이 생길 자리가 없다."},{"t":"이어 붙인 변환은 <b>목적지와 무관</b>하다. 같은 변환으로 배열에 담을 수도, 합계로 접을 수도, 개수만 셀 수도 있다. 무엇을 할지(변환)와 어디에 담을지(step)가 분리되기 때문이다."},{"t":"다만 <code>reduce</code> 는 도중에 멈추지 못한다. 앞 세 개만 필요해도 끝까지 훑는다. 그래서 <b>'이제 그만' 신호</b>를 값에 실어 보내고, 훑는 쪽이 그것을 보면 멈추는 규칙을 함께 둔다."}],"code":{"c":"const mapT    = f => step => (acc, x) => step(acc, f(x));\nconst filterT = p => step => (acc, x) => p(x) ? step(acc, x) : acc;\nconst comp = (...fs) => fs.reduce((f, g) => (...a) => f(g(...a)));\n\nconst xf = comp(mapT(x => x * x), filterT(x => x % 3 === 0));\nsrc.reduce(xf((a, x) => (a.push(x), a)), []);   /* 중간 배열 없음 */"},"key":["트랜스듀서가 없애는 것은 호출 횟수가 아니라 중간 배열이다","합친 변환은 배열·합계·개수 어디에나 같은 모양으로 쓸 수 있다","reduce 는 멈추지 못하므로 조기 종료에는 별도 신호가 필요하다","렌즈는 '깊은 곳을 읽고 바꾸는 방법' 을 값으로 만든 것이다"]}},{"t":"값이 된 변환 III","q":[{"t":"choice","k":"렌즈로 바꾸면","q":"렌즈로 깊은 값을 바꿨을 때 원본은 어떻게 되는가?","code":"const next = over(cityL, s => s.toUpperCase(), state);\n// state 는? next 의 손대지 않은 가지는?","o":["원본은 그대로이고, 손대지 않은 가지는 원본과 같은 객체다 — 바뀐 길목만 새로 만들어진다","원본도 함께 바뀐다 — 렌즈는 경로를 따라 내려가 그 자리의 값을 제자리에서 수정하므로 원본을 들고 있던 쪽도 새 값을 본다","원본은 그대로지만 전체가 깊이 복사되어 원본과 공유되는 객체가 없게 된다 — 안전을 위해 모든 가지를 새로 만들므로 메모리는 두 배가 된다","원본이 얼어붙어 더 이상 못 쓰게 된다 — 렌즈가 한 번 지나간 객체는 freeze 되어 이후의 수정 시도가 모두 예외로 끝난다"],"a":0,"ex":"렌즈의 set 이 각 층에서 얕은 복사만 하기 때문이다.\n개념: 이것이 불변 갱신의 구조 공유와 같은 이야기다. 렌즈는 그 갱신을 <b>재사용 가능한 값</b>으로 포장한 것이다.\n실무: 손대지 않은 가지가 같은 객체라는 사실 덕분에 <code>===</code> 하나로 '이 부분이 바뀌었는지' 를 알 수 있다. 화면을 다시 그릴지 정하는 데 그대로 쓰인다."},{"t":"choice","k":"렌즈를 잇는다","q":"<code>compose(userL, addressL, cityL)</code> 처럼 렌즈를 이어 붙이면 무엇을 얻는가?","code":"const deepL = compose(userL, addressL, cityL);\nview(deepL, state);        // state.user.address.city\nset(deepL, \"부산\", state);  // 그 자리만 바꾼 새 상태","o":["경로가 없으면 자동으로 만들어 준다","깊은 경로 하나를 이름 붙은 값으로 만들어 여러 곳에서 같이 쓸 수 있다","성능이 좋아진다 — 접근할 경로를 미리 계산해 두기 때문에 조회가 빨라진다","읽기 전용 뷰가 되어 바꿀 수 없게 된다"],"a":1,"ex":"합성이 렌즈의 핵심이다.\n개념: 같은 경로를 여러 파일에서 손으로 적으면 한 곳만 고쳤을 때 어긋난다. 렌즈로 만들어 두면 <b>경로가 한 군데에만 적힌다</b>.\n실무: 상태 구조를 바꿀 때 렌즈 정의만 고치면 쓰는 쪽은 그대로다. 상태 모양이 자주 바뀌는 초기 개발에서 특히 편하다."},{"t":"choice","k":"없는 경로","cat":"debug","q":"렌즈가 가리키는 중간 경로가 없을 때(<code>state.user</code> 가 undefined) 무엇이 문제가 되는가?","code":"const deepL = compose(userL, addressL, cityL);\nview(deepL, { });   // ?","o":["원본이 손상된다","렌즈가 중간에 없는 곳을 만나면 자동으로 빈 객체를 만들어 채워 주므로 아무 문제가 없다 — 경로가 중간에 끊겨 있어도 그대로 타고 내려간다","get 이 undefined 를 타고 내려가다 터지거나 조용히 undefined 를 돌려준다 — 없을 수 있는 경로는 별도로 다뤄야 한다","렌즈는 경로가 없으면 컴파일되지 않는다"],"a":2,"ex":"렌즈는 '반드시 있는 값' 을 가정한다.\n개념: 없을 수도 있는 자리에는 <b>프리즘</b>(있으면 보고 없으면 아무것도 안 하는 것)이라는 다른 도구를 쓴다. 렌즈로 억지로 다루면 조용한 undefined 가 흘러 다닌다.\n실무: 라이브러리를 안 쓰고 직접 만든다면, get 에서 중간이 없으면 명시적으로 실패를 돌려주도록 정해 두는 편이 낫다. '조용히 undefined' 가 가장 찾기 어렵다."},{"t":"choice","k":"무엇이 값이 되었나","q":"트랜스듀서와 렌즈가 공통으로 하는 일은?","code":"// 트랜스듀서: '어떻게 변환할지' 를 값으로\n// 렌즈      : '어디를 읽고 바꿀지' 를 값으로","o":["둘 다 타입 안전성을 높이는 장치다","둘 다 부수효과를 격리하는 장치다","둘 다 실행을 뒤로 미뤄 게으르게 만든다 — 실제로 필요해질 때까지 계산하지 않는다는 점이 공통이다","평소에는 코드에 흩어져 있던 방법 자체를 값으로 만들어, 합치고 넘기고 재사용할 수 있게 한다"],"a":3,"ex":"함수형에서 되풀이되는 한 가지 수법이다.\n개념: 값이 되면 <b>합칠 수 있고 이름을 줄 수 있고 인자로 넘길 수 있다</b>. 이 세 가지가 되는 순간 중복이 줄고 규칙이 한 군데로 모인다.\n실무: 새 추상을 들일지 판단할 때 이 기준으로 보면 된다 — 값이 되어 실제로 합쳐지고 재사용되는가, 아니면 이름만 어려워졌는가."}],"th":{"sum":"map·filter 를 이어 붙이면 중간 배열이 단계마다 생긴다. 변환을 값으로 만들어 먼저 합친 뒤 한 번만 훑으면 그 중간이 사라진다.","body":[{"t":"<code>xs.map(f).filter(p)</code> 는 읽기 좋지만 <b>중간 배열</b>을 하나 더 만든다. 원소가 십만 개면 십만 칸짜리 배열이 잠깐 살았다 죽는다. 단계가 늘수록 그런 배열도 늘어난다."},{"t":"트랜스듀서는 <b>'다음에 무엇을 할지'(step)를 받아 새 step 을 돌려주는 함수</b>다. map 도 filter 도 이 모양으로 쓰면 함수 합성으로 미리 이어 붙일 수 있고, 이어 붙인 것을 마지막에 딱 한 번 <code>reduce</code> 에 넘긴다. 중간 배열이 생길 자리가 없다."},{"t":"이어 붙인 변환은 <b>목적지와 무관</b>하다. 같은 변환으로 배열에 담을 수도, 합계로 접을 수도, 개수만 셀 수도 있다. 무엇을 할지(변환)와 어디에 담을지(step)가 분리되기 때문이다."},{"t":"다만 <code>reduce</code> 는 도중에 멈추지 못한다. 앞 세 개만 필요해도 끝까지 훑는다. 그래서 <b>'이제 그만' 신호</b>를 값에 실어 보내고, 훑는 쪽이 그것을 보면 멈추는 규칙을 함께 둔다."}],"code":{"c":"const mapT    = f => step => (acc, x) => step(acc, f(x));\nconst filterT = p => step => (acc, x) => p(x) ? step(acc, x) : acc;\nconst comp = (...fs) => fs.reduce((f, g) => (...a) => f(g(...a)));\n\nconst xf = comp(mapT(x => x * x), filterT(x => x % 3 === 0));\nsrc.reduce(xf((a, x) => (a.push(x), a)), []);   /* 중간 배열 없음 */"},"key":["트랜스듀서가 없애는 것은 호출 횟수가 아니라 중간 배열이다","합친 변환은 배열·합계·개수 어디에나 같은 모양으로 쓸 수 있다","reduce 는 멈추지 못하므로 조기 종료에는 별도 신호가 필요하다","렌즈는 '깊은 곳을 읽고 바꾸는 방법' 을 값으로 만든 것이다"]}},{"t":"값이 된 변환 IV","q":[{"t":"choice","k":"step 의 계약","cat":"internals","q":"트랜스듀서에 넘기는 step 함수가 지켜야 하는 것은?","code":"const step = (acc, x) => (acc.push(x), acc);   // 배열에 담기\nconst step2 = (acc, x) => acc + x;             // 합계","o":["누산값과 원소를 받아 <b>새 누산값을 돌려주는</b> 것","인자를 세 개 받아야 한다","새로운 배열 형태의 값을 돌려주어야 한다","순수 함수여야 하며 누산값을 바꾸면 안 된다"],"a":0,"ex":"계약은 '(누산, 원소) → 누산' 하나뿐이다.\n개념: 배열에 담는 step 은 실제로 <code>push</code> 로 제자리 변경을 한다. 함수형이지만 <b>누산기 안에서는</b> 바꿔도 된다 — 밖에서 안 보이기 때문이다.\n실무: 이 계약이 단순하기 때문에 트랜스듀서가 어디에든 붙는다. 새 목적지를 지원하려면 step 하나만 쓰면 된다.\n왜 그 답인가: 그 계약만 지키면 목적지는 무엇이든 된다"},{"t":"choice","k":"몇 번 훑는가","cat":"perf","q":"map → filter → map → filter 네 단계를 메서드 체인으로 쓰면 원본을 몇 번 훑고 배열을 몇 개 만드는가?","code":"xs.map(a).filter(b).map(c).filter(d)","o":["두 번 훑는다 — map 끼리, filter 끼리 합쳐진다","네 번 훑고 중간 배열 세 개(마지막 결과 제외)를 만든다","한 번 훑고 배열도 하나만 만든다 — 엔진이 합쳐 준다","네 번 훑지만 배열은 하나만 만든다"],"a":1,"ex":"단계마다 새 배열을 만들고 그 배열을 다시 훑는다.\n개념: 트랜스듀서로 합치면 훑기는 한 번, 중간 배열은 0개가 된다. 단계가 늘수록 차이가 커지는 이유다.\n실무: 자바스크립트 엔진은 이 합치기를 자동으로 해 주지 않는다. 배열이 크고 단계가 많으면 메모리 사용량 그래프에 그대로 나타난다."},{"t":"choice","k":"부수효과가 섞이면","cat":"debug","q":"트랜스듀서 안의 map 함수가 바깥 변수를 바꾼다. 무엇을 조심해야 하는가?","code":"let seen = 0;\nconst xf = comp(mapT(x => { seen++; return x; }), takeR(3));","o":["합성 순서와 무관하게 원본 개수만큼 불린다","부수효과가 있으면 결과가 항상 틀려진다","조기 종료가 있으면 몇 번 불릴지가 달라진다","트랜스듀서 안에서는 바깥 변수를 아예 읽을 수 없다"],"a":2,"ex":"직접 재 보니 신호가 없을 때 100,000번, 있을 때 3번 불렸다.\n개념: 순서와 횟수가 <b>구성에 따라 달라지는</b> 것이 함수형 파이프라인의 성질이다. 로그·카운터처럼 횟수가 의미를 갖는 부수효과를 안에 넣으면 결과가 흔들린다.\n실무: 세거나 기록할 일이 있으면 누산기에 담아 밖으로 흘려보낸다. 그러면 몇 번 불렸든 결과가 값에 남는다.\n왜 그 답인가: 부수효과 횟수가 변환 구성에 따라 바뀐다"},{"t":"choice","k":"무엇을 먼저 재는가","cat":"perf","q":"'파이프라인이 느리다' 는 말을 듣고 트랜스듀서 도입을 고민한다. 먼저 무엇을 확인하는가?","code":"// 후보: (1) 중간 배열 (2) 변환 함수 자체 (3) 원소 수 (4) 결과를 전부 쓰는가","o":["무조건 트랜스듀서로 바꾼다 — 항상 빨라진다","원소 수를 줄인다 — 그것 말고는 방법이 없다","메서드 체인을 for 문으로 바꾼다 — 중간 배열도 함수 호출도 사라지므로 결국 그것이 언제나 가장 빠른 방법이기 때문이다","시간이 어디에 쓰이는지부터 잰다 — 중간 배열이 아니라 변환 함수 하나가 비싼 것이라면 트랜스듀서로는 아무것도 안 바뀐다"],"a":3,"ex":"이 단원에서 확인한 대로 트랜스듀서는 <b>호출 횟수를 줄이지 않는다</b>.\n개념: 아끼는 것이 중간 배열이므로, 병목이 배열 할당이 아니면 효과가 없다. 재 보지 않고 도입하면 코드만 어려워진다.\n실무: 먼저 원소 수와 단계 수를 보고, 그다음 실제 시간을 잰다. 앞에서 본 것처럼 결과를 전부 쓰는지 일부만 쓰는지에 따라서도 답이 갈린다."}],"th":{"sum":"map·filter 를 이어 붙이면 중간 배열이 단계마다 생긴다. 변환을 값으로 만들어 먼저 합친 뒤 한 번만 훑으면 그 중간이 사라진다.","body":[{"t":"<code>xs.map(f).filter(p)</code> 는 읽기 좋지만 <b>중간 배열</b>을 하나 더 만든다. 원소가 십만 개면 십만 칸짜리 배열이 잠깐 살았다 죽는다. 단계가 늘수록 그런 배열도 늘어난다."},{"t":"트랜스듀서는 <b>'다음에 무엇을 할지'(step)를 받아 새 step 을 돌려주는 함수</b>다. map 도 filter 도 이 모양으로 쓰면 함수 합성으로 미리 이어 붙일 수 있고, 이어 붙인 것을 마지막에 딱 한 번 <code>reduce</code> 에 넘긴다. 중간 배열이 생길 자리가 없다."},{"t":"이어 붙인 변환은 <b>목적지와 무관</b>하다. 같은 변환으로 배열에 담을 수도, 합계로 접을 수도, 개수만 셀 수도 있다. 무엇을 할지(변환)와 어디에 담을지(step)가 분리되기 때문이다."},{"t":"다만 <code>reduce</code> 는 도중에 멈추지 못한다. 앞 세 개만 필요해도 끝까지 훑는다. 그래서 <b>'이제 그만' 신호</b>를 값에 실어 보내고, 훑는 쪽이 그것을 보면 멈추는 규칙을 함께 둔다."}],"code":{"c":"const mapT    = f => step => (acc, x) => step(acc, f(x));\nconst filterT = p => step => (acc, x) => p(x) ? step(acc, x) : acc;\nconst comp = (...fs) => fs.reduce((f, g) => (...a) => f(g(...a)));\n\nconst xf = comp(mapT(x => x * x), filterT(x => x % 3 === 0));\nsrc.reduce(xf((a, x) => (a.push(x), a)), []);   /* 중간 배열 없음 */"},"key":["트랜스듀서가 없애는 것은 호출 횟수가 아니라 중간 배열이다","합친 변환은 배열·합계·개수 어디에나 같은 모양으로 쓸 수 있다","reduce 는 멈추지 못하므로 조기 종료에는 별도 신호가 필요하다","렌즈는 '깊은 곳을 읽고 바꾸는 방법' 을 값으로 만든 것이다"]}}],"ord":7},{"t":"단답으로 확인하기 — 합성·커링·불변성","l":[{"t":"값을 함수 사이로 흘려보내기","xp":60,"th":{"sum":"함수형의 도구는 몇 개 안 된다 — **모으기·거르기·접기**, 그리고 그것을 잇는 **합성**과 **커링**.","body":[{"h":"순서와 방향","t":"<code>compose(f, g)</code> 는 수학 표기를 따라 <b>g 를 먼저</b> 하고, <code>pipe(f, g)</code> 는 <b>적은 순서대로</b> 흘려보낸다 — 같은 두 함수라도 순서가 바뀌면 값이 달라진다. <code>pipe</code> 는 <code>reduce</code> 로 세 줄이면 만들어진다. 커링은 인자를 <b>하나씩</b> 받는 사슬로 바꾸는 것이고, '설정을 미리 먹여 둔 함수' 를 만들 때 쓴다 — 인자 일부만 미리 먹이는 <b>부분 적용</b>과는 다르다."},{"h":"접기가 가장 일반적이다","t":"<code>map</code>·<code>filter</code>·<code>flatMap</code> 은 전부 <code>reduce</code> 로 만들 수 있지만 그 반대는 안 된다 — 표현력의 위아래가 정해져 있다. 그렇다고 전부 접기로 적으면 읽기 어려우니, 뜻이 분명한 이름을 쓰고 한 번에 끝내야 할 때만 접는다. <code>flatMap</code> 은 원소 하나가 <b>0 개 또는 여러 개</b>로 늘어날 때의 도구라, 버릴 원소에 빈 배열을 돌려주면 거르기까지 겸한다."}],"code":{"c":"const pipe = (...fs) => x => fs.reduce((v, fn) => fn(v), x);\ncompose(f, g)(3) === f(g(3))   // 오른쪽부터\nconst addTax = withRate(0.1);  // 설정을 먹여 둔 함수","cap":"값 하나가 함수들 사이를 지나간다"},"key":["compose 는 오른쪽부터, pipe 는 왼쪽부터","커링과 부분 적용은 다르다","reduce 가 가장 일반적인 형태","freeze 는 한 겹만 얼린다"]},"q":[{"t":"input","cat":"internals","k":"모으고 거르면 남는 것","q":"두 배로 바꾼 뒤 2 보다 큰 것만 남기면 무엇이 나올까요? 출력되는 JSON 을 그대로 적으세요. (예: [1,2])","code":"console.log(JSON.stringify([1, 2, 3].map(x => x * 2).filter(x => x > 2)));","a":["[4,6]"],"ex":"<code>map</code> 이 <code>[2,4,6]</code> 을 만들고 <code>filter</code> 가 2 보다 큰 <code>[4,6]</code> 만 남긴다.\n개념: 두 함수 모두 <b>새 배열을 돌려주고</b> 원본을 건드리지 않는다 — 그래서 이어 붙여 쓸 수 있다.\n실무: 이어 붙일 때마다 배열이 하나씩 더 만들어지므로, 데이터가 아주 크면 <code>reduce</code> 한 번이나 지연 평가로 합치는 편이 낫다."},{"t":"input","cat":"internals","k":"인자를 하나씩 받는 함수","q":"인자를 하나 받아 <b>또 함수를 돌려주는</b> 함수에 값을 두 번 넘기면 얼마가 될까요? 출력되는 값을 적으세요. (숫자)","code":"const add = a => b => a + b;\nconsole.log(add(2)(3));","a":["5"],"ex":"<code>add(2)</code> 는 '2 를 기억하는 함수' 를 돌려주고, 거기에 3 을 넘겨야 비로소 값이 나온다.\n개념: 이렇게 인자를 <b>한 번에 하나씩</b> 받도록 만드는 것을 커링이라 한다.\n실무: <code>const addTax = withRate(0.1)</code> 처럼 <b>설정을 미리 먹여 둔 함수</b>를 만들 때 쓰면, 호출부가 짧아지고 설정이 한 곳에 모인다."},{"t":"input","cat":"internals","k":"오른쪽부터 적용하기","q":"두 함수를 <b>수학에서 적듯이</b>(오른쪽 것을 먼저) 합성해 3 을 넘기면 얼마가 될까요? 출력되는 값을 적으세요. (숫자)","code":"const f = x => x + 1, g = x => x * 2;\nconst compose = (p, q) => x => p(q(x));\nconsole.log(compose(f, g)(3));","a":["7"],"ex":"<code>g(3) = 6</code> 을 먼저 하고 <code>f(6) = 7</code> 이다 — <code>f∘g</code> 는 '<b>g 를 먼저</b>' 다.\n개념: 합성은 결합법칙이 성립한다 — <code>compose(f, compose(g, h))</code> 와 <code>compose(compose(f, g), h)</code> 가 같다.\n실무: 순서를 헷갈리기 쉬워 실무에서는 <b>왼쪽부터 읽는</b> <code>pipe</code> 를 더 즐겨 쓴다."},{"t":"input","cat":"internals","k":"왼쪽부터 흘려보내기","q":"같은 두 함수를 <b>적은 순서대로</b> 흘려보내며 3 을 넘기면 얼마가 될까요? 출력되는 값을 적으세요. (숫자)","code":"const f = x => x + 1, g = x => x * 2;\nconst pipe = (...fs) => x => fs.reduce((v, fn) => fn(v), x);\nconsole.log(pipe(f, g)(3));","a":["8"],"ex":"<code>f(3) = 4</code>, <code>g(4) = 8</code> 이다. 같은 두 함수라도 순서가 바뀌면 값이 달라진다.\n개념: <code>pipe</code> 는 <code>reduce</code> 로 세 줄이면 만들어진다 — 값 하나를 함수들 사이로 흘려보내는 것이 전부다.\n실무: 데이터 변환을 <code>pipe(정규화, 검증, 저장모양으로)</code> 처럼 적으면 <b>단계 이름이 곧 문서</b>가 된다."},{"t":"input","cat":"internals","k":"식을 값으로 바꿔 써도 되는 성질","q":"같은 입력에 언제나 같은 출력을 주어, 식을 <b>그 결과값으로 바꿔 써도</b> 프로그램의 뜻이 안 변하는 성질을 무엇이라 부를까요? (한글 다섯 글자 또는 영문)","a":["참조투명성","referential transparency","참조투명","투명성"],"ex":"이 성질이 있으면 <b>메모이제이션·병렬 실행·순서 바꾸기</b>가 전부 안전해진다. 컴파일러의 최적화도 이 위에 서 있다.\n개념: 깨뜨리는 것은 대개 넷이다 — 전역 상태, 입출력, 현재 시각, 난수.\n실무: 시각과 난수를 <b>인자로 받게</b> 바꾸는 것만으로 테스트가 결정적으로 변한다."},{"t":"input","cat":"internals","k":"겉만 얼린 객체","q":"객체를 얼린 뒤 <b>안쪽 객체</b>의 값을 바꾸면 어떻게 될까요? 출력되는 값을 적으세요. (숫자)","code":"const o = Object.freeze({ inner: { v: 1 } });\no.inner.v = 2;\nconsole.log(o.inner.v);","a":["2"],"ex":"<code>Object.freeze</code> 는 <b>한 겹만</b> 얼린다. 안쪽 객체는 그대로라 값이 바뀐다.\n개념: 얕은 복사와 같은 함정이다 — 불변성은 <b>바뀌는 경로 위의 모든 층</b>에 걸어야 한다.\n실무: 깊게 얼리려면 재귀로 훑거나 아예 처음부터 <b>새로 만드는 갱신</b>만 허용하세요. 조용히 실패하는 것도 문제라, 개발 빌드는 엄격 모드로 두어 예외가 나게 하는 편이 낫다."},{"t":"input","cat":"internals","k":"접기로 모으기를 만들면","q":"<code>reduce</code> 만으로 '두 배로 바꾸기' 를 만들면 무엇이 나올까요? 출력되는 JSON 을 그대로 적으세요. (예: [1,2])","code":"console.log(JSON.stringify([1, 2, 3].reduce((a, x) => a.concat(x * 2), [])));","a":["[2,4,6]"],"ex":"<code>map</code>·<code>filter</code>·<code>flatMap</code> 은 전부 <code>reduce</code> 로 만들 수 있다 — <b>접기가 가장 일반적인 형태</b>다.\n개념: 반대로 <code>reduce</code> 는 <code>map</code> 으로 만들 수 없다. 표현력의 위아래가 정해져 있다.\n실무: 그렇다고 전부 <code>reduce</code> 로 적으면 읽기 어렵다 — 뜻이 분명한 <code>map</code>·<code>filter</code> 를 쓰고, 한 번에 끝내야 할 때만 접으세요."},{"t":"input","cat":"internals","k":"모으면서 한 겹 펴기","q":"중첩 배열을 <b>모으면서 한 겹 펴면</b> 무엇이 나올까요? 출력되는 JSON 을 그대로 적으세요. (예: [1,2])","code":"console.log(JSON.stringify([[1, 2], [3]].flatMap(x => x)));","a":["[1,2,3]"],"ex":"<code>flatMap</code> 은 <code>map</code> 뒤에 <code>flat(1)</code> 을 붙인 것과 같다.\n개념: 원소 하나가 <b>0 개 또는 여러 개</b>로 늘어날 수 있을 때 쓰는 도구라, <code>map</code>+<code>filter</code> 를 한 번에 대신할 수도 있다 — 버릴 원소는 빈 배열을 돌려주면 된다.\n실무: 중첩 응답을 평평하게 펼 때 <code>flatMap</code> 한 번이면 임시 배열을 안 만든다."}]},{"t":"빈 입력과 참조가 말해 주는 것","xp":60,"th":{"sum":"함수형의 보장은 **참조 투명성**에서 나오고, 그 보장을 확인하는 가장 좋은 입력은 **빈 것**과 **같은지 물어보는 것**이다.","body":[{"h":"참조 투명성과 그것을 깨는 넷","t":"같은 입력에 같은 출력을 주어 <b>식을 결과값으로 바꿔 써도</b> 뜻이 안 변하는 성질이다. 이 성질이 있으면 메모이제이션·병렬 실행·순서 바꾸기가 전부 안전해진다. 깨뜨리는 것은 대개 넷이다 — <b>전역 상태·입출력·현재 시각·난수</b>. 시각과 난수를 인자로 받게 바꾸는 것만으로 테스트가 결정적으로 변한다. 지연 평가는 안 쓰이는 값을 아예 계산하지 않아, 큰 파일도 한 줄씩 흘려보낼 수 있게 한다."},{"h":"빈 입력이 드러내는 항등원","t":"빈 배열에 '모두 참인가' 를 물으면 <b>참</b>(공허한 참)이고, '하나라도 참인가' 를 물으면 <b>거짓</b>이다. 두 값은 각 연산의 <b>항등원</b>이고, 같은 기준으로 <code>reduce</code> 의 초기값을 고른다 — 덧셈 0, 곱셈 1, 최댓값 <code>-Infinity</code>. '모든 항목이 승인됐으면 진행' 이 <b>목록이 비었을 때 통과</b>하는 것도 이 때문이다. 펼치기로 만든 객체는 참조가 달라지는데, 화면 라이브러리가 변경을 알아채는 근거가 바로 그것이다."}],"code":{"c":"[].every(x => false)   // true  — 반례가 없다\n[].some(x => true)     // false — 예가 없다\n{ ...o, a: 2 } !== o   // 참조가 바뀐다","cap":"빈 입력이 규칙을 드러낸다"},"key":["참조 투명성이 최적화의 근거","시각·난수는 인자로 받는다","빈 입력에서는 항등원이 나온다","펼치기는 참조를 바꾼다"]},"q":[{"t":"input","cat":"internals","k":"인자를 하나씩 받게 바꾸기","q":"여러 인자를 받는 함수를 <b>인자 하나씩 받는 함수들의 사슬</b>로 바꾸는 기법을 무엇이라 부를까요? (영문 한 단어)","a":["currying","curry","커링"],"ex":"<code>f(a, b, c)</code> 를 <code>f(a)(b)(c)</code> 로 바꾸는 것이다. 하스켈처럼 아예 모든 함수가 이 꼴인 언어도 있다.\n개념: '인자 일부만 미리 먹이기'(부분 적용)와는 다르다 — 부분 적용은 <b>몇 개든</b> 한 번에 먹일 수 있다.\n실무: 설정을 미리 먹여 둔 함수를 만들 때 유용하지만, 남용하면 호출부에서 <b>인자 개수를 세기</b> 어려워진다."},{"t":"input","cat":"internals","k":"필요할 때까지 미루기","q":"값이 실제로 쓰일 때까지 계산을 <b>미뤄 두는</b> 평가 방식을 무엇이라 부를까요? (영문 한 단어)","a":["lazy","지연평가","lazyevaluation","지연"],"ex":"무한 수열을 다룰 수 있고, 안 쓰이는 값은 아예 계산하지 않아 낭비가 없다.\n개념: 자바스크립트의 <code>&amp;&amp;</code>·<code>||</code>·삼항 연산자도 오른쪽을 필요할 때만 계산하는 <b>단축 평가</b>다.\n실무: 제너레이터나 이터러블로 파이프라인을 만들면 큰 파일도 <b>한 줄씩</b> 흘려보내며 처리할 수 있다 — 전체를 메모리에 올리지 않는다."},{"t":"input","cat":"internals","k":"조건에 맞는 첫 값","q":"2 보다 큰 <b>첫 원소</b>를 찾으면 무엇이 나올까요? 출력되는 값을 적으세요. (숫자)","code":"console.log([1, 2, 3, 4].find(x => x > 2));","a":["3"],"ex":"<code>find</code> 는 조건에 맞는 <b>첫 값</b>을, <code>findIndex</code> 는 그 자리를 준다. 없으면 각각 <code>undefined</code> 와 <code>-1</code> 이다.\n개념: 찾는 순간 <b>멈추므로</b> <code>filter(...)[0]</code> 보다 낫다 — 뒤쪽은 끝까지 훑는다.\n실무: 값이 <code>undefined</code> 일 수 있는 배열에서는 '못 찾음' 과 '찾았는데 undefined' 가 구별되지 않으므로 <code>findIndex</code> 를 쓰세요."},{"t":"input","cat":"internals","k":"모두 참인가","q":"모든 원소가 양수인지 물으면 무엇이 나올까요? 출력되는 값을 적으세요. (true 또는 false)","code":"console.log([1, 2, 3].every(x => x > 0));","a":["true"],"ex":"셋 다 조건을 만족하므로 참이다. 하나라도 어긋나면 <b>거기서 멈추고</b> 거짓을 낸다.\n개념: <code>every</code> 는 '반례가 없는가', <code>some</code> 은 '예가 있는가' 를 묻는다 — 서로 부정 관계다.\n실무: 검증 함수를 <code>every</code> 로 적으면 첫 실패에서 멈춰 빠르지만, <b>모든 오류를 모아 보여 주려면</b> 일부러 끝까지 훑어야 한다."},{"t":"input","cat":"internals","k":"빈 배열에 모두 물으면","q":"<b>빈 배열</b>에게 '모든 원소가 조건을 만족하는가' 를 물으면 무엇이 나올까요? 조건은 언제나 거짓이다. 출력되는 값을 적으세요. (true 또는 false)","code":"console.log([].every(x => false));","a":["true"],"ex":"반례가 하나도 없으므로 참이다 — 이를 <b>공허한 참</b>(vacuous truth)이라 한다.\n개념: 논리적으로도 자연스럽다. '<b>모든</b>' 은 '반례가 없다' 와 같은 말이고, 원소가 없으면 반례도 없다.\n실무: '모든 항목이 승인됐으면 진행' 같은 코드가 <b>목록이 비었을 때</b> 그대로 통과한다 — 빈 목록을 따로 막을지 먼저 정하세요."},{"t":"input","cat":"internals","k":"빈 배열에 하나라도 물으면","q":"<b>빈 배열</b>에게 '조건을 만족하는 원소가 하나라도 있는가' 를 물으면 무엇이 나올까요? 조건은 언제나 참이다. 출력되는 값을 적으세요. (true 또는 false)","code":"console.log([].some(x => true));","a":["false"],"ex":"원소가 하나도 없으니 '있다' 고 할 수 없다. 앞 문제와 짝을 이루는 결과다.\n개념: 두 값은 각 연산의 <b>항등원</b>이다 — AND 의 항등원은 참, OR 의 항등원은 거짓이라 빈 입력에서 그 값이 나온다.\n실무: <code>reduce</code> 의 초기값을 고를 때도 같은 기준이다 — 덧셈이면 0, 곱셈이면 1, 최댓값이면 <code>-Infinity</code>."},{"t":"input","cat":"internals","k":"펼쳐 만든 객체는 같은 것인가","q":"기존 객체를 펼쳐 새 객체를 만든 뒤 <b>같은 것인지</b> 물으면 무엇이 나올까요? 출력되는 값을 적으세요. (true 또는 false)","code":"const o = { a: 1 };\nconst n = { ...o, a: 2 };\nconsole.log(n === o);","a":["false"],"ex":"펼치기는 <b>새 객체</b>를 만든다. 참조가 다르므로 <code>===</code> 는 거짓이다.\n개념: 이 '참조가 바뀐다' 는 성질이 리액트 같은 화면 라이브러리가 <b>바뀐 것을 알아채는</b> 근거다 — 제자리에서 고치면 알아채지 못한다.\n실무: 다만 한 겹만 새로 만들므로 안쪽 배열·객체는 여전히 공유된다. 바뀌는 경로 위의 층을 모두 새로 만드세요."}]}],"ord":8},{"t":"코드 리뷰 — 결함 찾기","l":[{"t":"순수한 척하는 코드","xp":70,"th":{"sum":"함수형처럼 <b>보이는</b> 코드가 실제로는 바깥을 바꾸는 자리를 찾는다.","body":[{"h":"변환 자리의 부수효과","t":"<code>map</code> 안에서 바깥 변수를 바꾸거나, 파이프라인 한가운데 제자리 <code>sort</code> 를 두면 순서와 실행 횟수에 결과가 달린다. 값을 만드는 단계와 바꾸는 단계를 <b>나누는 것</b>이 규칙이다."},{"h":"복사의 깊이","t":"전개는 한 겹만 복사하므로 중첩된 객체는 공유된 채로 남는다. 참조 동일성으로 변경을 감지하는 도구에서는 <b>값은 바뀌었는데 화면은 그대로</b>인 증상이 되고, 원본까지 함께 바뀌어 되돌리기와 비교가 어긋난다."}],"code":{"c":"const [labels, total] = rows.reduce(…)   // 함께 접기\nrows.slice().sort(cmp)                    // 복사본\n{ ...s, a: { ...s.a, xs: [...s.a.xs, x] } }","cap":"만드는 단계와 바꾸는 단계를 나눈다"},"key":["map 은 변환만 한다","제자리 정렬은 입력을 바꾼다","전개는 얕다","참조가 같으면 안 바뀐 것으로 본다"]},"q":[{"t":"review","k":"map 안에서 바깥을 바꾼다","cat":"review","d":2,"q":"이 코드의 결함을 모두 고르세요","code":"let total = 0;\n\nconst labels = items.map((it) => {\n  total += it.price;\n  return it.name + \" (\" + it.price + \")\";\n});","items":[{"txt":"<code>map</code> 은 값을 변환해 새 배열을 만드는 자리인데 바깥 변수를 함께 바꾸고 있다. 이런 코드는 <b>순서와 실행 횟수에 의존</b>하게 되어, 나중에 결과만 재사용하거나 게으르게 평가하는 순간 합계가 어긋난다.","bad":true},{"txt":"<code>map</code> 의 콜백에서 문자열을 이어 붙이는 대신 템플릿 리터럴을 쓰면 읽기 쉬워진다 — 취향의 문제이고 동작에는 아무 차이가 없으므로 리뷰에서 굳이 막을 이유는 없다.","bad":false},{"txt":"합계와 라벨을 한 번에 만들려면 <code>reduce</code> 로 <b>두 값을 함께 접거나</b> 순회를 두 번 도는 편이 낫다. 배열이 아주 크지 않다면 두 번 도는 쪽이 읽기 쉽고, 각 단계가 무엇을 만드는지 이름으로 드러난다.","bad":true},{"txt":"<code>let total</code> 을 모듈 최상위에 두었다면 이 코드를 두 번 실행할 때 앞의 합계 위에 계속 더해져 값이 부풀지만, 주어진 조각만으로는 함수 안인지 모듈 밖인지 알 수 없으므로 결함이라고 단정할 수 없다.","bad":false},{"txt":"<code>items</code> 가 비어 있으면 <code>map</code> 이 <code>undefined</code> 를 돌려주므로 <code>labels</code> 를 쓰기 전에 존재 여부를 검사해야 한다.","bad":false}],"ex":"결함 2가지. (1) <b>변환 자리에서 부수효과</b>를 낸다 — <code>map</code> 은 '각 원소를 무엇으로 바꿀 것인가' 만 말해야 하고, 바깥을 바꾸면 그 약속이 깨진다. (2) 두 가지 결과를 한 순회에 섞어 <b>의도가 흐려진다</b> — <code>reduce</code> 로 명시적으로 접거나 순회를 나누면 각 단계가 무엇을 만드는지 드러난다.\n디스트랙터: 템플릿 리터럴은 취향이다. 최상위 <code>let</code> 은 걱정할 만하지만 이 조각만으로는 알 수 없다. 빈 배열에서 <code>map</code> 은 빈 배열을 돌려주지 <code>undefined</code> 가 아니다."},{"t":"review","k":"누산기를 그 자리에서 바꾼다","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"const byUser = orders.reduce((acc, o) => {\n  acc[o.userId] = acc[o.userId] || [];\n  acc[o.userId].push(o);\n  return acc;\n}, {});","items":[{"txt":"누산기를 제자리에서 바꾸는 것은 <code>reduce</code> 의 흔한 관용구이고, 초기값을 <b>이 호출에서 새로 만들었으므로</b> 밖으로 새지 않는다 — 성능 면에서도 매번 객체를 복사하는 것보다 낫다.","bad":false},{"txt":"<code>o.userId</code> 가 <code>undefined</code> 면 <code>\"undefined\"</code> 라는 키에 모두 모인다. 키가 없을 수 있는 데이터라면 <b>그 자리에서 걸러 내거나</b> 별도 버킷으로 옮겨, 잘못된 묶음이 조용히 만들어지지 않게 해야 한다.","bad":true},{"txt":"<code>Object.groupBy</code> 나 <code>Map</code> 을 쓰면 무엇을 묶는지가 이름으로 드러나고, 특히 <code>Map</code> 은 키 타입을 그대로 보존하며 프로토타입 오염 걱정도 없다 — 다만 지금 코드가 틀린 것은 아니므로 결함이라기보다 리팩터링 제안에 가깝다.","bad":false},{"txt":"빈 객체를 초기값으로 쓰면 <code>__proto__</code> 같은 키가 들어올 때 프로토타입을 건드릴 수 있으므로, 사용자 입력에서 온 키를 그대로 쓴다면 <code>Object.create(null)</code> 로 시작해야 한다.","bad":true},{"txt":"<code>reduce</code> 는 배열이 비어 있고 초기값이 없으면 예외를 던지므로, 초기값 <code>{}</code> 를 준 이 코드는 그 위험을 이미 피했다.","bad":false}],"ex":"결함 2가지. (1) <b>키가 없는 경우</b>를 다루지 않아 <code>\"undefined\"</code> 버킷이 조용히 생긴다 — 집계에서 가장 흔한 오염이다. (2) 사용자 입력에서 온 키를 평범한 객체에 넣으면 <code>__proto__</code> 같은 특수 키가 <b>프로토타입을 건드린다</b> — <code>Object.create(null)</code> 이나 <code>Map</code> 이 안전하다.\n디스트랙터: 이 호출에서 만든 초기값을 제자리에서 바꾸는 것은 밖으로 새지 않으므로 순수성을 해치지 않는다. <code>groupBy</code> 제안은 좋은 리팩터링이지 결함이 아니고, 초기값을 준 <code>reduce</code> 는 빈 배열에서도 안전하다."},{"t":"review","k":"얕게 복사하고 안심한다","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"function withTag(state, tag) {\n  const next = { ...state };\n  next.filters.tags.push(tag);\n  return next;\n}","items":[{"txt":"<code>structuredClone</code> 으로 통째로 깊은 복사를 하면 코드가 간단해지지만, 상태가 크면 매번 전부 복사하는 비용이 들고 함수·심볼처럼 복사되지 않는 값도 있다 — 바뀌는 경로만 새로 만드는 편이 보통 낫다.","bad":false},{"txt":"함수 이름이 <code>withTag</code> 라 새 상태를 돌려준다는 의도는 잘 드러난다 — 이름이 계약을 설명하는 좋은 예이고, 이름 자체를 바꿀 이유는 없다.","bad":false},{"txt":"전개는 <b>한 겹만</b> 복사한다. <code>next.filters</code> 는 여전히 원본과 같은 객체이므로 <code>tags</code> 에 밀어 넣는 순간 <b>원래 상태도 함께 바뀐다</b> — 새 객체를 돌려주니 안전해 보이는 것이 이 버그를 오래 살려 둔다.","bad":true},{"txt":"<code>tag</code> 가 이미 목록에 있는지 검사하지 않아 같은 태그가 여러 번 들어갈 수 있다 — 중복 허용 여부는 이 함수가 아니라 태그 모델의 규칙에서 정할 일이다.","bad":false},{"txt":"리액트 같은 곳에서는 참조가 같으면 다시 그리지 않는데, <code>filters</code> 참조가 그대로라 <b>화면이 갱신되지 않을 수도</b> 있다. 값은 바뀌었는데 화면은 그대로인, 가장 찾기 어려운 종류의 증상이 된다.","bad":true}],"ex":"결함 2가지. (1) <b>얕은 복사</b>라 중첩된 객체는 공유된다 — 겉으로는 불변처럼 보이는데 원본이 바뀌므로, 되돌리기·비교·캐시가 전부 어긋난다. (2) 참조 동일성으로 변경을 감지하는 도구에서는 <b>바뀐 것을 눈치채지 못한다</b>. 바뀌는 경로만 새로 만들어 <code>{ ...state, filters: { ...state.filters, tags: [...tags, tag] } }</code> 처럼 써야 한다.\n디스트랙터: 통째 깊은 복사는 대안 중 하나일 뿐 비용과 한계가 있다. 이름은 오히려 좋은 편이고, 중복 허용 여부는 모델의 규칙이다."},{"t":"review","k":"순수한 척하는 파이프라인","cat":"review","d":2,"q":"이 코드의 결함을 모두 고르세요","code":"const top3 = (rows) =>\n  rows\n    .sort((a, b) => b.score - a.score)\n    .slice(0, 3)\n    .map((r) => r.name);","items":[{"txt":"<code>sort</code> 는 <b>원본 배열을 제자리에서</b> 정렬한다. 화살표 하나로 이어진 순수해 보이는 파이프라인이지만 호출자의 배열 순서를 바꿔 놓으므로, <code>rows.slice().sort(...)</code> 나 <code>toSorted</code> 로 복사본을 정렬해야 한다.","bad":true},{"txt":"<code>slice(0, 3)</code> 은 <code>rows</code> 가 3개 미만이면 예외를 던지므로, 길이를 먼저 검사하고 부족하면 있는 만큼만 돌려주도록 감싸는 편이 안전하다.","bad":false},{"txt":"전체를 정렬한 뒤 앞의 셋만 쓰므로 <code>O(n log n)</code> 이 든다 — 크기 3 의 최소 힙이나 한 번의 순회로 <code>O(n)</code> 에 끝낼 수 있지만, 이것은 정확성 문제가 아니고 목록이 작으면 차이를 느낄 수도 없다.","bad":false},{"txt":"점수가 같을 때의 순서가 정해지지 않아 상위 3명이 실행마다 달라질 수 있다 — 동점 처리 규칙이 필요하다면 <code>id</code> 처럼 유일한 값을 두 번째 기준으로 넣어 <b>결과를 결정적으로</b> 만들어야 한다.","bad":true},{"txt":"화살표 함수 본문을 여러 줄에 걸쳐 메서드 체인으로 쓰면 중간값에 이름이 없어 디버깅이 어렵다 — 읽기 취향의 문제이며, 단계마다 이름을 붙이는 스타일도 똑같이 정당하다.","bad":false}],"ex":"결함 2가지. (1) <b>제자리 정렬</b>이 파이프라인 한가운데 있다 — 함수형 스타일로 보이지만 입력을 바꾸므로, 같은 배열을 쓰는 다른 코드가 영향을 받는다. (2) <b>동점 순서가 결정적이지 않다</b> — 상위 k 를 뽑는 함수는 같은 입력에 같은 답을 줘야 신뢰할 수 있다.\n디스트랙터: <code>slice</code> 는 범위를 넘겨도 예외 없이 있는 만큼만 돌려준다. 정렬 비용과 체인 스타일은 결함이 아니다."}]},{"t":"합성이 무너지는 자리","xp":70,"th":{"sum":"합성하려면 조각이 **예측 가능**해야 한다 — 상태·예외·게으름이 그 성질을 깬다.","body":[{"h":"기억하는 함수","t":"클로저에 상태를 쌓으면 같은 입력에 다른 출력이 나오고, 메모이제이션은 순수하지 않은 함수를 감싸는 순간 첫 결과를 영원히 굳힌다. 캐시를 모듈에 하나만 두면 서로 다른 함수의 결과가 섞이기도 한다."},{"h":"예외와 순회 비용","t":"실패를 던지고 곧바로 잡아 값으로 바꿀 것이라면 처음부터 <b>값으로 돌려주는</b> 편이 합성하기 쉽다. 그리고 배열 메서드는 게으르지 않으므로, 첫 하나만 필요한데 <code>map</code> 을 먼저 돌리면 전부 계산한다."}],"code":{"c":"const memo = (fn) => { const c = new Map(); return (x) => … };\nfor (const r of rows) { const v = f(r); if (ok(v)) return v; }","cap":"캐시는 감싼 함수마다 하나씩"},"key":["클로저에 변하는 상태를 두지 않는다","메모이제이션은 순수함에 기댄다","실패는 값으로 돌려준다","배열 메서드는 게으르지 않다"]},"q":[{"t":"review","k":"부수효과를 기억하는 메모이제이션","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"const cache = new Map();\n\nfunction memo(fn) {\n  return (arg) => {\n    if (cache.has(arg)) return cache.get(arg);\n    const v = fn(arg);\n    cache.set(arg, v);\n    return v;\n  };\n}","items":[{"txt":"인자가 객체면 참조로 키가 잡혀 내용이 같아도 캐시에 걸리지 않는다 — 값 기준으로 캐시하려면 키를 만들어야 하지만, 그것은 이 구현이 약속한 범위 밖의 이야기다.","bad":false},{"txt":"캐시가 <b>모듈에 하나뿐</b>이라 <code>memo</code> 로 감싼 서로 다른 함수들이 같은 저장소를 나눠 쓴다. 인자가 같으면 다른 함수의 결과가 돌아오므로, 캐시는 <code>memo</code> 호출마다 새로 만들어야 한다.","bad":true},{"txt":"<code>Map</code> 은 넣은 항목을 계속 붙잡으므로 인자의 종류가 많으면 메모리가 한없이 자란다 — 상한이나 만료가 필요하다는 지적은 옳지만, 값의 가짓수가 애초에 적은 캐시라면 필요 없을 수도 있다.","bad":false},{"txt":"인자가 하나뿐인 함수만 감쌀 수 있으므로 <code>(...args)</code> 로 받아 <code>JSON.stringify</code> 를 키로 써야 하며, 그렇게 바꾸지 않으면 대부분의 함수에 쓸 수 없다.","bad":false},{"txt":"메모이제이션은 <b>같은 입력에 같은 출력</b>이라는 성질에 기대는 최적화다. 시간·난수·입출력에 의존하는 함수를 감싸면 처음 한 번의 결과가 영원히 굳어 버리고, 그 뒤로는 무엇을 고쳐도 옛 값이 돌아오므로 감쌀 수 있는 함수인지 먼저 따져야 한다.","bad":true}],"ex":"결함 2가지. (1) <b>캐시를 공유한다</b> — <code>memo(f)</code> 와 <code>memo(g)</code> 가 같은 저장소를 쓰므로 결과가 뒤섞인다. 캐시는 반환하는 함수마다 새로 만들어야 한다. (2) <b>순수하지 않은 함수를 감싸면</b> 첫 결과가 영원히 굳는다 — 메모이제이션은 함수의 성질에 기대는 최적화다.\n디스트랙터: 객체 인자와 메모리 상한은 캐시 설계의 선택지이고, 인자 하나만 받는 것은 이 구현이 정한 계약이지 결함이 아니다."},{"t":"review","k":"예외로 흐름을 만든다","cat":"review","d":2,"q":"이 코드의 결함을 모두 고르세요","code":"function parseAge(s) {\n  const n = Number(s);\n  if (Number.isNaN(n)) throw new Error(\"bad\");\n  return n;\n}\n\nconst ages = inputs.map((s) => {\n  try { return parseAge(s); } catch { return null; }\n});","items":[{"txt":"실패를 예외로 던지고 곧바로 잡아 <code>null</code> 로 바꾸는 것은 <b>제어 흐름으로 예외를 쓰는</b> 형태다. 실패가 값의 일부라면 <code>null</code> 이나 결과 타입을 <b>돌려주는</b> 편이 합성하기 쉽고 비용도 낮다.","bad":true},{"txt":"<code>Number(\"\")</code> 는 <code>0</code> 이므로 빈 문자열이 나이 0 으로 통과한다 — 입력 검증에서 자주 놓치는 자리지만, 이 리뷰의 초점인 흐름 설계와는 다른 층위의 지적이다.","bad":false},{"txt":"<code>Error(\"bad\")</code> 는 무엇이 왜 잘못됐는지 알려 주지 않는다. 잡는 쪽에서 구분할 수 없고 로그에도 남기지 않으므로, 최소한 어떤 입력이 실패했는지 메시지에 담아야 원인을 추적할 수 있다.","bad":true},{"txt":"<code>catch</code> 에서 바인딩을 생략한 문법은 비교적 최신이라 오래된 실행 환경에서 문법 오류가 나므로, 반드시 <code>catch (e)</code> 로 되돌려야 한다.","bad":false},{"txt":"결과 배열에 <code>null</code> 이 섞이므로 뒤에서 다시 걸러야 하는데, 그 시점에는 어떤 입력이 실패했는지가 이미 사라져 원인을 알려 줄 수 없다 — 입력과 짝을 이루어 돌려주면 낫지만 계약에 따라 다르다.","bad":false}],"ex":"결함 2가지. (1) <b>예외를 곧바로 잡아 값으로 바꾼다</b> — 그럴 것이라면 처음부터 값으로 돌려주는 편이 낫다. 예외는 '여기서는 다룰 수 없다' 는 신호일 때 쓰는 도구다. (2) <b>오류가 정보를 담지 않는다</b> — 잡는 쪽도 로그도 무엇이 실패했는지 알 수 없다.\n디스트랙터: <code>Number(\"\")</code> 문제는 별개의 검증 주제다. <code>catch</code> 바인딩 생략은 현대 환경에서 널리 지원된다. <code>null</code> 이 섞이는 것은 계약의 선택이다."},{"t":"review","k":"커링한 함수가 상태를 안고 있다","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"const makeFormatter = (opts) => {\n  const parts = [];\n  return (row) => {\n    parts.push(row.id);\n    return opts.prefix + row.id + \" (\" + parts.length + \")\";\n  };\n};","items":[{"txt":"<code>opts.prefix</code> 가 없으면 <code>\"undefined\"</code> 가 앞에 붙는다 — 기본값을 두거나 생성 시점에 검증하면 좋지만, 옵션 검증은 이 함수의 계약에 명시돼 있지 않다.","bad":false},{"txt":"돌려주는 함수가 <b>클로저에 상태를 쌓는다</b>. 같은 입력에 다른 출력이 나오므로 <code>map</code> 같은 곳에 넘기면 순서에 따라 결과가 달라지고, 재시도나 병렬 처리에서 값이 어긋난다.","bad":true},{"txt":"화살표 함수를 이중으로 쓰면 이름이 없어 스택 추적이 읽기 어렵다 — 이름 있는 함수 선언으로 바꾸면 디버깅이 편해지지만 동작은 같으므로 취향의 영역이다.","bad":false},{"txt":"<code>parts</code> 는 커진 채로 계속 남는다 — 포매터를 오래 들고 있으면 처리한 행 수만큼 배열이 자라 메모리가 새고, 그 값이 실제로 쓰이는 곳은 길이뿐이라 더욱 아깝다.","bad":true},{"txt":"클로저로 옵션을 붙잡는 것 자체는 부분 적용의 정석이다 — 문제는 옵션이 아니라 <b>호출마다 변하는 상태</b>를 함께 붙잡은 데 있다.","bad":false}],"ex":"결함 2가지. (1) <b>호출마다 결과가 달라진다</b> — 순번을 매기려는 의도라면 그것을 인자로 받거나 <code>map</code> 의 인덱스를 쓰는 편이 정직하다. (2) <b>쌓기만 하고 비우지 않는</b> 배열이 메모리에 남는다. 길이만 필요하다면 숫자 하나로 충분하고, 그마저도 바깥에서 세는 편이 낫다.\n디스트랙터: 옵션 기본값과 이름 있는 함수는 개선 제안이다. 클로저로 옵션을 붙잡는 것은 부분 적용의 정석이며, 문제는 변하는 상태를 함께 붙잡은 데 있다."},{"t":"review","k":"게으른 척하는 파이프라인","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"const first = rows\n  .map((r) => expensive(r))\n  .filter((r) => r.ok)\n  .find((r) => r.score > 90);","items":[{"txt":"<code>find</code> 는 조건을 만족하는 값이 없으면 <code>undefined</code> 를 돌려주므로 뒤에서 옵셔널 체이닝이나 기본값이 필요하다 — 이 코드 자체의 결함이 아니라 사용하는 쪽의 계약이다.","bad":false},{"txt":"<code>expensive</code> 가 저장이나 전송 같은 부수효과를 낸다면 필요 없는 행에까지 그것이 실행되어 훨씬 큰 문제가 되지만, 이름만으로는 순수한 계산인지 알 수 없으므로 결함이라고 단정할 수 없다.","bad":false},{"txt":"<code>map</code> 이 <b>모든 행에 대해 먼저 다 돈다</b>. 찾는 값이 앞쪽에 있어도 뒤쪽까지 비싼 계산을 전부 수행하므로, 조건을 만족하는 첫 값만 필요하다면 한 번의 순회에서 변환하고 판정하고 찾는 즉시 멈추는 형태로 바꿔야 한다.","bad":true},{"txt":"메서드 체인 대신 <code>for</code> 문으로 쓰면 항상 더 빠르므로, 성능이 중요한 경로에서는 체인을 쓰지 않도록 규칙으로 금지해야 한다.","bad":false},{"txt":"중간 배열이 두 개 만들어져 입력이 클수록 메모리를 크게 쓴다 — 자바스크립트의 배열 메서드는 게으르지 않으므로, 큰 데이터에서는 제너레이터나 순회 한 번으로 합치는 편이 낫다.","bad":true}],"ex":"결함 2가지. (1) <b>필요 없는 계산을 전부 한다</b> — 앞의 한 건만 필요한데 모든 행을 변환하므로, 데이터가 커질수록 낭비가 그대로 늘어난다. (2) <b>중간 배열</b>이 두 벌 생긴다. 둘 다 '한 번 돌면서 판정하고 찾으면 멈춘다' 로 바꾸면 함께 사라진다.\n디스트랙터: <code>find</code> 의 <code>undefined</code> 반환은 정상 계약이다. <code>expensive</code> 의 순수성은 이 조각만으로 알 수 없고, 체인을 <b>항상</b> 금지하는 규칙은 지나치다 — 대부분의 코드에서 읽기 쉬움이 더 값지다."}]}],"ord":9},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"메모리 시각화","lv":2,"q":"불변 갱신을 만드세요. 원본을 건드리지 않고 <b>새 객체를 만들어</b> 값을 바꾼다. <b>단계마다</b> <code>snap(라벨, {원본:base, 결과:cur, 같은객체:base===cur})</code> 를 부르세요. 반환값은 <code>{원본유지, 결과}</code> 다.","src":"const base = { name: '가', tags: ['a'] };\n\nfunction update(obj, key, value) {\n  // 여기에 구현하세요 — 원본을 바꾸지 않고 새 객체를 돌려줍니다\n  return obj;\n}\n\nconst next = update(base, 'name', '나');\nRESULT = { 원본유지: base.name === '가', 결과: next.name };","tests":[{"d":"원본이 그대로다","js":"RESULT.원본유지===true"},{"d":"새 값이 반영된다","js":"RESULT.결과==='나'"},{"d":"장면이 남았다","js":"FRAMES.length>=1"},{"d":"결과는 원본과 다른 객체다","js":"FRAMES[0].value['같은객체']===false"},{"d":"장면 속 원본의 이름이 바뀌지 않았다","js":"FRAMES[0].value['원본'].name==='가'"}],"ex":"불변 갱신의 값어치는 '<b>바뀌었는지 참조 비교 하나로 안다</b>' 는 데 있다. 원본을 제자리에서 고치면 이전 값이 사라져 무엇이 달라졌는지 알 수 없지만, 새 객체를 만들면 <code>prev !== next</code> 하나로 판단할 수 있다. React 의 리렌더 판단, 되돌리기 기능, 시간 여행 디버깅이 전부 이 성질 위에 서 있다. 대신 전개 연산자는 <b>얕은</b> 복사라 중첩 객체는 그 층까지 새로 만들어야 한다."},{"t":"sim","k":"실행 순서 시각화","lv":2,"q":"함수 합성 <code>compose(f, g)(x) = f(g(x))</code> 를 만드세요. <b>각 함수가 실행될 때마다</b> <code>snap(\"적용 \"+이름, {값:v})</code> 를 부르세요. 반환값은 최종 결과다.","src":"function compose(...fns) {\n  // 여기에 구현하세요 — 오른쪽부터 적용합니다\n}\n\nconst inc = x => { snap('적용 inc', { 값: x + 1 }); return x + 1; };\nconst dbl = x => { snap('적용 dbl', { 값: x * 2 }); return x * 2; };\nRESULT = compose(inc, dbl)(5);","tests":[{"d":"결과가 11 이다 (5×2 그다음 +1)","js":"RESULT===11"},{"d":"두 함수가 모두 실행됐다","js":"FRAMES.length===2"},{"d":"오른쪽 함수가 먼저 적용된다","js":"FRAMES[0].label==='적용 dbl'"},{"d":"중간 값이 10 이다","js":"FRAMES[0].value['값']===10"},{"d":"마지막 값이 결과와 같다","js":"FRAMES[1].value['값']===RESULT"}],"ex":"<code>compose(f, g)</code> 는 수학의 <code>f∘g</code> 와 같아 <b>오른쪽부터</b> 적용한다. 왼쪽부터 읽고 싶으면 <code>pipe</code> 를 쓰는데, 둘을 헷갈려 순서가 뒤집히는 것이 합성에서 가장 흔한 실수다. <code>reduceRight</code> 한 줄로 구현되는 데서 보이듯, 합성은 특별한 기능이 아니라 <b>함수를 값처럼 다루면 자연히 따라오는</b> 것이다."},{"t":"sim","k":"실행 순서 시각화","lv":3,"q":"커링을 만드세요. <code>curry(f)</code> 는 인자가 다 모일 때까지 <b>함수를 돌려주고</b>, 다 모이면 실행한다. <b>인자를 받을 때마다</b> <code>snap(\"인자 \"+n, {모인인자:[...args]})</code> 를 부르세요. 반환값은 최종 계산 결과다.","src":"function curry(fn) {\n  // 여기에 구현하세요 — fn.length 만큼 모이면 실행합니다\n}\n\nconst add3 = (a, b, c) => a + b + c;\nconst c = curry(add3);\nRESULT = c(1)(2)(3);","tests":[{"d":"결과가 6 이다","js":"RESULT===6"},{"d":"세 번에 걸쳐 인자를 받는다","js":"FRAMES.length===3"},{"d":"인자가 하나씩 쌓인다","js":"JSON.stringify(FRAMES.map(f=>f.value['모인인자'].length))==='[1,2,3]'"},{"d":"마지막에 인자가 셋이다","js":"JSON.stringify(FRAMES[2].value['모인인자'])==='[1,2,3]'"},{"d":"앞 단계는 아직 계산하지 않는다","js":"FRAMES[0].value['모인인자'].length===1"}],"ex":"커링은 '<b>인자를 나눠 받는 것</b>' 이고, 그 값어치는 <b>부분 적용</b>에 있다. <code>add(1)</code> 을 변수에 담아 두면 '1을 더하는 함수' 가 되어 재사용된다. 구현의 핵심은 <code>fn.length</code> — 자바스크립트 함수는 자기가 몇 개를 받는지 알고 있다. 다만 기본값이나 나머지 매개변수가 있으면 <code>length</code> 가 줄어들어 커링이 일찍 실행되므로, 라이브러리들은 개수를 직접 받는 형태도 함께 제공한다."},{"t":"sim","k":"상태 시각화","lv":3,"q":"게으른 평가를 만드세요. <code>lazy(fn)</code> 은 <b>처음 값을 요구할 때만</b> 계산하고 그 뒤로는 기억해 둔 값을 돌려준다. <b>계산·재사용마다</b> <code>snap(라벨, {계산횟수:n})</code> 을 부르세요. 반환값은 실제 계산 횟수다.","src":"function lazy(fn) {\n  // 여기에 구현하세요 — 처음 한 번만 계산하고 기억합니다\n}\n\nlet calls = 0;\nconst v = lazy(() => { calls++; snap('계산', { 계산횟수: calls }); return 42; });\nv(); v(); v();\nRESULT = calls;","tests":[{"d":"세 번 불러도 한 번만 계산한다","js":"RESULT===1"},{"d":"계산 장면이 한 번뿐이다","js":"FRAMES.filter(f=>f.label==='계산').length===1"},{"d":"재사용 장면이 두 번이다","js":"FRAMES.filter(f=>f.label==='재사용').length===2"},{"d":"계산이 재사용보다 먼저다","js":"FRAMES[0].label==='계산'"},{"d":"장면이 3개다","js":"FRAMES.length===3"}],"ex":"게으른 평가는 <b>필요하기 전에는 계산하지 않는다</b>는 원칙이다. 비싼 설정값·큰 파일·네트워크 호출을 미리 하지 않으므로 시작이 빨라지고, 끝내 안 쓰이면 아예 계산되지 않는다. 여기에 <b>메모이제이션</b>이 붙어 두 번째부터는 공짜인다. 주의할 것은 <code>fn</code> 이 부수효과를 가지면 '언제 실행되는지' 가 예측하기 어려워진다는 점이다 — 그래서 게으름과 순수 함수는 짝으로 다닌다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련이다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠르다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둔다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않는다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려진다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러난다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 본다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈린다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"알고리즘 시각화","lv":2,"q":"<code>reduce</code> 로 <code>map</code> 과 <code>filter</code> 를 만드세요. <b>누적값이 자랄 때마다</b> <code>snap(라벨, [...acc])</code> 를 부르세요. 반환값은 <code>{mapped, filtered}</code> 다.","src":"function myMap(arr, f) {\n  // reduce 로 구현하세요\n  return [];\n}\nfunction myFilter(arr, p) {\n  // reduce 로 구현하세요\n  return [];\n}\n\nRESULT = { mapped: myMap([1,2,3], x => x * 2), filtered: myFilter([1,2,3,4], x => x % 2 === 0) };","tests":[{"d":"map 결과가 맞다","js":"JSON.stringify(RESULT.mapped)==='[2,4,6]'"},{"d":"filter 결과가 맞다","js":"JSON.stringify(RESULT.filtered)==='[2,4]'"},{"d":"map 장면이 3개다","js":"FRAMES.filter(f=>f.label==='map').length===3"},{"d":"filter 는 4번 돌지만 결과는 2개만 자란다","js":"(function(){var f=FRAMES.filter(x=>x.label==='filter');return f.length===4&&f[3].value.length===2;})()"},{"d":"누적값은 줄어들지 않는다","js":"(function(){var f=FRAMES.filter(x=>x.label==='filter');for(var i=1;i<f.length;i++) if(f[i].value.length<f[i-1].value.length) return false; return true;})()"}],"ex":"<code>reduce</code> 는 '<b>접기</b>' 이고, map·filter 는 그 특수한 경우다. map 은 매번 하나를 넣는 접기, filter 는 조건에 맞을 때만 넣는 접기다. 이걸 알면 두 번 훑던 <code>arr.map(f).filter(p)</code> 를 한 번의 reduce 로 합칠 수 있다. 장면에서 filter 가 4번 돌지만 누적값은 2번만 자라는 것이 '<b>순회 횟수와 결과 크기는 다르다</b>' 를 보여 준다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련이다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠르다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둔다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않는다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려진다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러난다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 본다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈린다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 III","q":[{"t":"sim","k":"함수형 시뮬레이션","lv":2,"cat":"internals","q":"함수가 <b>순수한지</b> 판정하세요. 순수하려면 <b>(1) 같은 입력에 같은 출력</b>이고 <b>(2) 바깥 상태를 건드리지 않아야</b> 한다. 함수마다 <code>snap(이름, {sameOutput, noEffect, pure}, {name})</code> 을 남기고 <b>[순수한 함수 수, 같은 입력에 다른 출력을 내는 함수 수, 부수 효과가 있는 함수 수, 캐시(메모이제이션)를 안전하게 붙일 수 있는 함수 수]</b> 를 돌려주세요.","src":"// sameOutput: 같은 입력에 늘 같은 값인가 · noEffect: 바깥을 안 건드리는가\nconst FUNCS = [\n  { name: 'add(a,b)',        sameOutput: true,  noEffect: true },\n  { name: 'now()',           sameOutput: false, noEffect: true },\n  { name: 'push(arr, x)',    sameOutput: true,  noEffect: false },\n  { name: 'log(msg)',        sameOutput: true,  noEffect: false },\n  { name: 'slugify(text)',   sameOutput: true,  noEffect: true }\n];\n\nfunction purity() {\n  return [0, 0, 0, 0];\n}\n\nRESULT = purity();","tests":[{"d":"순수한 함수는 2개","js":"RESULT[0]===2"},{"d":"같은 입력에 다른 출력을 내는 것은 1개","js":"RESULT[1]===1"},{"d":"부수 효과가 있는 것은 2개","js":"RESULT[2]===2"},{"d":"메모이제이션이 안전한 것은 순수한 2개뿐","js":"RESULT[3]===2"},{"d":"함수마다 장면이 남는다","js":"FRAMES.length===5"},{"d":"now() 는 부수 효과는 없지만 순수하지 않다","js":"FRAMES[1].value.noEffect===true&&FRAMES[1].value.pure===false"}],"ex":"순수성은 <b>도덕이 아니라 도구</b>다 — 순수한 함수만 <b>캐시하고, 순서를 바꾸고, 병렬로 돌리고, 테스트를 쉽게</b> 만들 수 있다. 여기서 <code>now()</code> 가 좋은 예다: 아무것도 망가뜨리지 않지만 <b>같은 입력에 다른 답</b>을 주므로 메모이제이션을 붙이면 시간이 얼어붙는다. 실무에서 목표는 '모든 함수를 순수하게' 가 아니라 <b>부수 효과를 가장자리로 몰아내는 것</b>이다 — 시간·난수·IO·DB 는 바깥에서 받아 <b>인자로 넘기고</b>(의존성 주입), 계산은 순수하게 유지하면 그 부분만 골라 테스트할 수 있다."},{"t":"sim","k":"함수형 시뮬레이션","lv":3,"cat":"internals","q":"<b>불변 갱신이 왜 느리지 않은지</b> 보이세요. 깊은 트리에서 잎 하나를 바꿀 때 <b>경로에 있는 노드만 새로 만들고</b> 나머지는 <b>그대로 공유</b>한다. 깊이마다 <code>snap('깊이 '+d, {newNodes, shared}, {depth})</code> 를 남기고 <b>[새로 만든 노드 수, 공유한 노드 수, 전체 복사였다면 만들었을 노드 수, 몇 분의 일인지(반올림)]</b> 를 돌려주세요. 트리는 <b>이진 트리 깊이 10</b>(노드 1,023개)이고 잎 하나를 바꾼다.","src":"const DEPTH = 10;\nconst TOTAL = Math.pow(2, DEPTH) - 1;   // 1023\n\nfunction structuralSharing() {\n  return [0, 0, 0, 0];\n}\n\nRESULT = structuralSharing();","tests":[{"d":"새로 만드는 노드는 10개","js":"RESULT[0]===10"},{"d":"1,013개를 그대로 공유한다","js":"RESULT[1]===1013"},{"d":"전체 복사였다면 1,023개","js":"RESULT[2]===1023"},{"d":"약 102분의 1","js":"RESULT[3]===102"},{"d":"깊이마다 장면이 남는다","js":"FRAMES.length===10"},{"d":"깊이가 깊어질수록 새 노드가 하나씩 는다","js":"FRAMES[9].value.newNodes===10&&FRAMES[0].value.newNodes===1"}],"ex":"'불변이면 매번 통째로 복사하니 느리다' 는 오해다 — <b>바뀐 경로만</b> 새로 만들고 나머지 가지는 <b>이전 버전과 같은 객체를 가리키면</b> 되기 때문이다(구조 공유). 깊이 10 짜리 트리에서 잎 하나를 바꾸는 데 새 노드는 <b>10개</b>뿐이고, 나머지 1,013개는 그대로다. 이 성질 덕분에 <b>이전 버전이 그대로 살아 있어</b> 실행 취소·타임 트래블 디버깅·React 의 <code>prevProps</code> 비교가 공짜로 된다. Immutable.js·Immer 같은 라이브러리가 하는 일이 정확히 이것이고, 얕은 비교(<code>===</code>)로 변경을 감지할 수 있는 것도 <b>안 바뀐 가지는 같은 참조</b>이기 때문이다."},{"t":"sim","k":"함수형 시뮬레이션","lv":3,"cat":"internals","q":"<b>Maybe 체인</b>을 만드세요. 값이 있으면 다음 함수를 적용하고, <b>한 번 없음(None)이 되면 나머지는 건너뛴다</b>. 단계마다 <code>snap(단계, {value, state}, {step, skipped})</code> 를 남기고 <b>[최종 값, 실제로 실행된 단계 수, 건너뛴 단계 수, 같은 로직을 if 로 쓰면 필요한 null 검사 수]</b> 를 돌려주세요.","src":"// user → address → city → 대문자\nconst USER = { name: 'kim', address: { zip: '12345' } };   // city 가 없다\nconst STEPS = ['address', 'city', 'toUpper'];\n\nfunction maybe() {\n  return [null, 0, 0, 0];\n}\n\nRESULT = maybe();","tests":[{"d":"최종 값은 없음(null)","js":"RESULT[0]===null"},{"d":"두 단계까지만 실행된다","js":"RESULT[1]===2"},{"d":"한 단계를 건너뛴다","js":"RESULT[2]===1"},{"d":"if 로 쓰면 검사 3번이 필요하다","js":"RESULT[3]===3"},{"d":"단계마다 장면이 남는다","js":"FRAMES.length===3"},{"d":"None 이 된 뒤의 단계는 건너뛴 것으로 표시된다","js":"FRAMES[2].opt.skipped===true&&FRAMES[0].opt.skipped===false"}],"ex":"<b>None 이 되면 나머지를 건너뛴다</b>는 규칙 하나가 중첩된 null 검사를 없앤다 — <code>if (user && user.address && user.address.city)</code> 가 <code>Maybe(user).map(a).map(b).map(c)</code> 한 줄이 된다. 자바스크립트의 <b>옵셔널 체이닝</b>(<code>user?.address?.city</code>)이 바로 이 패턴을 문법으로 흡수한 것이고, 러스트의 <code>?</code>·자바의 <code>Optional</code> 도 같은 뿌리다. 다만 조심할 점이 있다 — Maybe 는 <b>왜 없는지 알려 주지 않는다</b>. 실패 이유가 중요하면 <code>Either</code>·<code>Result</code> 처럼 <b>에러를 실어 나르는</b> 타입을 써야 하고, 그래서 API 경계에서는 Maybe 보다 Result 가 더 유용하다."},{"t":"sim","k":"함수형 시뮬레이션","lv":3,"cat":"internals","q":"<b>순수한 재귀에 메모를 붙이면</b> 호출 수가 얼마나 줄어드는지 보이세요. 피보나치 <code>fib(20)</code> 을 메모 없이 계산할 때와 메모를 붙일 때의 <b>함수 호출 수</b>를 세세요. 메모에 값을 채울 때마다 <code>snap('memo['+n+']', {size, calls}, {n})</code> 을 남기고 <b>[메모 없는 호출 수, 메모 있는 호출 수, 메모 항목 수, 몇 배 적은지(반올림)]</b> 를 돌려주세요.","src":"const N = 20;\n\nfunction memoize() {\n  return [0, 0, 0, 0];\n}\n\nRESULT = memoize();","tests":[{"d":"메모 없이는 21,891번 부른다","js":"RESULT[0]===21891"},{"d":"메모를 붙이면 39번","js":"RESULT[1]===39"},{"d":"메모 항목은 21개","js":"RESULT[2]===21"},{"d":"561배 적다","js":"RESULT[3]===561"},{"d":"메모를 채울 때마다 장면이 남는다","js":"FRAMES.length===21"},{"d":"메모가 하나씩 자란다","js":"FRAMES[20].value.size===21&&FRAMES[0].value.size===1"}],"ex":"메모이제이션이 <b>정당한 이유는 순수성</b>이다 — 같은 입력에 늘 같은 값이니 <b>한 번 계산한 것을 재사용해도 프로그램의 의미가 변하지 않는다</b>(참조 투명성). 그 성질 하나로 호출이 21,891번에서 39번으로 줄어든다. 반대로 순수하지 않은 함수에 캐시를 붙이면 <b>버그가 된다</b>: 시간·난수·DB 조회 결과가 얼어붙거나, 부수 효과가 사라져 로그가 안 남는다. 실무에서는 캐시 키에 <b>모든 입력이 들어갔는지</b>도 확인해야 한다 — 숨은 입력(전역 설정·현재 사용자)이 있으면 그것까지 키에 넣거나, 애초에 <b>인자로 끌어올려야</b> 한다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련이다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠르다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둔다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않는다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려진다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러난다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 본다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈린다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 IV","q":[{"t":"sim","k":"함수형 시뮬레이션","lv":3,"cat":"internals","q":"<b>무한 스트림</b>에서 필요한 만큼만 꺼내세요. 자연수 스트림에 <code>제곱 → 3의 배수만 → 앞의 4개</code> 를 적용할 때, <b>스트림이 실제로 생성한 원소 수</b>를 세세요. 값을 꺼낼 때마다 <code>snap('n='+n, {produced, taken}, {n})</code> 을 남기고 <b>[생성한 원소 수, 결과 배열, 리스트로 먼저 100개를 만들었다면 생성했을 수, 무한 리스트로 같은 일을 하면 어떻게 되는지]</b> 를 돌려주세요. 마지막 값은 <code>'무한 루프'</code> 다.","src":"const TAKE = 4;\n// 자연수 1, 2, 3, ... 을 제곱해 3의 배수만 고른다\n\nfunction lazyStream() {\n  return [0, [], 0, ''];\n}\n\nRESULT = lazyStream();","tests":[{"d":"12개만 생성하면 충분하다","js":"RESULT[0]===12"},{"d":"결과는 9·36·81·144","js":"JSON.stringify(RESULT[1])===JSON.stringify([9,36,81,144])"},{"d":"리스트 방식이었다면 100개를 만들었을 것","js":"RESULT[2]===100"},{"d":"무한 리스트를 먼저 만들면 끝나지 않는다","js":"RESULT[3]==='무한 루프'"},{"d":"꺼낸 원소마다 장면이 남는다","js":"FRAMES.length===12"},{"d":"4개를 채우는 순간 멈춘다","js":"FRAMES[11].value.taken===4"}],"ex":"지연 평가의 진짜 가치는 속도가 아니라 <b>표현할 수 있는 것이 늘어난다</b>는 데 있다 — <b>끝이 없는 것</b>(자연수·이벤트·파일 줄)을 값처럼 다루고, 필요한 만큼만 꺼내 쓸 수 있다. 여기서는 4개를 얻는 데 <b>12개만</b> 만들었다. 같은 일을 리스트로 하려면 '몇 개까지 만들지' 를 <b>미리 정해야</b> 하고(100개), 그 수가 모자라면 답이 틀리고 넘치면 낭비다. 자바스크립트에서는 <b>제너레이터</b>, 자바는 <code>Stream</code>, 파이썬은 <code>itertools</code> 가 이 역할을 한다. 대가는 <b>디버깅이 어렵다</b>는 것 — 값이 언제 계산되는지 눈에 안 보이므로, 부수 효과가 섞이면 순서를 예측하기 힘들어진다."},{"t":"sim","k":"함수형 시뮬레이션","lv":2,"cat":"internals","q":"<code>compose</code> 와 <code>pipe</code> 는 <b>적용 순서가 반대</b>다 — <code>compose(f,g,h)(x) = f(g(h(x)))</code>(오른쪽부터), <code>pipe(f,g,h)(x) = h(g(f(x)))</code>(왼쪽부터). 같은 함수 목록으로 둘을 돌려 <code>snap(방식+' '+단계, {value, applied}, {mode})</code> 를 남기고 <b>[compose 결과, pipe 결과, 두 결과가 같은지, 순서를 바꿔도 결과가 같으려면 필요한 성질]</b> 을 돌려주세요. 마지막 값은 <code>'교환법칙'</code> 이다.","src":"// f: +1  ·  g: ×2  ·  h: -3\nconst FNS = [['+1', function (x) { return x + 1; }],\n             ['×2', function (x) { return x * 2; }],\n             ['-3', function (x) { return x - 3; }]];\nconst X = 5;\n\nfunction order() {\n  return [0, 0, false, ''];\n}\n\nRESULT = order();","tests":[{"d":"compose 는 5 → 2 → 4 → 5","js":"RESULT[0]===5"},{"d":"pipe 는 5 → 6 → 12 → 9","js":"RESULT[1]===9"},{"d":"같은 함수 목록인데 결과가 다르다","js":"RESULT[2]===false"},{"d":"일반적으로 같으려면 교환법칙이 필요하다","js":"RESULT[3]==='교환법칙'"},{"d":"두 방식의 단계가 모두 장면으로 남는다","js":"FRAMES.length===6"},{"d":"중간값은 서로 다르다","js":"FRAMES[0].value.value!==FRAMES[3].value.value"}],"ex":"같은 함수 세 개인데 <b>결과가 5 와 9 로 갈린다</b> — compose 는 <code>-3</code> 부터, pipe 는 <code>+1</code> 부터 적용하기 때문이다. 함수 합성에는 <b>교환법칙이 없으므로</b>(<code>f∘g ≠ g∘f</code>) 순서가 곧 의미다. 그래서 '어느 쪽이 먼저인지' 를 헷갈리면 <b>오류 없이 조용히 틀린 값</b>이 나온다. 실무에서 <code>pipe</code> 를 더 선호하는 이유는 단순하다 — <b>읽는 순서와 실행 순서가 같아서</b> 데이터가 위에서 아래로 흐르는 것처럼 보인다(<code>pipe(정규화, 검증, 저장)</code>). 반대로 수학 표기와 맞추려면 <code>compose</code> 다. 어느 쪽을 쓰든 팀 안에서 <b>하나로 통일</b>하는 것이 실수를 줄인다."},{"t":"sim","k":"함수형 시뮬레이션","lv":4,"cat":"internals","q":"재귀의 <b>스택 깊이</b>를 비교하세요. <b>일반 재귀</b>는 반환 뒤에 할 일이 남아 프레임이 쌓이고(<code>n + rec(n-1)</code>), <b>꼬리 재귀</b>는 누적값을 넘겨 마지막에 호출만 남는다(<code>rec(n-1, acc+n)</code>). 100번 반복할 때 깊이가 바뀔 때마다 <code>snap('n='+n, {depth, acc}, {mode})</code> 를 남기고(10 간격) <b>[일반 재귀의 최대 깊이, 꼬리 재귀를 최적화하면 필요한 깊이, 자바스크립트가 꼬리 호출 최적화를 보장하는지, 대신 쓰는 방법]</b> 을 돌려주세요. 마지막 값은 <code>'반복문'</code> 이다.","src":"const N = 100;\n\nfunction recursion() {\n  return [0, 0, false, ''];\n}\n\nRESULT = recursion();","tests":[{"d":"일반 재귀는 100프레임을 쌓는다","js":"RESULT[0]===100"},{"d":"꼬리 호출이 최적화되면 1프레임","js":"RESULT[1]===1"},{"d":"자바스크립트 엔진은 대체로 보장하지 않는다","js":"RESULT[2]===false"},{"d":"대안은 반복문","js":"RESULT[3]==='반복문'"},{"d":"10 간격으로 장면이 남는다","js":"FRAMES.length===20"},{"d":"일반 재귀의 깊이가 계속 는다","js":"FRAMES[9].value.depth===100"},{"d":"꼬리 재귀 쪽은 깊이가 1로 고정","js":"FRAMES[19].value.depth===1"}],"ex":"차이는 <b>호출한 뒤에 할 일이 남아 있는가</b> 하나다. <code>n + rec(n-1)</code> 은 재귀가 끝나야 덧셈을 할 수 있으니 <b>프레임을 붙들어야</b> 하고, <code>rec(n-1, acc+n)</code> 은 넘겨주고 잊어도 되므로 <b>같은 프레임을 재사용</b>할 수 있다(꼬리 호출 최적화). 문제는 <b>언어와 엔진이 이걸 보장하느냐</b> 다 — 스칼라·하스켈·엘릭서는 보장하지만, <b>자바스크립트는 명세에 있어도 대부분의 엔진이 구현하지 않았고</b> 파이썬·자바도 하지 않는다. 그래서 이 언어들에서는 깊은 재귀를 <b>반복문이나 명시적 스택</b>으로 바꾸는 것이 현실적인 답이다(<code>RangeError: Maximum call stack size exceeded</code> 를 만나기 전에)."},{"t":"sim","k":"함수형 시뮬레이션","lv":4,"cat":"internals","q":"<code>map → filter → map</code> 을 이어 붙이면 <b>단계마다 중간 배열</b>이 생긴다. 세 변환을 <b>하나의 reduce 로 융합</b>하면 원소를 한 번만 훑고 중간 배열이 없다. 방식마다 <code>snap(방식, {passes, arrays, ops}, {mode})</code> 를 남기고 <b>[체이닝의 순회 횟수, 융합의 순회 횟수, 체이닝이 만드는 중간 배열 수, 원소 1,000개일 때 아낀 배열 원소 수]</b> 를 돌려주세요. 필터는 절반을 남긴다.","src":"const N = 1000;\n// map(x*2) → filter(짝수 인덱스) → map(x+1)\n\nfunction transduce() {\n  return [0, 0, 0, 0];\n}\n\nRESULT = transduce();","tests":[{"d":"체이닝은 세 번 순회한다","js":"RESULT[0]===3"},{"d":"융합하면 한 번","js":"RESULT[1]===1"},{"d":"중간 배열이 2개 생긴다","js":"RESULT[2]===2"},{"d":"1,500개의 원소 저장을 아낀다","js":"RESULT[3]===1500"},{"d":"방식마다 장면이 남는다","js":"FRAMES.length===2"},{"d":"융합 쪽은 중간 배열이 0","js":"FRAMES[1].value.arrays===0"}],"ex":"<code>map</code>·<code>filter</code> 체이닝은 <b>읽기 좋지만 메모리를 쓴다</b> — 단계마다 새 배열을 만들어 1,000 + 500 원소를 임시로 붙들고, 배열을 세 번 훑는다. <b>트랜스듀서</b>(또는 한 번의 <code>reduce</code>)는 변환을 <b>합성한 뒤 원소마다 한 번에</b> 적용해 중간 배열을 없앤다. 다만 <b>언제 이게 중요한지</b>를 아는 것이 더 중요하다: 수천 개 수준에서는 차이가 미미하고 <b>가독성이 이긴다</b>. 진짜로 필요한 곳은 <b>원소가 수백만이거나</b>, 스트림처럼 <b>전체를 메모리에 담을 수 없을 때</b>다 — 그래서 자바 <code>Stream</code>·<code>Sequence</code>(코틀린)·제너레이터 파이프라인이 기본적으로 이 방식으로 동작한다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련이다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠르다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둔다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않는다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려진다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러난다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 본다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈린다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}],"ord":10},{"t":"실행형 실전 — 함수를 값으로 다룬다","l":[{"t":"커링·불변 갱신·지연 평가","xp":80,"th":{"sum":"함수형의 도구는 셋 다 '나중에'를 다룬다 — **인자를 나중에**(커링), **복사를 최소로**(구조 공유), **계산을 한 번만**(지연).","body":[{"h":"모으고, 공유하고","t":"커링은 인자를 **새 배열로** 모아 두다가 fn.length 에 이르면 발사한다. 새 배열이라야 부분 적용을 재사용해도 서로 오염되지 않는다. 불변 갱신은 경로 위만 복사하고 나머지 가지는 **참조를 공유**한다 — React 가 === 만으로 변경을 감지하는 근거다."},{"h":"실행 여부는 값과 다른 정보다","t":"한 번만 계산하는 lazy 는 '실행했는가' 를 **플래그로 따로** 기억해야 한다. 결과값으로 판단하면 undefined·null 을 돌려주는 함수에서 매번 다시 실행된다 — 캐시에서 null 을 '없음' 으로 쓰다 겪는 사고와 같은 뿌리다."}],"code":{"c":"// 값이 아니라 플래그로 판단한다\nlet done = false, value;\nif (!done) { value = fn(); done = true; }","cap":"undefined 반환도 '한 번 실행됨' 이다"},"key":["커링은 concat 으로 새 배열 — 재사용 안전","불변 갱신은 경로 위만 복사(구조 공유)","n.z===o.z 가 리렌더 생략의 근거","실행 여부 플래그와 결과값을 분리"]},"q":[{"t":"code","run":"js","k":"커링","cat":"internals","q":"<b>커링</b>을 구현하세요. <code>curry(fn)</code> 은 인자를 나눠 받을 수 있는 함수를 돌려준다. 호출마다 인자를 <b>모으고</b>, 모인 개수가 <code>fn.length</code> 에 이르면 원함수를 호출한다. <code>f(1)(2)(3)</code> 도 <code>f(1,2)(3)</code> 도 같아야 하고, <b>부분 적용을 재사용해도</b> 서로 영향이 없어야 한다.","src":"function curry(fn) {\n  // TODO: fn.length 만큼 모이면 호출\n  return fn;\n}","sol":"function curry(fn) {\n  const step = (args) => (...next) => {\n    const all = args.concat(next);\n    return all.length >= fn.length ? fn(...all) : step(all);\n  };\n  return step([]);\n}","tests":[{"in":"curry((a,b,c)=>a+b+c)(1)(2)(3)","out":"6"},{"in":"curry((a,b,c)=>a+b+c)(1,2)(3)","out":"6"},{"in":"curry((a,b)=>a*b)(4,5)","out":"20"},{"in":"(() => { const add=curry((a,b)=>a+b); const add1=add(1); return [add1(2), add1(10)]; })()","out":"[3,11]"}],"edge":[{"in":"curry((a)=>a*2)(7)","out":"14"},{"in":"curry((a,b,c)=>a+b+c)(1)(2,3)","out":"6"}],"ex":"커링의 핵심은 <b>인자를 배열로 모아 두었다가</b> 충분해지면 원함수를 부르는 것이다. <code>fn.length</code>(선언된 매개변수 수)가 '충분함' 의 기준이다.\n<code>args.concat(next)</code> 로 <b>새 배열</b>을 만드는 것이 재사용의 비결이다. <code>add1 = add(1)</code> 을 여러 번 호출해도 각 호출이 자기 배열을 갖기 때문에 서로를 오염시키지 않는다 — push 로 공유 배열에 쌓으면 두 번째 호출부터 틀어진다.\n<code>fn.length</code> 는 기본값·나머지 매개변수를 <b>세지 않는다</b>. <code>(a, b = 1) => …</code> 의 length 는 1이라 커링이 일찍 발사된다.\n커링은 '설정을 먼저, 데이터를 나중에' 받는 API 를 만들 때 빛난다. <code>log('error')</code> 처럼 부분 적용해 두고 재사용하는 패턴이 대표적이다."},{"t":"code","run":"js","k":"불변 갱신과 구조 공유","cat":"internals","q":"중첩 객체를 <b>불변으로 갱신</b>하는 <code>setIn(obj, path, value)</code> 를 구현하세요. 원본은 그대로 두고, <b>경로 위의 객체만 복사</b>하고 <b>경로 밖의 가지는 그대로 공유</b>한다(구조 공유). 빈 경로면 <code>value</code> 자체를, 중간 경로가 없으면 만들어 가며 넣으세요.","src":"function setIn(obj, path, value) {\n  // TODO: 경로 위만 복사\n  return obj;\n}","sol":"function setIn(obj, path, value) {\n  if (path.length === 0) return value;\n  const [head, ...rest] = path;\n  const base = obj && typeof obj === 'object' ? obj : {};\n  return Object.assign({}, base, { [head]: setIn(base[head], rest, value) });\n}","tests":[{"in":"setIn({a:{b:1},z:{c:2}},['a','b'],9)","out":"{a:{b:9},z:{c:2}}"},{"in":"(() => { const o={a:{b:1},z:{c:2}}; const n2=setIn(o,['a','b'],9); return n2.z===o.z; })()","out":"true"},{"in":"(() => { const o={a:{b:1}}; setIn(o,['a','b'],9); return o.a.b; })()","out":"1"},{"in":"(() => { const o={a:{b:1}}; const n2=setIn(o,['a','b'],9); return n2.a===o.a; })()","out":"false"}],"edge":[{"in":"setIn({x:1},[],5)","out":"5"},{"in":"setIn({},['a','b'],1)","out":"{a:{b:1}}"}],"ex":"불변 갱신은 '전부 복사' 가 아니다. <b>바뀐 경로 위의 객체만</b> 새로 만들고 나머지 가지는 <b>참조를 그대로 공유</b>한다 — 그래서 깊은 트리도 갱신 비용이 경로 길이에 비례한다.\n<code>n.z === o.z</code> 가 true 인 것이 핵심 테스트인다. React 가 <code>===</code> 비교만으로 '이 가지는 안 바뀌었으니 리렌더 생략' 을 판단할 수 있는 근거가 바로 이 구조 공유다.\n<code>obj.a.b = 9</code> 로 직접 고치면 참조가 안 바뀌어 React·Redux 가 <b>변경을 감지하지 못한다</b>. 반대로 <code>JSON.parse(JSON.stringify(o))</code> 전체 복사는 감지는 되지만 모든 가지가 새 참조라 <b>모든 곳이 리렌더</b>된다.\nImmer 는 이 패턴을 Proxy 로 자동화한 것이고, <code>structuredClone</code> 은 공유 없는 전체 복사다 — 셋의 차이를 알고 골라 써야 한다."},{"t":"code","run":"js","k":"지연 평가와 메모이즈","cat":"internals","q":"<b>한 번만 계산하는 지연 값</b> <code>lazy(fn)</code> 을 구현하세요. 돌려준 함수를 처음 부를 때만 <code>fn</code> 을 실행해 결과를 기억하고, 이후엔 기억한 값을 돌려준다. <b><code>fn</code> 이 <code>undefined</code> 를 돌려줘도 다시 실행하면 안 된다</b> — 값이 아니라 <b>실행 여부 플래그</b>로 판단하세요.","src":"function lazy(fn) {\n  let value;\n  return () => {\n    if (value === undefined) value = fn();\n    return value;\n  };\n}","sol":"function lazy(fn) {\n  let done = false, value;\n  return () => {\n    if (!done) { value = fn(); done = true; }\n    return value;\n  };\n}","tests":[{"in":"(() => { let n2=0; const f=lazy(()=>{n2++; return 42;}); f(); f(); return [n2, f()]; })()","out":"[1,42]"},{"in":"(() => { let n2=0; const f=lazy(()=>{n2++;}); f(); f(); return n2; })()","out":"1"},{"in":"(() => { let n2=0; lazy(()=>{n2++;}); return n2; })()","out":"0"},{"in":"lazy(()=>'x')()","out":"'x'"}],"edge":[{"in":"(() => { let n2=0; const f=lazy(()=>{n2++; return null;}); return [f(), f(), n2]; })()","out":"[null,null,1]"},{"in":"(() => { let n2=0; const mk=()=>lazy(()=>++n2); const f=mk(), g=mk(); return [f(), g(), f()]; })()","out":"[1,2,1]"}],"ex":"시작 코드는 그럴듯하지만 <b>값으로 실행 여부를 판단하는</b> 버그가 있다. <code>fn</code> 이 <code>undefined</code> 를 돌려주면 '아직 실행 안 함' 과 구별이 안 되어 <b>매번 다시 실행</b>된다.\n그래서 <code>done</code> 플래그를 <b>따로</b> 둔다. '실행했는가' 와 '결과가 무엇인가' 는 다른 정보이고, 하나의 변수에 욱여넣으면 특정 값에서 무너진다 — 캐시에서 <code>null</code> 을 '없음' 으로 쓰다 당하는 사고와 같은 뿌리다.\n부수효과가 있는 <code>fn</code> 이면 이 버그는 <b>이중 과금·중복 요청</b>이 된다. 테스트의 <code>n2</code> 카운터가 그 시나리오를 흉내 낸 것이다.\n이 패턴이 곧 싱글턴 초기화·<code>lazy val</code>·React 의 <code>useMemo</code> 다. 다인자 버전이 메모이제이션(인자를 키로 한 결과 캐시)다."}]}],"ord":11},{"t":"실행형 실전 — 순수해 보이지만 새는 코드 고치기","l":[{"t":"조합자의 계약이 어긋난 곳","xp":80,"th":{"sum":"조합자는 **작고 대칭인 예제에서 전부 통과한다** — 방향·인자 개수·멈추는 시점이 어긋나도 드러나지 않는다.","body":[{"h":"대칭인 예제가 버그를 숨긴다","t":"`pipe` 와 `compose` 는 방향만 다르므로 `+1` 두 개로 테스트하면 같은 답이 나온다. `takeWhile` 과 `filter` 는 조건 만족 원소가 앞에만 몰려 있으면 같다. 테스트는 반드시 **교환 불가능한 조합**과 **중간에 조건이 끊기는 자료**로 짜야 한다."},{"h":"약속을 절반만 지킨 함수","t":"`once` 는 '한 번만 실행' 과 '**같은 값을 준다**' 두 가지를 약속하는데 뒤를 빠뜨리기 쉽다. `memo` 는 키가 **인자 전체**를 대표해야 하고, `curry` 는 값이 아니라 `args.length` 로 인자 개수를 세야 한다. 셋 다 반환값 하나만 확인하는 테스트를 통과한다."}],"code":{"c":"return xs.reduce((v, f) => f(v), x);   // pipe 는 왼쪽부터\nif (!done) { done = true; value = fn(...args); }\nreturn value;                          // 결과도 보관한다","cap":"계약의 절반만 지키기 쉽다"},"key":["방향은 비대칭 예제로 검증","캐시 키는 인자 전체","once 는 값도 보관","인자 개수는 args.length 로"]},"q":[{"t":"code","run":"js","k":"pipe 인데 순서가 거꾸로다","cat":"debug","q":"함수들을 <b>왼쪽에서 오른쪽으로</b> 이어 붙이는 <code>pipeAll</code> 이다. <code>pipeAll([f, g])(x)</code> 는 <code>g(f(x))</code> 여야 한다. 지금은 변환 순서가 뒤집혀 결과가 엉뚱하다.","src":"function pipeAll(fns) {\n  return x => fns.reduceRight((v, f) => f(v), x);\n}","sol":"function pipeAll(fns) {\n  return x => fns.reduce((v, f) => f(v), x);\n}","tests":[{"in":"pipeAll([n => n + 1, n => n * 2])(3)","out":"8"},{"in":"pipeAll([n => n * 2, n => n + 1])(3)","out":"7"},{"in":"pipeAll([])(5)","out":"5"},{"in":"pipeAll([s => s + 'a', s => s + 'b'])('x')","out":"'xab'"}],"edge":[{"in":"pipeAll([n => n - 1])(1)","out":"0"},{"in":"pipeAll([n => [n], a => a.concat(2)])(1)","out":"[1,2]"}],"ex":"원인: <code>reduceRight</code> 는 <b>오른쪽부터</b> 적용하므로 그건 <code>compose</code> 다. <code>pipe</code> 와 <code>compose</code> 는 방향만 다른 쌍이라 함수가 하나거나 두 함수가 교환 가능하면(둘 다 <code>+1</code> 같은) 결과가 같아, <b>순서가 중요한 조합</b>에서만 드러난다.\n해결: <code>reduce</code> 로 바꾼다. 초깃값이 <code>x</code> 이고 누적값에 함수를 차례로 먹이는 꼴이 <code>pipe</code> 다.\n재발 방지: 두 이름을 코드베이스에서 <b>하나만</b> 쓰는 팀이 많다. 섞어 쓰면 읽는 사람이 매번 방향을 다시 생각해야 하기 때문이다. 테스트는 반드시 <b>교환 불가능한</b> 함수 쌍(<code>+1</code> 과 <code>×2</code>)으로 짜세요 — 대칭인 예제는 방향 버그를 통과시킨다."},{"t":"code","run":"js","k":"메모이즈가 첫 인자만 본다","cat":"debug","q":"인자로 캐시하는 <code>memo</code> 다. 인자가 여러 개일 때도 <b>모든 인자</b>가 같아야 캐시 적중이다. 지금은 두 번째 인자를 바꿔도 <b>옛 결과</b>가 나온다.","src":"function memo(fn) {\n  const seen = new Map();\n  return (...args) => {\n    const key = args[0];\n    if (!seen.has(key)) seen.set(key, fn(...args));\n    return seen.get(key);\n  };\n}","sol":"function memo(fn) {\n  const seen = new Map();\n  return (...args) => {\n    const key = JSON.stringify(args);\n    if (!seen.has(key)) seen.set(key, fn(...args));\n    return seen.get(key);\n  };\n}","tests":[{"in":"(() => { const f = memo((a, b) => a + b); return [f(1, 2), f(1, 5)]; })()","out":"[3,6]"},{"in":"(() => { const f = memo(a => a * 2); return [f(3), f(3), f(4)]; })()","out":"[6,6,8]"},{"in":"(() => { let n = 0; const f = memo((a, b) => { n += 1; return a * b; }); f(2, 3); f(2, 3); return n; })()","out":"1"},{"in":"(() => { const f = memo((a, b) => `${a}-${b}`); return f('x', 'y'); })()","out":"'x-y'"}],"edge":[{"in":"(() => { const f = memo(() => 7); return [f(), f()]; })()","out":"[7,7]"},{"in":"(() => { const f = memo(a => a); return [f(0), f(1)]; })()","out":"[0,1]"}],"ex":"원인: 캐시 키가 <b>첫 인자뿐</b>이라 나머지 인자가 무시된다. 인자가 하나인 함수로만 테스트하면 완벽하게 동작해서, 여러 인자를 받는 함수에 붙이는 순간 <b>조용히 틀린 값</b>을 돌려준다 — 오류가 아니라 옛 답이라 더 찾기 어렵다.\n해결: 인자 전체로 키를 만든다. <code>JSON.stringify(args)</code> 가 간단한 방법이고, 인자가 원시값뿐이면 구분자로 이어 붙여도 된다.\n재발 방지: 메모이즈는 <b>순수 함수에만</b> 붙일 수 있고, 키가 인자 전체를 <b>정확히</b> 대표해야 한다. 객체 인자는 <code>stringify</code> 가 키 순서에 따라 달라지고, 함수·<code>undefined</code> 는 사라진다. 캐시는 메모리 누수의 흔한 원인이기도 하므로 상한이나 <code>WeakMap</code> 을 함께 생각하세요."},{"t":"code","run":"js","k":"once 가 두 번째부터 undefined 를 준다","cat":"debug","q":"함수를 <b>한 번만 실행</b>하고 그 결과를 계속 돌려주는 <code>once</code> 다. 초기화 함수에 붙였더니 <b>두 번째 호출부터 <code>undefined</code></b> 가 나온다.","src":"function once(fn) {\n  let done = false;\n  return (...args) => {\n    if (done) return;\n    done = true;\n    return fn(...args);\n  };\n}","sol":"function once(fn) {\n  let done = false, value;\n  return (...args) => {\n    if (!done) { done = true; value = fn(...args); }\n    return value;\n  };\n}","tests":[{"in":"(() => { const f = once(() => 42); return [f(), f()]; })()","out":"[42,42]"},{"in":"(() => { let n = 0; const f = once(() => { n += 1; return n; }); f(); f(); return n; })()","out":"1"},{"in":"(() => { const f = once(a => a * 2); return [f(3), f(9)]; })()","out":"[6,6]"},{"in":"(() => { const f = once(() => null); return [f(), f()]; })()","out":"[null,null]"}],"edge":[{"in":"(() => { const f = once(() => 0); return [f(), f()]; })()","out":"[0,0]"},{"in":"(() => { const f = once(() => undefined); return [f(), f()]; })()","out":"[undefined,undefined]"}],"ex":"원인: '한 번만 실행' 은 지켰지만 <b>결과를 보관하지 않았다</b>. 두 번째부터는 아무것도 돌려주지 않아, 초기화 결과를 받아 쓰던 코드가 <code>undefined</code> 를 만난다. 첫 호출만 확인하는 테스트로는 절대 안 잡힌다.\n해결: 첫 결과를 변수에 담아 두고 이후에는 그것을 돌려준다. 계약이 '<b>한 번만 실행하고 같은 값을 준다</b>' 라는 점을 테스트 이름에도 적어 두세요.\n재발 방지: <code>once</code>·싱글턴·지연 초기화는 모두 '실행 횟수' 와 '반환값' 두 가지를 약속한다. 하나만 테스트하면 다른 하나가 조용히 깨진다. 그리고 첫 호출이 <b>예외를 던졌을 때</b> 다시 시도할지 그대로 실패로 굳힐지도 정해 두어야 한다 — 초기화 실패가 영구 실패가 되는 사고가 여기서 나온다."},{"t":"code","run":"js","k":"zip 이 짧은 쪽을 넘어간다","cat":"debug","q":"두 배열을 함수로 짝지어 합치는 <code>zipWith</code> 다. 길이가 다르면 <b>짧은 쪽에 맞춰</b> 끝내야 한다. 지금은 뒤쪽에 <code>NaN</code> 이 섞여 나온다.","src":"function zipWith(f, a, b) {\n  return a.map((x, i) => f(x, b[i]));\n}","sol":"function zipWith(f, a, b) {\n  const n = Math.min(a.length, b.length);\n  return Array.from({ length: n }, (_, i) => f(a[i], b[i]));\n}","tests":[{"in":"zipWith((x, y) => x + y, [1,2,3], [10,20,30])","out":"[11,22,33]"},{"in":"zipWith((x, y) => x + y, [1,2,3], [10])","out":"[11]"},{"in":"zipWith((x, y) => x + y, [1], [10,20,30])","out":"[11]"},{"in":"zipWith((x, y) => [x, y], [1,2], ['a','b'])","out":"[[1,'a'],[2,'b']]"}],"edge":[{"in":"zipWith((x, y) => x + y, [], [1,2])","out":"[]"},{"in":"zipWith((x, y) => x * y, [2,3], [4])","out":"[8]"}],"ex":"원인: <code>a.map</code> 은 <b>첫 배열의 길이</b>만큼 돈다. 두 번째 배열이 짧으면 <code>b[i]</code> 가 <code>undefined</code> 가 되어 <code>NaN</code> 이나 <code>'1undefined'</code> 같은 값이 조용히 섞인다. 길이가 같은 예제로만 테스트하면 통과한다.\n해결: 두 길이의 <b>최솟값</b>만큼 돈다. 반대 정책(긴 쪽에 맞추고 빈 자리는 기본값)을 쓰려면 그 기본값을 인자로 받아 <b>계약에 드러내세요</b>.\n재발 방지: 두 자료를 나란히 도는 코드는 언제나 '<b>길이가 다르면 어떻게 하는가</b>' 를 먼저 정해야 한다. 조용히 <code>undefined</code> 를 흘리는 것은 선택지가 아니다 — 짧은 쪽에 맞추거나, 기본값을 채우거나, 오류로 거절하거나 셋 중 하나다."},{"t":"code","run":"js","k":"groupBy 가 프로토타입 키에 걸린다","cat":"debug","q":"키 함수로 묶는 <code>groupBy</code> 다. 사용자 입력에서 나온 문자열이 키가 될 수 있다. 지금은 키가 <code>'constructor'</code> 인 자료가 들어오면 <b>이상한 오류</b>가 난다.","src":"function groupBy(xs, keyOf) {\n  const out = {};\n  for (const x of xs) {\n    if (!out[keyOf(x)]) out[keyOf(x)] = [];\n    out[keyOf(x)].push(x);\n  }\n  return out;\n}","sol":"function groupBy(xs, keyOf) {\n  const out = Object.create(null);\n  for (const x of xs) {\n    const k = keyOf(x);\n    if (!Object.prototype.hasOwnProperty.call(out, k)) out[k] = [];\n    out[k].push(x);\n  }\n  return out;\n}","tests":[{"in":"groupBy(['a','bb','c'], s => s.length)","out":"{1:['a','c'], 2:['bb']}"},{"in":"groupBy(['constructor'], s => s)","out":"{constructor:['constructor']}"},{"in":"groupBy([], s => s)","out":"{}"},{"in":"groupBy(['toString','x'], s => s)","out":"{toString:['toString'], x:['x']}"}],"edge":[{"in":"groupBy([1,2,3], n => n % 2)","out":"{0:[2], 1:[1,3]}"},{"in":"Object.keys(groupBy(['__proto__','a'], s => s))","out":"['__proto__','a']"}],"ex":"원인: 보통 객체는 <code>Object.prototype</code> 을 물려받는다. <code>out['constructor']</code> 는 아직 아무것도 안 넣었는데도 <b>함수를 돌려주므로</b> <code>if (!out[k])</code> 가 거짓이 되어 배열을 만들지 않고 그 함수에 <code>push</code> 를 시도한다. <code>'__proto__'</code> 는 더 나빠서 대입이 <b>프로토타입 자체</b>를 건드린다.\n해결: <code>Object.create(null)</code> 로 <b>물려받은 것이 없는</b> 객체를 만들고, 존재 확인은 <code>hasOwnProperty</code> 로 한다. <code>Map</code> 을 쓰면 이 문제가 아예 없다.\n재발 방지: <b>바깥에서 온 문자열이 객체 키가 되는</b> 모든 자리가 이 함정이다 — 집계·캐시·설정 병합·질의 파라미터. 프로토타입 오염은 여기서 시작해 애플리케이션 전역의 동작을 바꾸는 취약점이 된다. 사전이 필요하면 <code>Map</code> 을 기본으로 삼으세요."},{"t":"code","run":"js","k":"takeWhile 이 필터로 구현됐다","cat":"debug","q":"조건이 <b>처음 거짓이 되는 순간 멈추는</b> <code>takeWhile</code> 다. 지금은 뒤쪽에 있는 조건 만족 원소까지 함께 나와, 정렬된 자료의 앞부분만 자르려던 의도가 깨진다.","src":"function takeWhile(xs, ok) {\n  return xs.filter(ok);\n}","sol":"function takeWhile(xs, ok) {\n  const out = [];\n  for (const x of xs) {\n    if (!ok(x)) break;\n    out.push(x);\n  }\n  return out;\n}","tests":[{"in":"takeWhile([1,2,9,3], n => n < 5)","out":"[1,2]"},{"in":"takeWhile([1,2,3], n => n < 5)","out":"[1,2,3]"},{"in":"takeWhile([9,1,2], n => n < 5)","out":"[]"},{"in":"takeWhile([], n => true)","out":"[]"}],"edge":[{"in":"takeWhile([0,1,2], n => n === 0)","out":"[0]"},{"in":"takeWhile([5,5,5], n => n < 5)","out":"[]"}],"ex":"원인: <code>filter</code> 는 <b>전부 훑어</b> 조건을 만족하는 것을 모은다. <code>takeWhile</code> 은 <b>처음 거짓에서 멈춘다</b>. 조건을 만족하는 원소가 앞에만 몰려 있는 자료로 테스트하면 두 결과가 같아서 그냥 지나간다.\n해결: 반복문에서 <code>break</code> 로 멈춘다. 멈춘다는 것은 <b>뒤를 보지 않는다</b>는 뜻이라, 무한 수열이나 비싼 계산에서는 성능 차이도 크다.\n재발 방지: <code>filter</code>·<code>takeWhile</code>·<code>find</code>·<code>some</code> 는 '언제 멈추는가' 가 다르다. 테스트는 반드시 <b>조건이 중간에 끊겼다 다시 참이 되는</b> 자료로 짜세요 — 이 한 줄이 네 함수를 구분해 준다."}]},{"t":"겉보기에 순수한데 새는 곳","xp":80,"th":{"sum":"'불변' 과 '원본 보존' 은 **반환값에 드러나지 않는 계약**이라, 따로 테스트하지 않으면 조용히 깨진다.","body":[{"h":"한 겹만 얼고 한 겹만 복사된다","t":"`Object.freeze` 는 한 겹만 얼고, `shift`·`sort`·`splice` 는 원본을 바꾼다. 비엄격 모드에서 언 객체에 대입하면 **오류 없이 무시**되므로, 테스트는 '오류가 나는가' 가 아니라 '**값이 그대로인가**' 로 확인해야 한다. 바꾸는 메서드와 새로 만드는 메서드를 갈라 두고, 앞의 것은 복사한 뒤에만 쓴다."},{"h":"빈칸과 바깥 입력","t":"보통 객체는 `Object.prototype` 을 물려받아 `'constructor'` 가 이미 있는 것처럼 보인다 — 바깥 문자열이 키가 되는 자리는 `Object.create(null)` 이나 `Map` 을 쓴다. 전진 폭이 변수인 반복문은 **0 가드**가 없으면 멈추지 않고, 깊이 인자를 안 줄이는 재귀는 바닥까지 판다."}],"code":{"c":"const out = Object.create(null);\nif (!(n >= 1)) return [];      // NaN 도 함께 걸린다","cap":"가드는 반복문 앞에"},"key":["동결·복사는 한 겹뿐","'원본이 그대로인가' 를 테스트한다","바깥 문자열 키는 Map 으로","전진 폭이 변수면 0 을 막는다"]},"q":[{"t":"code","run":"js","k":"깊이 지정 평탄화가 한 겹 더 판다","cat":"debug","q":"<code>depth</code> 겹까지만 펴는 <code>flatten</code> 이다. <code>depth</code> 가 1 이면 <b>한 겹</b>만 펴야 하는데, 안쪽까지 전부 펴져 구조가 사라진다.","src":"function flatten(xs, depth) {\n  if (depth < 0) return xs;\n  return xs.reduce((out, x) => out.concat(Array.isArray(x) ? flatten(x, depth) : x), []);\n}","sol":"function flatten(xs, depth) {\n  if (depth <= 0) return xs.slice();\n  return xs.reduce((out, x) => out.concat(Array.isArray(x) ? flatten(x, depth - 1) : x), []);\n}","tests":[{"in":"flatten([1,[2,[3,[4]]]], 1)","out":"[1,2,[3,[4]]]"},{"in":"flatten([1,[2,[3,[4]]]], 2)","out":"[1,2,3,[4]]"},{"in":"flatten([1,[2]], 0)","out":"[1,[2]]"},{"in":"flatten([1,2], 5)","out":"[1,2]"}],"edge":[{"in":"flatten([], 3)","out":"[]"},{"in":"flatten([[[1]]], 3)","out":"[1]"}],"ex":"원인: 재귀에 <b><code>depth - 1</code> 을 안 넘겼다</b>. 깊이가 줄지 않으니 바닥까지 내려가고, <code>depth &lt; 0</code> 이라는 종료 조건은 영영 참이 되지 않는다. 두 겹짜리 자료로만 테스트하면 1 과 무한이 같은 답을 내서 통과한다.\n해결: 재귀 호출에 줄어든 깊이를 넘기고, 종료 조건을 <code>depth &lt;= 0</code> 으로 맞춘다. 이때 <code>slice()</code> 로 복사해 돌려주면 반환값이 입력과 <b>같은 객체를 공유하지 않는다</b>.\n재발 방지: 재귀에서 '줄어드는 값' 을 안 넘기는 것은 무한 재귀의 대표 원인이다. 종료 조건과 <b>줄어드는 인자</b>는 언제나 짝으로 확인하세요. 그리고 깊이 인자를 받는 함수는 <b>0 과 1</b> 을 반드시 테스트에 넣어야 한다."},{"t":"code","run":"js","k":"chunk 가 0 에서 멈추지 않는다","cat":"debug","q":"배열을 <code>n</code> 개씩 자르는 <code>chunk</code> 다. <code>n</code> 이 1 보다 작으면 <b>빈 배열</b>을 돌려줘야 한다. 지금은 설정값이 0 으로 들어오면 화면이 그대로 멈춘다.","src":"function chunk(xs, n) {\n  const out = [];\n  for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n));\n  return out;\n}","sol":"function chunk(xs, n) {\n  if (!(n >= 1)) return [];\n  const out = [];\n  for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n));\n  return out;\n}","tests":[{"in":"chunk([1,2,3,4,5], 2)","out":"[[1,2],[3,4],[5]]"},{"in":"chunk([1,2,3], 0)","out":"[]"},{"in":"chunk([1,2,3], 5)","out":"[[1,2,3]]"},{"in":"chunk([], 2)","out":"[]"}],"edge":[{"in":"chunk([1,2,3], -1)","out":"[]"},{"in":"chunk([1], 1)","out":"[[1]]"}],"ex":"원인: <code>i += 0</code> 은 <b>전진하지 않는다</b>. 반복문이 끝나지 않고 배열에 빈 조각을 무한히 밀어 넣어, 오류가 아니라 <b>메모리를 다 쓰고 탭이 죽는</b> 방식으로 실패한다. 브라우저에서는 이 실패가 오류 로그조차 남기지 않는다.\n해결: 전진 폭이 1 이상인지 <b>먼저</b> 확인한다. <code>!(n &gt;= 1)</code> 로 적으면 <code>NaN</code> 과 <code>undefined</code> 도 함께 걸러진다 — <code>n &lt; 1</code> 은 <code>NaN</code> 을 통과시킨다.\n재발 방지: 전진 폭이 <b>변수</b>인 반복문에는 언제나 가드가 필요하다. 같은 함정이 청킹의 겹침(<code>overlap &gt;= size</code>), 페이지 크기 0, 재시도 간격 0 에도 있다. 설정값에서 온 숫자는 <b>범위를 검증한 뒤에</b> 반복문에 넣으세요."},{"t":"code","run":"js","k":"동결이 한 겹만 걸린다","cat":"debug","q":"객체를 <b>중첩까지 전부</b> 얼리는 <code>deepFreeze</code> 다. 지금은 안쪽 객체가 그대로 수정되어, 공유 설정이 요청 사이에 오염된다.","src":"function deepFreeze(obj) {\n  return Object.freeze(obj);\n}","sol":"function deepFreeze(obj) {\n  if (obj === null || typeof obj !== 'object') return obj;\n  for (const k of Object.keys(obj)) deepFreeze(obj[k]);\n  return Object.freeze(obj);\n}","tests":[{"in":"(() => { const o = deepFreeze({a:{b:1}}); try { o.a.b = 2; } catch (e) {} return o.a.b; })()","out":"1"},{"in":"(() => { const o = deepFreeze({a:1}); try { o.a = 2; } catch (e) {} return o.a; })()","out":"1"},{"in":"Object.isFrozen(deepFreeze({a:{b:{c:1}}}).a.b)","out":"true"},{"in":"deepFreeze(5)","out":"5"}],"edge":[{"in":"Object.isFrozen(deepFreeze({}))","out":"true"},{"in":"(() => { const o = deepFreeze({a:[1,2]}); try { o.a.push(3); } catch (e) {} return o.a.length; })()","out":"2"}],"ex":"원인: <code>Object.freeze</code> 는 <b>한 겹만</b> 얼린다. 바깥 객체의 키는 못 바꾸지만 <code>o.a.b = 2</code> 는 그대로 통한다. 얕은 복사와 똑같은 함정이고, 그래서 '<b>불변이라고 믿었는데 바뀐</b>' 버그가 생긴다.\n해결: 값이 객체이면 <b>먼저 안쪽을 얼리고</b> 자신을 언다. 원시값은 그대로 돌려준다. 순환 참조가 있으면 무한 재귀가 되므로 실무에서는 방문 집합을 함께 쓴다.\n재발 방지: 비엄격 모드에서 언 객체에 대입하면 <b>조용히 무시</b>되고 오류가 나지 않는다(모듈과 엄격 모드에서는 예외). 그래서 테스트는 '오류가 나는가' 가 아니라 '<b>값이 그대로인가</b>' 로 확인해야 한다. 애초에 공유 상태를 만들지 않는 쪽이 더 나은 답일 때가 많다."},{"t":"code","run":"js","k":"partition 이 원본을 함께 바꾼다","cat":"debug","q":"조건으로 두 묶음으로 가르는 <code>partition</code> 이다. <b>원본 배열을 바꾸면 안 된다</b>. 지금은 한 번 호출하고 나면 원본이 비어 버려 두 번째 호출부터 결과가 이상하다.","src":"function partition(xs, ok) {\n  const yes = [], no = [];\n  while (xs.length) {\n    const x = xs.shift();\n    (ok(x) ? yes : no).push(x);\n  }\n  return [yes, no];\n}","sol":"function partition(xs, ok) {\n  const yes = [], no = [];\n  for (const x of xs) (ok(x) ? yes : no).push(x);\n  return [yes, no];\n}","tests":[{"in":"partition([1,2,3,4], n => n % 2 === 0)","out":"[[2,4],[1,3]]"},{"in":"(() => { const a = [1,2,3]; partition(a, n => n > 1); return a; })()","out":"[1,2,3]"},{"in":"partition([], n => true)","out":"[[],[]]"},{"in":"partition([1,2], n => false)","out":"[[],[1,2]]"}],"edge":[{"in":"partition([5], n => n === 5)","out":"[[5],[]]"},{"in":"(() => { const a = [1,2]; const r1 = partition(a, n => n > 0); const r2 = partition(a, n => n > 0); return [r1[0].length, r2[0].length]; })()","out":"[2,2]"}],"ex":"원인: <code>shift</code> 는 <b>원본에서 원소를 꺼낸다</b>. 결과는 맞게 나오지만 호출자의 배열이 비어, 같은 배열로 두 번째 작업을 하면 아무것도 없다. 반환값만 검사하는 테스트로는 절대 안 잡힌다.\n해결: 읽기만 하는 <code>for...of</code> 로 돈다. 굳이 꺼내야 한다면 <code>xs.slice()</code> 로 복사본을 만들어 그것을 소비하세요.\n재발 방지: 자바스크립트의 배열 메서드는 <b>바꾸는 것</b>(<code>sort</code>·<code>reverse</code>·<code>splice</code>·<code>push</code>·<code>shift</code>)과 <b>새로 만드는 것</b>(<code>map</code>·<code>filter</code>·<code>slice</code>·<code>concat</code>)으로 갈린다. 순수 함수를 쓴다면 앞의 목록은 <b>복사한 뒤에만</b> 쓴다. 그리고 '원본이 그대로인가' 를 테스트로 못 박으세요 — 이 계약은 반환값에 드러나지 않는다."},{"t":"code","run":"js","k":"커링이 인자 개수를 안 센다","cat":"debug","q":"두 자리 함수를 커링하는 <code>curry2</code> 다. <code>f(1)(2)</code> 와 <code>f(1, 2)</code> 가 <b>모두</b> 동작해야 한다. 지금은 두 인자를 한 번에 넘기면 함수가 그대로 나온다.","src":"function curried(fn) {\n  return a => b => fn(a, b);\n}","sol":"function curried(fn) {\n  return function step(...args) {\n    if (args.length >= 2) return fn(args[0], args[1]);\n    return b => fn(args[0], b);\n  };\n}","tests":[{"in":"curried((a, b) => a + b)(1)(2)","out":"3"},{"in":"curried((a, b) => a + b)(1, 2)","out":"3"},{"in":"curried((a, b) => a * b)(3)(4)","out":"12"},{"in":"curried((a, b) => `${a}${b}`)('x', 'y')","out":"'xy'"}],"edge":[{"in":"typeof curried((a, b) => a + b)(1)","out":"'function'"},{"in":"curried((a, b) => (a || 0) + (b || 0))(0, 0)","out":"0"}],"ex":"원인: 반환한 함수가 <b>인자를 하나만</b> 받는다. <code>f(1, 2)</code> 로 부르면 두 번째 인자는 그냥 버려지고 '아직 덜 채워진 함수' 가 나온다. 오류가 아니라 <b>함수 객체</b>가 돌아오므로, 그 값을 문자열로 이어 붙이거나 비교하는 자리에서야 이상함이 드러난다.\n해결: 받은 인자 개수를 세어 <b>충분하면 바로 호출</b>하고, 모자라면 나머지를 기다리는 함수를 돌려준다. 실무 라이브러리는 <code>fn.length</code> 로 목표 개수를 읽어 임의 자리 수를 지원한다.\n재발 방지: 커링의 가치는 '<b>부분 적용</b>' 이지 문법이 아니다. 두 호출 방식이 같은 답을 내는지 반드시 테스트하고, 인자가 <code>0</code>·<code>undefined</code> 처럼 거짓 같은 값일 때도 '덜 받았다' 로 오해하지 않는지 확인하세요 — 개수는 <b>값이 아니라 <code>args.length</code></b> 로 세야 한다."},{"t":"code","run":"js","k":"누산기 없는 재귀가 스택을 넘긴다","cat":"debug","q":"1 부터 <code>n</code> 까지 더하는 재귀 함수다. 작은 값은 맞는데 <code>n</code> 이 커지면 <b>스택 넘침</b>으로 죽는다. 재귀 형태는 유지하되 큰 <code>n</code> 도 버텨야 한다.","src":"function sumTo(n) {\n  if (n <= 0) return 0;\n  return n + sumTo(n - 1);\n}","sol":"function sumTo(n) {\n  let acc = 0;\n  const step = k => { while (k > 0) { acc += k; k -= 1; } return acc; };\n  return step(n);\n}","tests":[{"in":"sumTo(0)","out":"0"},{"in":"sumTo(10)","out":"55"},{"in":"sumTo(100000)","out":"5000050000"},{"in":"sumTo(1)","out":"1"}],"edge":[{"in":"sumTo(-5)","out":"0"},{"in":"sumTo(3)","out":"6"}],"ex":"원인: <code>n + sumTo(n - 1)</code> 은 <b>꼬리 호출이 아니다</b> — 재귀에서 돌아온 뒤에 더해야 하므로 호출마다 스택 프레임이 남는다. 10만 번이면 스택을 넘겨 <code>RangeError</code> 로 죽는다. 작은 입력만 테스트하면 완벽해 보인다.\n해결: 남은 일을 <b>누산기</b>로 옮기면 돌아와서 할 일이 없어진다. 자바스크립트 엔진은 꼬리 호출 최적화를 대부분 지원하지 않으므로, 누산기 꼴을 <b>반복문으로</b> 펴는 것이 실전의 답이다.\n재발 방지: 재귀 깊이가 <b>입력 크기에 비례</b>하면 언제든 터질 수 있다. 깊이가 <code>log n</code> 인 재귀(이진 탐색·병합 정렬)는 안전하고, 선형인 재귀(리스트 순회)는 반복문으로 펴세요. 테스트에는 <b>10만 단위 입력</b>을 하나 넣어 두면 이 한계가 배포 전에 드러난다."}]}],"ord":12}]);
